((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).el = window.CARDS_BY_LANG.el || {}).film = [{"name":"Ο Νονός","emoji":"🍊","meta":["γκανγκστερικό δράμα","1972","Φράνσις Φορντ Κόπολα"],"description":"Η σικελική μαφιόζικη οικογένεια Κορλεόνε στη Νέα Υόρκη της δεκαετίας του 1940, όπου τη θέση του γερασμένου νονού παίρνει ο μικρότερος γιος του. Η μεταφορά του μυθιστορήματος του Μάριο Πούζο έγινε το μέτρο σύγκρισης για κάθε ταινία με γκάνγκστερ.","fact":"Η φράση «Θα του κάνω μια προσφορά που δεν θα μπορεί να αρνηθεί» είναι από τις πιο γνωστές στην ιστορία του κινηματογράφου.","wiki_en":"The Godfather"},{"name":"The Shawshank Redemption","emoji":"⛓️","meta":["δράμα","1994","Φρανκ Ντάραμποντ"],"description":"Ένας τραπεζίτης καταδικάζεται άδικα για τον φόνο της γυναίκας του και καταλήγει σε μια σκληρή φυλακή, όπου στήριγμα γίνεται η φιλία του με έναν συγκρατούμενο. Η μεταφορά της νουβέλας του Στίβεν Κινγκ κρατιέται χρόνια στην κορυφή της κατάταξης του IMDb.","fact":"Στις αίθουσες απέτυχε, αλλά χάρη στις τηλεοπτικές επαναλήψεις και το βίντεο έγινε μια από τις ταινίες που ξαναβλέπει ο κόσμος περισσότερο.","wiki_en":"The Shawshank Redemption"},{"name":"Pulp Fiction","emoji":"💼","meta":["αστυνομική κομεντί","1994","Κουέντιν Ταραντίνο"],"description":"Μπλεγμένες ιστορίες γκάνγκστερ, ενός πυγμάχου και δύο μικροκακοποιών στο Λος Άντζελες, που δεν ξετυλίγονται με τη σειρά. Η ταινία έμεινε για τη σπασμένη χρονολογική δομή, τους θρασείς διαλόγους και τη μουσική της, και επανέφερε τον Τζον Τραβόλτα στις οθόνες.","fact":"Το περιεχόμενο της βαλίτσας που φωτίζεται δεν δείχνεται ποτέ — ο θεατής καλείται να το φανταστεί μόνος.","wiki_en":"Pulp Fiction"},{"name":"Forrest Gump","emoji":"🍫","meta":["δράμα","1994","Ρόμπερτ Ζεμέκις"],"description":"Ένας αγαθός νεαρός από την Αλαμπάμα βρίσκεται κατά τύχη μέσα στα κορυφαία γεγονότα της αμερικανικής ιστορίας του δεύτερου μισού του 20ού αιώνα. Η ταινία δένει το αθώο χιούμορ με τη νοσταλγία και χάρισε στην ποπ κουλτούρα αμέτρητες ατάκες.","fact":"Η ατάκα του Φόρεστ για το κουτί με τα σοκολατάκια — ποτέ δεν ξέρεις τι θα σου τύχει — έγινε καθημερινή έκφραση.","wiki_en":"Forrest Gump"},{"name":"The Matrix","emoji":"💊","meta":["επιστημονική φαντασία","1999","Οι Γουατσόφσκι"],"description":"Ένας χάκερ ανακαλύπτει ότι ο κόσμος που ξέρει είναι μια προσομοίωση υπολογιστή και ότι η αληθινή πραγματικότητα είναι εντελώς αλλιώτικη, και μπαίνει στην εξέγερση κατά των μηχανών. Η ταινία άλλαξε τα ειδικά εφέ με το bullet time και επέβαλε τα μαύρα δερμάτινα παλτά.","fact":"Η επιλογή ανάμεσα στο κόκκινο και το μπλε χάπι έγινε σύμβολο της επιλογής ανάμεσα σε ένα άνετο ψέμα και μια δυσάρεστη αλήθεια.","wiki_en":"The Matrix"},{"name":"Fight Club","emoji":"🧼","meta":["δράμα","1999","Ντέιβιντ Φίντσερ"],"description":"Ένας ανώνυμος υπάλληλος γραφείου, που τον τρώει η αϋπνία και η απάθεια, γνωρίζει έναν χαρισματικό πωλητή σαπουνιών και μαζί του στήνει υπόγειες λέσχες πυγμαχίας. Η μεταφορά του μυθιστορήματος του Τσακ Παλάνιουκ απογοήτευσε αρχικά τους κριτικούς και μετά έγινε καλτ.","fact":"Ο πρώτος κανόνας της Λέσχης — δεν μιλάς για τη Λέσχη — έγινε παροιμιώδης φράση πολύ πιο πέρα από τον κινηματογράφο.","wiki_en":"Fight Club"},{"name":"Inception","emoji":"🌀","meta":["επιστημονική φαντασία","2010","Κρίστοφερ Νόλαν"],"description":"Ένας ειδικός στην εισβολή σε ξένα όνειρα αναλαμβάνει όχι να κλέψει μια ιδέα αλλά να τη φυτέψει, κατεβαίνοντας για αυτό σε πολλά επίπεδα ύπνου ταυτόχρονα. Η δομή με τα όνειρα μέσα σε όνειρα και το ανοιχτό φινάλε άφησαν τους θεατές να μαλώνουν.","fact":"Η σβούρα που γυρίζει ξανά και ξανά ο ήρωας έγινε το σύμβολο της αμφισημίας: ο καθένας αποφασίζει μόνος αν σταμάτησε.","wiki_en":"Inception"},{"name":"Interstellar","emoji":"🚀","meta":["επιστημονική φαντασία","2014","Κρίστοφερ Νόλαν"],"description":"Μια οικολογική καταστροφή φέρνει την ανθρωπότητα στα πρόθυρα της εξαφάνισης και ένας παλιός πιλότος περνά μέσα από μια σκουληκότρυπα ψάχνοντας κατοικήσιμο πλανήτη, αφήνοντας την κόρη του στη Γη. Στην ταινία συμβούλευε ο φυσικός Κιπ Θορν.","fact":"Επειδή ο χρόνος κυλά πιο αργά κοντά στη μαύρη τρύπα, μία ώρα σε έναν μακρινό πλανήτη αντιστοιχεί σε χρόνια πάνω στη Γη.","wiki_en":"Interstellar (film)"},{"name":"The Dark Knight","emoji":"🦇","meta":["ταινία δράσης","2008","Κρίστοφερ Νόλαν"],"description":"Ο Μπάτμαν, ο αστυνόμος Γκόρντον και ο εισαγγελέας Χάρβεϊ Ντεντ προσπαθούν να σταματήσουν έναν αναρχικό κακοποιό με το παρατσούκλι Τζόκερ, που περιφρονεί κάθε κανόνα του Γκόθαμ. Η ταινία ξανάγραψε το σινεμά των υπερηρώων ως σκοτεινό αστυνομικό θρίλερ.","fact":"Ο Χιθ Λέτζερ, που πέθανε πριν από την πρεμιέρα, πήρε μετά θάνατον Όσκαρ για τον ρόλο του Τζόκερ.","wiki_en":"The Dark Knight"},{"name":"Ο Άρχοντας των Δαχτυλιδιών: Η Συντροφιά του Δαχτυλιδιού","emoji":"💍","meta":["ταινία φαντασίας","2001","Πίτερ Τζάκσον"],"description":"Ο χόμπιτ Φρόντο παίρνει μια επικίνδυνη αποστολή — να καταστρέψει το Δαχτυλίδι της Δύναμης — και ξεκινά μαζί με μια ανόμοια συντροφιά ένα μακρύ ταξίδι στη Μέση Γη. Το πρώτο μέρος της τριλογίας εντυπωσίασε με τα γυρίσματα στη Νέα Ζηλανδία και την προσοχή στη λεπτομέρεια.","fact":"Και οι τρεις ταινίες της τριλογίας γυρίστηκαν σχεδόν ταυτόχρονα, σε διάστημα πάνω από ένα χρόνο.","wiki_en":"The Lord of the Rings: The Fellowship of the Ring"},{"name":"Ο Χάρι Πότερ και η Φιλοσοφική Λίθος","emoji":"⚡","meta":["ταινία φαντασίας","2001","Κρις Κολόμπους"],"description":"Ένα ορφανό αγόρι μαθαίνει ότι είναι μάγος και πηγαίνει να σπουδάσει στη σχολή μαγείας Χόγκουαρτς, όπου κάνει φίλους και ξεσκεπάζει ένα οικογενειακό μυστικό. Η πρώτη ταινία από τα βιβλία της Τζ. Κ. Ρόουλινγκ ξεκίνησε μια από τις πιο κερδοφόρες σειρές του σινεμά.","fact":"Για τους τρεις πρωταγωνιστικούς ρόλους οι δημιουργοί είδαν χιλιάδες παιδιά σε όλη τη Βρετανία.","wiki_en":"Harry Potter and the Philosopher's Stone (film)"},{"name":"Ο Πόλεμος των Άστρων: Επεισόδιο IV – Μια Νέα Ελπίδα","emoji":"⚔️","meta":["επιστημονική φαντασία","1977","Τζορτζ Λούκας"],"description":"Ένας νέος αγρότης από έναν έρημο πλανήτη μπλέκεται στον πόλεμο των επαναστατών κατά της γαλαξιακής Αυτοκρατορίας και μαθαίνει ποιο είναι το πεπρωμένο του. Η ταινία του Τζορτζ Λούκας άλλαξε τα ειδικά εφέ και τον ήχο και γέννησε μια τεράστια κινηματογραφική σειρά.","fact":"Πριν από την πρεμιέρα σχεδόν κανείς δεν πίστευε στην επιτυχία της και οι διανομείς την έβγαλαν σε λίγες μόνο κόπιες.","wiki_en":"Star Wars (film)"},{"name":"Τιτανικός","emoji":"🚢","meta":["ρομαντικό δράμα","1997","Τζέιμς Κάμερον"],"description":"Πάνω στο πολυτελές και υποτίθεται αβύθιστο υπερωκεάνιο, ένας άπορος ζωγράφος και μια κοπέλα της υψηλής κοινωνίας ερωτεύονται, ενώ το πλοίο πλέει προς την καταστροφή. Για χρόνια η ταινία παρέμενε η εμπορικότερη στην ιστορία του κινηματογράφου.","fact":"Το My Heart Will Go On με τη Σελίν Ντιόν έγινε μια από τις πιο αναγνωρίσιμες μπαλάντες που γράφτηκαν ποτέ για ταινία.","wiki_en":"Titanic (1997 film)"},{"name":"Avatar","emoji":"🌿","meta":["επιστημονική φαντασία","2009","Τζέιμς Κάμερον"],"description":"Ένας πρώην πεζοναύτης χειρίζεται ένα τεχνητό σώμα Να'βι για να εντοπίσει κοιτάσματα στον πλανήτη Πανδώρα, αλλά σιγά σιγά δένεται με τον πολιτισμό των κατοίκων του. Η ταινία εντυπωσίασε με το τρισδιάστατο και τη σύλληψη κίνησης, φτιάχνοντας έναν ολόκληρο εξωγήινο κόσμο.","fact":"Έγινε η εμπορικότερη ταινία παγκοσμίως και κράτησε αυτό το ρεκόρ για πολλά χρόνια.","wiki_en":"Avatar (2009 film)"},{"name":"Ιουρασικό Πάρκο","emoji":"🦖","meta":["επιστημονική φαντασία","1993","Στίβεν Σπίλμπεργκ"],"description":"Σε ένα απομονωμένο νησί επιστήμονες αναπλάθουν δεινόσαυρους από αρχαίο DNA για ένα πάρκο αναψυχής, αλλά τα συστήματα ασφαλείας πέφτουν και οι επισκέπτες μένουν μόνοι με τα θηρία. Η ταινία του Σπίλμπεργκ έκανε άλμα στην ψηφιακή εικόνα.","fact":"Μέρος των δεινοσαύρων της ταινίας είναι ανιματρονικά μοντέλα σε φυσικό μέγεθος και όχι μόνο ψηφιακά γραφικά.","wiki_en":"Jurassic Park (film)"},{"name":"Τα Σαγόνια του Καρχαρία","emoji":"🦈","meta":["θρίλερ","1975","Στίβεν Σπίλμπεργκ"],"description":"Ένα μικρό παραθαλάσσιο θέρετρο τρομοκρατείται από έναν τεράστιο λευκό καρχαρία και ο σερίφης βγαίνει στη θάλασσα μαζί με έναν ωκεανογράφο και έναν κυνηγό για να τον σταματήσει. Η ταινία θεωρείται η πρώτη πραγματική καλοκαιρινή εμπορική επιτυχία.","fact":"Ο μηχανικός καρχαρίας χάλαγε συνεχώς, οπότε ο Σπίλμπεργκ τον κράτησε πιο πολύ εκτός κάδρου — και η αγωνία μεγάλωσε.","wiki_en":"Jaws (film)"},{"name":"E.T. ο Εξωγήινος","emoji":"🛸","meta":["επιστημονική φαντασία","1982","Στίβεν Σπίλμπεργκ"],"description":"Ένα αγόρι βρίσκει στον κήπο του έναν εξωγήινο που ξεχάστηκε στη Γη και, κρύβοντάς τον από τους μεγάλους, τον βοηθά να επικοινωνήσει με τους δικούς του και να γυρίσει στο σκάφος. Μια ζεστή οικογενειακή ιστορία του Σπίλμπεργκ για τη φιλία και το μεγάλωμα.","fact":"Η σκηνή με το ποδήλατο που πετά μπροστά από το φεγγάρι έγινε ένα από τα πιο αναγνωρίσιμα καρέ στην ιστορία του σινεμά.","wiki_en":"E.T. the Extra-Terrestrial"},{"name":"Ιντιάνα Τζόουνς: Ο Κυνηγός του Χαμένου Θησαυρού","emoji":"🤠","meta":["περιπέτεια","1981","Στίβεν Σπίλμπεργκ"],"description":"Ο αρχαιολόγος και τυχοδιώκτης με το παρατσούκλι Ιντιάνα Τζόουνς ανταγωνίζεται τους ναζί στο κυνήγι της βιβλικής Κιβωτού της Διαθήκης, που κρύβει υπερφυσική δύναμη. Η ταινία ένωσε το πνεύμα των παλιών σίριαλ περιπέτειας με σύγχρονα ακροβατικά και καταδιώξεις.","fact":"Η φημισμένη σκηνή με τον ξιφομάχο επινοήθηκε πάνω στο γύρισμα, γιατί ο πρωταγωνιστής δεν ένιωθε καλά.","wiki_en":"Raiders of the Lost Ark"},{"name":"Επιστροφή στο Μέλλον","emoji":"🚗","meta":["επιστημονική φαντασία","1985","Ρόμπερτ Ζεμέκις"],"description":"Ένας έφηβος με ένα αυτοκίνητο μετατραμμένο σε μηχανή του χρόνου βρίσκεται κατά λάθος από το 1985 στο 1955, συναντά τους γονείς του νέους και κινδυνεύει να εμποδίσει τη δική του γέννηση. Η ταινία έγινε το κλασικό δείγμα του ταξιδιού στον χρόνο.","fact":"Μηχανή του χρόνου στην ταινία είναι ένα DeLorean του εμπορίου, με τις χαρακτηριστικές πόρτες που ανοίγουν προς τα πάνω.","wiki_en":"Back to the Future"},{"name":"Εξολοθρευτής 2: Η Μέρα της Κρίσης","emoji":"🤖","meta":["επιστημονική φαντασία","1991","Τζέιμς Κάμερον"],"description":"Ο εξολοθρευτής του παλιού μοντέλου προστατεύει τώρα ένα έφηβο αγόρι από ένα νεότερο, πιο εξελιγμένο κυβόργιο από υγρό μέταλλο, που στάλθηκε να αλλάξει το μέλλον. Η συνέχεια έμεινε για τα πρωτοποριακά για την εποχή εφέ του υγρού μετάλλου.","fact":"Η φράση I'll be back από την πρώτη ταινία έμεινε το σήμα κατατεθέν του ήρωα του Άρνολντ Σβαρτσενέγκερ για δεκαετίες.","wiki_en":"Terminator 2: Judgment Day"},{"name":"Alien, ο Επιβάτης του Διαστήματος","emoji":"👽","meta":["ταινία τρόμου","1979","Ρίντλεϊ Σκοτ"],"description":"Το πλήρωμα ενός φορτηγού διαστημόπλοιου απαντά σε σήμα κινδύνου από άγνωστο πλανήτη και φέρνει άθελά του στο σκάφος ένα θανατηφόρο εξωγήινο θηρίο. Η ταινία του Ρίντλεϊ Σκοτ ένωσε τη διαστημική φαντασία με την αισθητική του τρόμου.","fact":"Τον ξενόμορφο σχεδίασε ο Ελβετός καλλιτέχνης Χανς Γκίγκερ, γνωστός για το σκοτεινό ύφος του, όπου η σάρκα μπλέκεται με τη μηχανή.","wiki_en":"Alien (film)"},{"name":"Blade Runner","emoji":"🌃","meta":["επιστημονική φαντασία","1982","Ρίντλεϊ Σκοτ"],"description":"Σε ένα ζοφερό μέλλον ένας ντετέκτιβ κυνηγά δραπέτες βιοτεχνολογικούς ρέπλικαντ, που σχεδόν δεν ξεχωρίζουν από ανθρώπους, και αρχίζει να αναρωτιέται για τη δική του συνείδηση. Η μεταφορά του μυθιστορήματος του Φίλιπ Ντικ όρισε την εικόνα του σάιμπερπανκ.","fact":"Στην πρώτη της κυκλοφορία η ταινία απέτυχε εμπορικά και μόνο αργότερα αναγνωρίστηκε ως μία από τις σημαντικότερες του είδους.","wiki_en":"Blade Runner"},{"name":"Πολύ Σκληρός για να Πεθάνει","emoji":"🏢","meta":["ταινία δράσης","1988","Τζον ΜακΤίερναν"],"description":"Ένας αστυνομικός από τη Νέα Υόρκη τα βάζει μόνος με μια συμμορία ένοπλων κακοποιών που κατέλαβαν έναν ουρανοξύστη στη χριστουγεννιάτικη γιορτή όπου βρίσκεται η γυναίκα του. Η ταινία όρισε για χρόνια το μοτίβο «ένας ήρωας απέναντι σε πολλούς σε κλειστό χώρο».","fact":"Η κραυγή Yippee-ki-yay του ήρωα του Μπρους Γουίλις έγινε μια από τις πιο αναγνωρίσιμες ατάκες στις ταινίες δράσης.","wiki_en":"Die Hard"},{"name":"Μόνος στο Σπίτι","emoji":"🎄","meta":["κομεντί","1990","Κρις Κολόμπους"],"description":"Ένα οχτάχρονο αγόρι ξεχνιέται κατά λάθος στο σπίτι όταν η οικογένεια πετά για Χριστούγεννα στην Ευρώπη και πρέπει μόνο του να το υπερασπιστεί από δύο άτσαλους διαρρήκτες. Οι ευφάνταστες παγίδες την έκαναν κλασική χριστουγεννιάτικη ταινία.","fact":"Για πάνω από δύο δεκαετίες παρέμεινε η εμπορικότερη κομεντί με ζωντανούς ηθοποιούς σε όλο τον κόσμο.","wiki_en":"Home Alone"},{"name":"Pretty Woman","emoji":"👠","meta":["ρομαντική κομεντί","1990","Γκάρι Μάρσαλ"],"description":"Ένας πλούσιος επιχειρηματίας προσλαμβάνει μια κοπέλα του δρόμου να τον συνοδεύσει σε μια εβδομάδα επαγγελματικών συναντήσεων, και ανάμεσά τους ανάβει απρόσμενα αληθινό αίσθημα. Η σύγχρονη Σταχτοπούτα έκανε σταρ τη Τζούλια Ρόμπερτς.","fact":"Αρχικά το σενάριο ήταν ένα σκληρό δράμα για τη ζωή στον δρόμο και μόνο μετά τις αλλαγές του στούντιο έγινε ρομαντική κομεντί με αίσιο τέλος.","wiki_en":"Pretty Woman"},{"name":"Dirty Dancing","emoji":"💃","meta":["μουσικό ρομαντικό δράμα","1987","Εμίλ Αρντολίνο"],"description":"Σε ένα καλοκαιρινό θέρετρο μια κοπέλα από ευκατάστατη οικογένεια ερωτεύεται έναν χορευτή από φτωχό περιβάλλον και κρυφά ετοιμάζεται μαζί του για μια σημαντική παράσταση. Η ταινία έμεινε για τα χορευτικά της και για το (I've Had) The Time of My Life.","fact":"Το τελικό σήκωμα της παρτενέρ πάνω από το κεφάλι έγινε μια από τις πιο παρωδημένες χορευτικές φιγούρες στο σινεμά.","wiki_en":"Dirty Dancing"},{"name":"Ghost","emoji":"👻","meta":["ρομαντικό δράμα","1990","Τζέρι Ζούκερ"],"description":"Ένας άντρας που δολοφονείται μένει στη γη ως φάντασμα και, με τη βοήθεια μιας απατεώνισσας μέντιουμ, προσπαθεί να προστατέψει την αγαπημένη του και να μάθει πώς πέθανε. Η ταινία ένωσε το μεταφυσικό με ένα τρυφερό ερωτικό δράμα.","fact":"Το Unchained Melody, που ακούγεται στη σκηνή με τον πηλό, ξανάγινε επιτυχία ένα τέταρτο του αιώνα μετά την ηχογράφηση των Righteous Brothers.","wiki_en":"Ghost (1990 film)"},{"name":"Η Σιωπή των Αμνών","emoji":"🦋","meta":["θρίλερ","1991","Τζόναθαν Ντέμι"],"description":"Μια νέα σπουδάστρια της ακαδημίας του FBI συμβουλεύεται τον φυλακισμένο ψυχίατρο και κανίβαλο Χάνιμπαλ Λέκτερ για να βρει τα ίχνη ενός άλλου κατά συρροή δολοφόνου. Είναι από τα λίγα θρίλερ που πήραν ποτέ Όσκαρ καλύτερης ταινίας.","fact":"Ο Άντονι Χόπκινς εμφανίζεται ως Λέκτερ λίγο πάνω από δεκαπέντε λεπτά, και αυτό αρκούσε για το Όσκαρ πρώτου ανδρικού ρόλου.","wiki_en":"The Silence of the Lambs"},{"name":"Se7en","emoji":"📦","meta":["θρίλερ","1995","Ντέιβιντ Φίντσερ"],"description":"Δύο ντετέκτιβ, ο ένας στα πρόθυρα της σύνταξης και ο άλλος πρωτάρης, ερευνούν μια σειρά φόνων που ο δράστης στήνει γύρω από τα επτά θανάσιμα αμαρτήματα. Η αδιάκοπη βροχή και η σκληρή σκηνοθεσία του Φίντσερ όρισαν το αστυνομικό θρίλερ της δεκαετίας του 1990.","fact":"Το φινάλε με το κουτί έγινε μια από τις πιο συζητημένες και πιο παρωδημένες ανατροπές στην ιστορία του θρίλερ.","wiki_en":"Seven (1995 film)"},{"name":"Η Πράσινη Μίλη","emoji":"🐭","meta":["δράμα","1999","Φρανκ Ντάραμποντ"],"description":"Ένας δεσμοφύλακας στην πτέρυγα των μελλοθανάτων μιας φυλακής της δεκαετίας του 1930 συναντά έναν καταδικασμένο γίγαντα με ανεξήγητο χάρισμα θεραπείας. Η μεταφορά του Στίβεν Κινγκ δένει τη φυλακή με το μεταφυσικό και με ερωτήματα πίστης και δικαιοσύνης.","fact":"Το μυθιστόρημα του Στίβεν Κινγκ στο οποίο βασίζεται κυκλοφόρησε αρχικά σε ξεχωριστά τεύχη, σαν σίριαλ σε χαρτόδετη έκδοση.","wiki_en":"The Green Mile (film)"},{"name":"Η Λίστα του Σίντλερ","emoji":"🕯️","meta":["ιστορικό δράμα","1993","Στίβεν Σπίλμπεργκ"],"description":"Στον Β' Παγκόσμιο Πόλεμο ο Γερμανός επιχειρηματίας Όσκαρ Σίντλερ σώζει πάνω από χίλιους Πολωνούς Εβραίους προσλαμβάνοντάς τους στο εργοστάσιό του. Γυρισμένη σχεδόν εξ ολοκλήρου σε ασπρόμαυρο, η ταινία του Σπίλμπεργκ βασίζεται σε αληθινή ιστορία.","fact":"Ο Σπίλμπεργκ δεν πήρε αμοιβή για την ταινία και με τα έσοδά της ίδρυσε ίδρυμα που καταγράφει μαρτυρίες επιζώντων του Ολοκαυτώματος.","wiki_en":"Schindler's List"},{"name":"Η Διάσωση του Στρατιώτη Ράιαν","emoji":"🪖","meta":["πολεμικό δράμα","1998","Στίβεν Σπίλμπεργκ"],"description":"Μετά την απόβαση στη Νορμανδία ένα απόσπασμα Αμερικανών στρατιωτών παίρνει εντολή να βρει και να γυρίσει σπίτι τον μόνο επιζώντα από τέσσερα αδέρφια. Η μεγάλη σκηνή της εφόδου στην παραλία θεωρείται από τις πιο ρεαλιστικές μάχες στο σινεμά.","fact":"Η απεικόνιση της μάχης ήταν τόσο σκληρή που, σύμφωνα με μαρτυρίες, κάποιοι βετεράνοι του Β' Παγκοσμίου έφευγαν από την αίθουσα.","wiki_en":"Saving Private Ryan"},{"name":"Gladiator","emoji":"⚔️","meta":["ιστορικό δράμα","2000","Ρίντλεϊ Σκοτ"],"description":"Ένας Ρωμαίος στρατηγός, προδομένος από τον φθονερό διάδοχο του αυτοκράτορα, χάνει την οικογένεια και την ελευθερία του και καταλήγει μονομάχος στην αρένα, σχεδιάζοντας την εκδίκησή του. Η ταινία ξαναζωντάνεψε το ενδιαφέρον του Χόλιγουντ για την αρχαιότητα.","fact":"Η φράση του ήρωα «Το όνομά μου είναι Μάξιμος Δέκιμος Μαρίδιος» έγινε μια από τις πιο αναγνωρίσιμες παρουσιάσεις στο σινεμά.","wiki_en":"Gladiator (2000 film)"},{"name":"Γενναία Καρδιά","emoji":"🗡️","meta":["ιστορικό δράμα","1995","Μελ Γκίμπσον"],"description":"Ο Σκωτσέζος Ουίλιαμ Γουάλας ξεσηκώνει εξέγερση ενάντια στην αγγλική κυριαρχία, αφού Άγγλοι στρατιώτες σκοτώνουν τη γυναίκα του. Το ιστορικό δράμα μεγάλης κλίμακας, με τις τεράστιες σκηνές μάχης, χάρισε στον Μελ Γκίμπσον το Όσκαρ σκηνοθεσίας.","fact":"Τα καρό κιλτ της ταινίας είναι αναχρονισμός — τα ταρτάν αυτής της μορφής εμφανίστηκαν πολύ αργότερα από τα γεγονότα που δείχνει.","wiki_en":"Braveheart"},{"name":"Λεόν: Ο Επαγγελματίας","emoji":"🌱","meta":["αστυνομικό δράμα","1994","Λυκ Μπεσόν"],"description":"Ένας μοναχικός επαγγελματίας δολοφόνος παίρνει υπό την προστασία του ένα δωδεκάχρονο κορίτσι που του σκότωσαν την οικογένεια διεφθαρμένοι πράκτορες, και δένεται μαζί του χωρίς να το θέλει. Ο Λυκ Μπεσόν ενώνει τη σκληρή δράση με μια απρόσμενα τρυφερή ιστορία φιλίας.","fact":"Το γλαστράκι που κουβαλά παντού ο ήρωας και φροντίζει σαν να είναι ο μόνος του φίλος έγινε το σύμβολο όλης της ταινίας.","wiki_en":"Léon: The Professional"},{"name":"Το Πέμπτο Στοιχείο","emoji":"🚕","meta":["επιστημονική φαντασία","1997","Λυκ Μπεσόν"],"description":"Ένας ταξιτζής στη φουτουριστική Νέα Υόρκη του 23ου αιώνα βρίσκεται ξαφνικά να σώζει τον κόσμο μαζί με μια μυστηριώδη κοπέλα που ενσαρκώνει ένα αρχαίο όπλο απέναντι στο απόλυτο κακό. Ο Μπεσόν ένωσε την αισθητική του κόμικ με τη διαστημική φαντασία.","fact":"Τα κοστούμια σχεδίασε ο Ζαν Πολ Γκοτιέ, μαζί με το περίφημο ρούχο από λευκούς επιδέσμους που φορά η Μίλα Γιόβοβιτς.","wiki_en":"The Fifth Element"},{"name":"Ο Βασιλιάς των Λιονταριών","emoji":"🦁","meta":["κινούμενα σχέδια","1994","Ρότζερ Άλερς, Ρομπ Μίνκοφ"],"description":"Το λιονταράκι Σίμπα προορίζεται να κληρονομήσει τον θρόνο του πατέρα του στην αφρικανική σαβάνα, αλλά μετά από μια τραγωδία για την οποία κατηγορεί τον εαυτό του φεύγει μακριά και επιστρέφει χρόνια αργότερα. Η ταινία της Disney, με μουσική του Έλτον Τζον, σάρωσε στα ταμεία.","fact":"Η ιστορία θυμίζει έντονα τον «Άμλετ» του Σαίξπηρ, με την προδοσία και την εκδίκηση για τον σκοτωμένο πατέρα.","wiki_en":"The Lion King"},{"name":"Toy Story","emoji":"🧸","meta":["κινούμενα σχέδια","1995","Τζον Λάσετερ"],"description":"Ο καουμπόης Γούντι, το αγαπημένο παιχνίδι του μικρού Άντι, ζηλεύει τον καινούριο αστραφτερό διαστημικό φύλακα Μπαζ Λάιτγιαρ και σιγά σιγά μαθαίνει να μοιράζεται την προσοχή του αφεντικού του. Ήταν η πρώτη ταινία μεγάλου μήκους φτιαγμένη εξ ολοκλήρου σε υπολογιστή.","fact":"Στους υπολογιστές της εποχής, η απόδοση ενός και μόνο καρέ της πρώτης ψηφιακής ταινίας μπορούσε να κρατήσει ώρες.","wiki_en":"Toy Story"},{"name":"Shrek","emoji":"🧅","meta":["κινούμενα σχέδια","2001","Άντριου Άνταμσον, Βίκι Τζένσον"],"description":"Ένας γκρινιάρης πράσινος ογκρ, που θέλει πίσω την ησυχία του βάλτου του, δέχεται να σώσει μια πριγκίπισσα από έναν πύργο που φυλάει δράκος, με αντάλλαγμα τη γη του. Η ταινία παρωδεί τα κλασικά παραμύθια και κλείνει συνεχώς το μάτι στους μεγάλους.","fact":"Η ατάκα του Σρεκ ότι οι ογκρ έχουν στρώσεις, όπως τα κρεμμύδια, είναι η πιο πολυαναφερόμενη της ταινίας.","wiki_en":"Shrek"},{"name":"Ψάχνοντας τον Νέμο","emoji":"🐠","meta":["κινούμενα σχέδια","2003","Άντριου Στάντον"],"description":"Ένα ψάρι-κλόουν, ο Μάρλιν, διασχίζει ολόκληρο τον ωκεανό για να βρει τον γιο του Νέμο, που τον άρπαξαν για ενυδρείο, αντιμετωπίζοντας κάθε κίνδυνο μαζί με την αφηρημένη αλλά καλόκαρδη Ντόρι. Η ταινία της Pixar έμεινε για τη ρεαλιστική απόδοση του βυθού.","fact":"Μετά την ταινία εκτοξεύτηκε η ζήτηση για ψάρια-κλόουν σε ενυδρεία σπιτιού, κάτι που ανησύχησε τους οικολόγους.","wiki_en":"Finding Nemo"},{"name":"WALL-E","emoji":"🤖","meta":["κινούμενα σχέδια","2008","Άντριου Στάντον"],"description":"Σε μια Γη θαμμένη στα σκουπίδια και εγκαταλειμμένη, ένα μοναχικό ρομπότ καθαρισμού συνεχίζει να δουλεύει, ώσπου ερωτεύεται ένα ρομπότ νέας γενιάς που φτάνει σε αποστολή αναγνώρισης. Το πρώτο τρίτο της ταινίας δεν έχει σχεδόν καθόλου διαλόγους, μόνο παντομίμα.","fact":"Τη φωνή και τους ήχους του WALL-E έφτιαξε ο Μπεν Μπερτ, ο ίδιος που είχε δημιουργήσει και την «ομιλία» του R2-D2.","wiki_en":"WALL-E"},{"name":"Ψηλά στο Σπίτι","emoji":"🎈","meta":["κινούμενα σχέδια","2009","Πιτ Ντόκτερ"],"description":"Ένας ηλικιωμένος χήρος δένει χιλιάδες μπαλόνια στο σπίτι του και ξεκινά για το ταξίδι στη Νότια Αμερική που ονειρευόταν με τη γυναίκα του, για να ανακαλύψει έναν μικρό πρόσκοπο στη βεράντα. Η αρχή της ταινίας αφηγείται μια ολόκληρη κοινή ζωή χωρίς λόγια.","fact":"Πέρα από το βραβείο κινουμένων σχεδίων, η ταινία πήρε και μια σπάνια για το είδος υποψηφιότητα Όσκαρ καλύτερης ταινίας.","wiki_en":"Up (2009 film)"},{"name":"Ψυχρά κι Ανάποδα","emoji":"❄️","meta":["κινούμενα σχέδια","2013","Κρις Μπακ, Τζένιφερ Λι"],"description":"Μια πριγκίπισσα που παγώνει ό,τι αγγίζει βυθίζει κατά λάθος το βασίλειό της σε αιώνιο χειμώνα και κρύβεται στα βουνά, ενώ η αδελφή της ξεκινά να τη βρει και να διορθώσει το κακό. Η Disney έβαλε στο κέντρο όχι τον έρωτα αλλά τον δεσμό των δύο αδελφών.","fact":"Το τραγούδι Let It Go έγινε παγκόσμια επιτυχία και ηχογραφήθηκε σε δεκάδες γλώσσες.","wiki_en":"Frozen (2013 film)"},{"name":"Spirited Away","emoji":"🐉","meta":["κινούμενα σχέδια","2001","Χαγιάο Μιγιαζάκι"],"description":"Ένα κορίτσι, καθ' οδόν προς το καινούριο του σπίτι, περνά στον κόσμο των πνευμάτων, όπου οι γονείς του μεταμορφώνονται σε γουρούνια και εκείνο πιάνει δουλειά σε ένα μαγικό λουτρό για να τους σώσει. Η ταινία του Χαγιάο Μιγιαζάκι ήταν το πρώτο άνιμε με Όσκαρ.","fact":"Για πολλά χρόνια παρέμεινε η εμπορικότερη ταινία στην ιστορία των ιαπωνικών αιθουσών.","wiki_en":"Spirited Away"},{"name":"Οι Πειρατές της Καραϊβικής: Η Κατάρα του Μαύρου Μαργαριταριού","emoji":"🏴‍☠️","meta":["περιπέτεια","2003","Γκορ Βερμπίνσκι"],"description":"Ένας σιδεράς ξεκινά να σώσει την απαχθείσα κόρη του κυβερνήτη μαζί με τον εκκεντρικό πειρατή Τζακ Σπάροου, που το πλοίο του είναι καταραμένο και το πλήρωμά του γίνεται σκελετοί στο σεληνόφως. Βασισμένη σε ένα παιχνίδι της Disneyland, αναβίωσε την πειρατική περιπέτεια.","fact":"Ο Τζόνι Ντεπ έχτισε τον Τζακ Σπάροου σε μεγάλο βαθμό πάνω στους τρόπους του μουσικού Κιθ Ρίτσαρντς.","wiki_en":"Pirates of the Caribbean: The Curse of the Black Pearl"},{"name":"Spider-Man","emoji":"🕷️","meta":["ταινία υπερηρώων","2002","Σαμ Ρέιμι"],"description":"Ένας απλός μαθητής, ο Πίτερ Πάρκερ, αποκτά υπερδυνάμεις από το δάγκωμα μιας ραδιενεργής αράχνης και, μετά τον θάνατο του θείου του, αποφασίζει να τις βάλει στην υπηρεσία της πόλης. Η ταινία του Σαμ Ρέιμι ήταν από τις πρώτες μεγάλες επιτυχίες υπερηρώων.","fact":"Η φράση του θείου Μπεν «με τη μεγάλη δύναμη έρχεται και μεγάλη ευθύνη» έγινε το σύνθημα του ήρωα για δεκαετίες.","wiki_en":"Spider-Man (2002 film)"},{"name":"Iron Man","emoji":"🦾","meta":["ταινία υπερηρώων","2008","Τζον Φαβρό"],"description":"Ένας δισεκατομμυριούχος έμπορος όπλων που πέφτει αιχμάλωτος φτιάχνει μια θωρακισμένη στολή για να δραπετεύσει και, γυρίζοντας σπίτι, συνεχίζει να την τελειοποιεί για να πολεμά το κακό. Η ταινία άνοιξε το κινηματογραφικό σύμπαν της Marvel.","fact":"Η σκηνή μετά τους τίτλους, με την εμφάνιση του Νικ Φιούρι, καθιέρωσε τη συνήθεια που δένει τις ταινίες της Marvel σε ένα σύμπαν.","wiki_en":"Iron Man (film)"},{"name":"The Avengers","emoji":"🛡️","meta":["ταινία υπερηρώων","2012","Τζος Γουίντον"],"description":"Οι πιο δυνατοί ήρωες της Γης — ο Iron Man, ο Θορ, ο Κάπτεν Αμέρικα, ο Χαλκ και οι υπόλοιποι — ενώνονται για πρώτη φορά για να σταματήσουν την εισβολή ενός εξωγήινου στρατού στη Νέα Υόρκη. Ήταν η πρώτη μεγάλη συνάντηση του σύμπαντος της Marvel.","fact":"Να μαζευτούν ήρωες από ξεχωριστές σειρές ταινιών σε μία ταινία δεν είχε σχεδόν ποτέ δοκιμαστεί σε τέτοια κλίμακα.","wiki_en":"The Avengers (2012 film)"},{"name":"Avengers: Endgame","emoji":"💎","meta":["ταινία υπερηρώων","2019","Άντονι Ρούσο, Τζο Ρούσο"],"description":"Μετά την καταστροφή της προηγούμενης ταινίας, οι υπερήρωες που απέμειναν ψάχνουν τρόπο να αναιρέσουν την εξαφάνιση των μισών έμβιων όντων του σύμπαντος. Το φινάλε της πολύχρονης σάγκα της Marvel έγινε μια από τις εμπορικότερες ταινίες όλων των εποχών.","fact":"Για ένα διάστημα ήταν η εμπορικότερη ταινία στην παγκόσμια ιστορία, περνώντας μπροστά από το Avatar.","wiki_en":"Avengers: Endgame"},{"name":"Joker","emoji":"🃏","meta":["δράμα","2019","Τοντ Φίλιπς"],"description":"Ένας αποτυχημένος κλόουν και επίδοξος κωμικός με ψυχική διαταραχή χάνει σιγά σιγά την επαφή του με την πραγματικότητα, μέσα στην αδιαφορία και τη σκληρότητα του Γκόθαμ. Η ταινία ξαναδιάβασε την καταγωγή ενός κλασικού κακού ως ζοφερό κοινωνικό δράμα.","fact":"Ο Χοακίν Φίνιξ έχασε πολλά κιλά για τον ρόλο, ώστε να δώσει στον ήρωα μια εξαντλημένη, τσακισμένη όψη.","wiki_en":"Joker (2019 film)"},{"name":"Deadpool","emoji":"🗡️","meta":["κομεντί υπερηρώων","2016","Τιμ Μίλερ"],"description":"Ένας πρώην κομάντο, που γίνεται πειραματόζωο σε ένα παράνομο πρόγραμμα θεραπείας του καρκίνου, βγαίνει με υπερδυνάμεις και παραμορφωμένο πρόσωπο και εκδικείται πίσω από τη μάσκα ενός φλύαρου μισθοφόρου. Η ταινία σπάει τον τέταρτο τοίχο και έχει μαύρο χιούμορ.","fact":"Ο Ράιαν Ρέινολντς πάλευε χρόνια για την ταινία, και καθοριστικό ρόλο έπαιξε ένα δοκιμαστικό βίντεο που διέρρευσε και ενθουσίασε τον κόσμο.","wiki_en":"Deadpool (film)"},{"name":"Οι Φύλακες του Γαλαξία","emoji":"🌌","meta":["ταινία υπερηρώων","2014","Τζέιμς Γκαν"],"description":"Μια ανάκατη παρέα διαστημικών παρανόμων — μαζί και ένα ρακούν που μιλάει και ένα δέντρο που περπατά — μπλέκει κατά λάθος στη μάχη για ένα αντικείμενο με δύναμη να καταστρέψει ολόκληρους πλανήτες. Η ταινία ξεχώρισε για τη ρετρό μουσική της από τη δεκαετία του 1970.","fact":"Η συλλογή Awesome Mix με τις παλιές επιτυχίες που ακούει ο ήρωας έγινε από μόνη της επιτυχία στις μουσικές υπηρεσίες.","wiki_en":"Guardians of the Galaxy (film)"},{"name":"Mad Max: Ο Δρόμος της Οργής","emoji":"🏜️","meta":["ταινία δράσης","2015","Τζορτζ Μίλερ"],"description":"Στην καμένη ερημιά ενός μεταποκαλυπτικού μέλλοντος, η δραπέτισσα αρχηγός Φουριόζα και ο τυχαίος σύντροφός της Μαξ προσπαθούν να ξεφύγουν από έναν τύραννο με ένα φορτηγό γεμάτο γυναίκες. Μια καταδίωξη σχεδόν δύο ωρών χάρισε στην ταινία ενθουσιώδεις κριτικές.","fact":"Τα περισσότερα ακροβατικά και τα τρακαρίσματα γυρίστηκαν αληθινά, σχεδόν χωρίς ψηφιακά γραφικά.","wiki_en":"Mad Max: Fury Road"},{"name":"John Wick","emoji":"🐶","meta":["ταινία δράσης","2014","Τσαντ Σταχέλσκι"],"description":"Ένας αποσυρμένος πληρωμένος δολοφόνος γυρίζει στην παλιά του δουλειά όταν παλιοί συνεργάτες σκοτώνουν το κουτάβι που του άφησε η νεκρή γυναίκα του και του κλέβουν το αυτοκίνητο. Η ταινία έμεινε για τη χορογραφία των σκηνών δράσης, που άλλαξε το είδος.","fact":"Τις σκηνές μάχης έστησαν πρώην κασκαντέρ, και αυτό έδωσε στις ανταλλαγές πυρών μια σωματική αλήθεια ασυνήθιστη για το Χόλιγουντ.","wiki_en":"John Wick"},{"name":"Kill Bill: Vol. 1","emoji":"🟡","meta":["ταινία δράσης","2003","Κουέντιν Ταραντίνο"],"description":"Μια πρώην πληρωμένη δολοφόνος, που επέζησε από την εκτέλεσή της στον ίδιο της τον γάμο, φτιάχνει λίστα με τους παλιούς συναδέλφους της και τους ξεκαθαρίζει έναν έναν. Ο Ταραντίνο ενώνει το σινεμά των σαμουράι, τη δράση του Χονγκ Κονγκ και το γουέστερν.","fact":"Η κίτρινη φόρμα της ηρωίδας παραπέμπει ευθέως στη στολή του Μπρους Λι στην ταινία Game of Death.","wiki_en":"Kill Bill: Volume 1"},{"name":"Django Unchained","emoji":"⛓️","meta":["γουέστερν","2012","Κουέντιν Ταραντίνο"],"description":"Ένας απελευθερωμένος σκλάβος συνεργάζεται με έναν Γερμανό κυνηγό επικηρυγμένων για να βρει και να σώσει τη γυναίκα του, που την κρατά ακόμη ένας σκληρός φυτευτής στον αμερικανικό Νότο. Ο Ταραντίνο ξαναγράφει το σπαγγέτι γουέστερν μέσα από το θέμα της δουλείας.","fact":"Ο τίτλος και ένα μέρος της μουσικής παραπέμπουν στο ιταλικό γουέστερν Django του 1966.","wiki_en":"Django Unchained"},{"name":"Inglourious Basterds","emoji":"🎬","meta":["πολεμικό δράμα","2009","Κουέντιν Ταραντίνο"],"description":"Ένα απόσπασμα Αμερικανοεβραίων στρατιωτών κυνηγά Ναζί αξιωματικούς στην κατεχόμενη Γαλλία, ενώ παράλληλα η ιδιοκτήτρια ενός παρισινού σινεμά ετοιμάζει τη δική της εκδίκηση για τη δολοφονημένη οικογένειά της. Ο Ταραντίνο δένει την εναλλακτική ιστορία με αγάπη για το σινεμά.","fact":"Και οι δύο λέξεις του τίτλου είναι γραμμένες λάθος επίτηδες, και η ταινία δεν εξηγεί ποτέ γιατί.","wiki_en":"Inglourious Basterds"},{"name":"Κάποτε στο Χόλιγουντ","emoji":"📺","meta":["τραγικωμωδία","2019","Κουέντιν Ταραντίνο"],"description":"Ένας ξεπεσμένος πρωταγωνιστής τηλεοπτικών γουέστερν και ο κασκαντέρ-σωσίας του παλεύουν να κρατηθούν στην επιφάνεια μέσα στο Χόλιγουντ που αλλάζει ραγδαία στα τέλη της δεκαετίας του 1960, δίπλα στο σπίτι της Σάρον Τέιτ. Η ταινία ξαναφτιάχνει το Λος Άντζελες της εποχής.","fact":"Η ιστορία διαδραματίζεται στο Λος Άντζελες του 1969 και παίζει πάνω στην πραγματική τραγωδία εκείνου του καλοκαιριού.","wiki_en":"Once Upon a Time in Hollywood"},{"name":"Ο Λύκος της Wall Street","emoji":"💰","meta":["βιογραφική κομεντί","2013","Μάρτιν Σκορσέζε"],"description":"Ο χρηματιστής Τζόρνταν Μπέλφορτ χτίζει μια οικονομική αυτοκρατορία πάνω σε απάτες και κατρακυλά σε έναν κόσμο αδιανόητης χλιδής, ναρκωτικών και ασυδοσίας. Η ταινία βασίζεται σε αληθινά απομνημονεύματα και ξεχωρίζει για τον ξέφρενο ρυθμό της.","fact":"Ο Λεονάρντο ντι Κάπριο υποδύεται έναν υπαρκτό άνθρωπο, τον Τζόρνταν Μπέλφορτ, που εμφανίζεται και ο ίδιος σε ρολάκι στην ταινία.","wiki_en":"The Wolf of Wall Street (2013 film)"},{"name":"Shutter Island","emoji":"🏝️","meta":["ψυχολογικό θρίλερ","2010","Μάρτιν Σκορσέζε"],"description":"Ένας ομοσπονδιακός αστυνόμος ερευνά την εξαφάνιση μιας ασθενούς από ψυχιατρείο σε ένα απομονωμένο νησί, αλλά όσο προχωρά η έρευνα τόσο λιγότερο αξιόπιστη μοιάζει η πραγματικότητα γύρω του. Η μεταφορά του μυθιστορήματος του Ντένις Λιχέιν είναι ένα θρίλερ ατμόσφαιρας.","fact":"Ο Σκορσέζε γέμισε επίτηδες την ταινία με οπτικά και αφηγηματικά στοιχεία που βγάζουν νόημα μόνο στη δεύτερη προβολή.","wiki_en":"Shutter Island"},{"name":"Τα Μυστικά της Βοστώνης","emoji":"🕵️","meta":["αστυνομικό δράμα","2006","Μάρτιν Σκορσέζε"],"description":"Ένας αστυνομικός μπαίνει μυστικός στην ιρλανδική μαφία της Βοστώνης, ενώ ταυτόχρονα ένας άνθρωπος της μαφίας δουλεύει ως χαφιές μέσα στην ίδια την αστυνομία, και ο καθένας ψάχνει να ξεσκεπάσει τον άλλον. Η ταινία χάρισε στον Σκορσέζε το πρώτο του Όσκαρ σκηνοθεσίας.","fact":"Η ταινία είναι ριμέικ του θρίλερ Infernal Affairs από το Χονγκ Κονγκ.","wiki_en":"The Departed"},{"name":"Τα Καλά Παιδιά","emoji":"🔫","meta":["αστυνομικό δράμα","1990","Μάρτιν Σκορσέζε"],"description":"Η άνοδος και η πτώση ενός μικρού γκάνγκστερ, που από παιδί ονειρευόταν να ανήκει στην ιταλοαμερικανική μαφία της Νέας Υόρκης και πέρασε από τις μικροκλοπές στα μεγάλα εγκλήματα. Η ταινία βασίζεται σε αληθινή ζωή και έμεινε για το ξέφρενο μοντάζ της.","fact":"Το περίφημο μακρύ πλάνο της διαδρομής μέσα από την κουζίνα του εστιατορίου γυρίστηκε σε μία αδιάκοπη λήψη.","wiki_en":"Goodfellas"},{"name":"Ο Ταξιτζής","emoji":"🚕","meta":["ψυχολογικό δράμα","1976","Μάρτιν Σκορσέζε"],"description":"Ένας μοναχικός βετεράνος του Βιετνάμ δουλεύει νύχτες ταξί στη Νέα Υόρκη του εγκλήματος και, καθώς αποξενώνεται όλο και πιο πολύ, καταστρώνει ένα σχέδιο βίαιης κάθαρσης της πόλης. Η ταινία έγινε ένα από τα κορυφαία πορτρέτα της αστικής μοναξιάς.","fact":"Τη μουσική έγραψε ο Μπέρναρντ Χέρμαν, πολύχρονος συνεργάτης του Χίτσκοκ· ήταν η τελευταία του δουλειά και η ταινία είναι αφιερωμένη στη μνήμη του.","wiki_en":"Taxi Driver"},{"name":"Scarface","emoji":"🌎","meta":["αστυνομικό δράμα","1983","Μπράιαν Ντε Πάλμα"],"description":"Ο Κουβανός μετανάστης Τόνι Μοντάνα φτάνει στο Μαϊάμι χωρίς δεκάρα και χτίζει σιγά σιγά μια αυτοκρατορία ναρκωτικών, ανεβαίνοντας τη ματωμένη σκάλα του υποκόσμου. Το ριμέικ μιας ταινίας του 1932 έγινε η καλτ ιστορία του αμερικανικού ονείρου από την ανάποδη.","fact":"Η επιγραφή «Ο κόσμος είναι δικός σου», που ο ήρωας βλέπει σε ένα αερόπλοιο, έγινε το σύνθημα όλης της ιστορίας.","wiki_en":"Scarface (1983 film)"},{"name":"The Big Lebowski","emoji":"🎳","meta":["κομεντί","1998","Ίθαν Κοέν, Τζόελ Κοέν"],"description":"Έναν τεμπέλη λάτρη του μπόουλινγκ με το παρατσούκλι Dude τον περνούν κατά λάθος για έναν συνονόματο εκατομμυριούχο και τον μπλέκουν σε μια παράλογη ιστορία με απαγωγή και λύτρα. Η εκκεντρική κομεντί των αδελφών Κοέν πέρασε αρχικά απαρατήρητη και μετά έγινε καλτ.","fact":"Οι θαυμαστές της ταινίας διοργανώνουν κάθε χρόνο το Lebowski Fest, με μπόουλινγκ και κοστούμια των ηρώων.","wiki_en":"The Big Lebowski"},{"name":"Καμιά Πατρίδα για τους Μελλοθάνατους","emoji":"🪙","meta":["θρίλερ","2007","Ίθαν Κοέν, Τζόελ Κοέν"],"description":"Ένας κυνηγός που πέφτει τυχαία πάνω στα λεφτά μιας αποτυχημένης συμφωνίας ναρκωτικών προσπαθεί να εξαφανιστεί από έναν αδίστακτο δολοφόνο που τον καταδιώκει στις ερημιές του Τέξας. Η μεταφορά του μυθιστορήματος του Κόρμακ ΜακΚάρθι πήρε Όσκαρ καλύτερης ταινίας.","fact":"Το όπλο του δολοφόνου είναι ένα πιστόλι σφαγής ζώων, μια εντελώς ασυνήθιστη επιλογή για αστυνομικό θρίλερ.","wiki_en":"No Country for Old Men"},{"name":"American Beauty","emoji":"🌹","meta":["δράμα","1999","Σαμ Μέντες"],"description":"Ένας μεσήλικας απογοητευμένος από τη δουλειά και τον γάμο του περνά κρίση, ερωτεύεται τη φίλη της κόρης του και αποφασίζει να ανατρέψει τη ζωή του κόντρα στις συμβάσεις των προαστίων. Η ταινία έμεινε για τον οπτικό συμβολισμό της, με πρώτα τα σκορπισμένα ροδοπέταλα.","fact":"Μια πλαστική σακούλα που παίζει στον άνεμο σε μια σκηνή έγινε από τις πιο συζητημένες και πιο παρωδημένες εικόνες της ταινίας.","wiki_en":"American Beauty (1999 film)"},{"name":"Η Έκτη Αίσθηση","emoji":"👦","meta":["μεταφυσικό θρίλερ","1999","Μ. Νάιτ Σιάμαλαν"],"description":"Ένας παιδοψυχολόγος προσπαθεί να βοηθήσει ένα αγόρι που λέει ότι βλέπει νεκρούς, και σιγά σιγά φτάνουν κι οι δύο σε μια αλήθεια που αλλάζει όλη την ιστορία. Η ταινία έμεινε για μια από τις πιο απρόσμενες ανατροπές στο φινάλε που έχει δει το σινεμά.","fact":"Η ατάκα του αγοριού «Βλέπω νεκρούς ανθρώπους» έγινε από τις πιο αναγνωρίσιμες και πιο παρωδημένες του κινηματογράφου.","wiki_en":"The Sixth Sense"},{"name":"Ένας Υπέροχος Άνθρωπος","emoji":"🧮","meta":["βιογραφικό δράμα","2001","Ρον Χάουαρντ"],"description":"Ο χαρισματικός μαθηματικός Τζον Νας πετυχαίνει τη μια επιστημονική τομή μετά την άλλη, παλεύοντας ταυτόχρονα με μια σχιζοφρένεια που επιδεινώνεται και παραμορφώνει την αίσθηση του πραγματικού. Η ταινία βασίζεται στη ζωή ενός υπαρκτού νομπελίστα οικονομικών.","fact":"Η ταινία πήρε Όσκαρ καλύτερης ταινίας και η Τζένιφερ Κόνελι το Όσκαρ δεύτερου γυναικείου ρόλου.","wiki_en":"A Beautiful Mind (film)"},{"name":"Πιάσε με αν Μπορείς","emoji":"✈️","meta":["αστυνομική κομεντί","2002","Στίβεν Σπίλμπεργκ"],"description":"Ένας έφηβος γίνεται δεινός απατεώνας, περνιέται για πιλότος, γιατρός και δικηγόρος και πλαστογραφεί επιταγές εκατομμυρίων, ώσπου αρχίζει να τον κυνηγά ένας επίμονος πράκτορας του FBI. Η ταινία βασίζεται στα απομνημονεύματα του υπαρκτού Φρανκ Αμπανέιλ.","fact":"Ο αληθινός Φρανκ Αμπανέιλ, που η ιστορία του έγινε η ταινία, έγινε αργότερα σύμβουλος τραπεζικής ασφάλειας.","wiki_en":"Catch Me If You Can"},{"name":"Ocean's Eleven","emoji":"🎰","meta":["αστυνομική κομεντί","2001","Στίβεν Σόντερμπεργκ"],"description":"Ο επαγγελματίας απατεώνας Ντάνι Όσιαν μαζεύει μια ομάδα έντεκα ειδικών για να ληστέψει τρία καζίνο του Λας Βέγκας μέσα σε μία νύχτα. Το ριμέικ μιας ταινίας του 1960, με πλειάδα αστέρων, έγινε το μέτρο του κομψού σινεμά με ληστείες.","fact":"Το πλάνο με τους ήρωες να στέκονται αμίλητοι μπροστά στα συντριβάνια του Bellagio στο φινάλε είναι η πιο γνωστή εικόνα της ταινίας.","wiki_en":"Ocean's Eleven (2001 film)"},{"name":"Mission: Impossible","emoji":"🕶️","meta":["ταινία δράσης","1996","Μπράιαν Ντε Πάλμα"],"description":"Ένας πράκτορας παγιδεύεται μετά από μια αποστολή στην οποία σκοτώνεται όλη η ομάδα του, και πρέπει μόνος, έξω από τον νόμο, να βρει ποιος τους πρόδωσε. Βασισμένη στην καλτ τηλεοπτική σειρά της δεκαετίας του 1960, ξεκίνησε τη μακρόβια σειρά δράσης του Τομ Κρουζ.","fact":"Η εισβολή στο ασφαλές θησαυροφυλάκιο της CIA, με τον ήρωα κρεμασμένο σε συρματόσχοινο μια ανάσα από το πάτωμα, είναι από τις πιο παρωδημένες σκηνές.","wiki_en":"Mission: Impossible (film)"},{"name":"Casino Royale","emoji":"🎲","meta":["ταινία κατασκοπείας","2006","Μάρτιν Κάμπελ"],"description":"Μόλις προαχθείς σε πράκτορα 007, ο Τζέιμς Μποντ παίρνει την πρώτη σοβαρή αποστολή του: να νικήσει στο πόκερ τον χρηματοδότη μιας τρομοκρατικής οργάνωσης σε ένα καζίνο του Μαυροβουνίου. Η ταινία ξεκίνησε από την αρχή τη σειρά Μποντ, με πιο σκληρό τόνο.","fact":"Ήταν η πρώτη ταινία Μποντ με τον Ντάνιελ Κρεγκ, που στην αρχή συνάντησε τη δυσπιστία μέρους των θαυμαστών και μετά τους κέρδισε.","wiki_en":"Casino Royale (2006 film)"},{"name":"Ρόκι","emoji":"🥊","meta":["αθλητικό δράμα","1976","Τζον Άβιλντσεν"],"description":"Ένας άγνωστος πυγμάχος από τη λαϊκή Φιλαδέλφεια βρίσκει απρόσμενα την ευκαιρία να παλέψει με τον παγκόσμιο πρωταθλητή και την αρπάζει, για να αποδείξει στον εαυτό του και στους άλλους ότι αντέχει ως το τέλος. Η μικρού προϋπολογισμού ταινία έκανε σταρ τον Σταλόνε.","fact":"Το ανέβασμα του ήρωα στα σκαλιά του Μουσείου Τέχνης της Φιλαδέλφειας τα έκανε αξιοθέατο, γνωστά ως «τα σκαλιά του Ρόκι».","wiki_en":"Rocky"},{"name":"Rambo: Πρώτο Αίμα","emoji":"🔪","meta":["ταινία δράσης","1982","Τεντ Κότσεφ"],"description":"Ένας βετεράνος του Βιετνάμ, που η αστυνομία μιας μικρής πόλης τον καταδιώκει άδικα, κρύβεται στο δάσος και τα βάζει μόνος με ένα ολόκληρο απόσπασμα. Η ταινία ανοίγει το δύσκολο θέμα της επιστροφής των βετεράνων και παρουσιάζει τον ήρωα Ράμπο.","fact":"Σε αντίθεση με τις αιματοβαμμένες συνέχειες, στην πρώτη ταινία ο ήρωας σχεδόν δεν σκοτώνει — κυρίως αφοπλίζει και τρομάζει τους διώκτες του.","wiki_en":"First Blood"},{"name":"Predator","emoji":"👽","meta":["ταινία δράσης και φαντασίας","1987","Τζον ΜακΤίερναν"],"description":"Ένα απόσπασμα επίλεκτων κομάντος στέλνεται σε αποστολή διάσωσης στη ζούγκλα της Κεντρικής Αμερικής και γίνεται ένας ένας λεία ενός αόρατου εξωγήινου κυνηγού. Η ταινία ένωσε την πολεμική δράση με τον τρόμο και χάρισε στο είδος ένα αξέχαστο τέρας.","fact":"Η στολή του Predator είχε φτιαχτεί αρχικά για άλλον ηθοποιό και άλλη μορφή, και ξαναχτίστηκε από την αρχή λίγο πριν τα γυρίσματα.","wiki_en":"Predator (film)"},{"name":"RoboCop","emoji":"🦾","meta":["ταινία δράσης και φαντασίας","1987","Πολ Βερχόφεν"],"description":"Ένας αστυνομικός του Ντιτρόιτ, βαριά τραυματισμένος στο καθήκον, επιστρέφει στην υπηρεσία ως κυβόργιο με σχεδόν χαμένη ανθρώπινη μνήμη και σιγά σιγά θυμάται ποιος ήταν. Ο Πολ Βερχόφεν δένει τη σκληρή δράση με καυστική σάτιρα για τις εταιρείες και τα μέσα.","fact":"Λόγω της υπερβολικής βιαιότητας η ταινία ξαναμοντάρθηκε αρκετές φορές, ώστε να πάρει στις ΗΠΑ σήμανση που επέτρεπε την προβολή.","wiki_en":"RoboCop"},{"name":"Οι Κυνηγοί των Φαντασμάτων","emoji":"👻","meta":["κομεντί φαντασίας","1984","Άιβαν Ράιτμαν"],"description":"Τρεις άτσαλοι επιστήμονες της παραψυχολογίας ανοίγουν στη Νέα Υόρκη μια ιδιωτική υπηρεσία σύλληψης φαντασμάτων και πέφτουν αμέσως πάνω σε μια αληθινή υπερφυσική εισβολή. Η ταινία κόλλησε την κομεντί στην ιστορία φαντασμάτων και έγινε καλτ κλασικό της δεκαετίας του 1980.","fact":"Το τραγούδι Ghostbusters του Ρέι Πάρκερ Τζούνιορ, γραμμένο για την ταινία, ανέβηκε στην κορυφή του αμερικανικού τσαρτ.","wiki_en":"Ghostbusters (1984 film)"},{"name":"Men in Black","emoji":"🕶️","meta":["κομεντί φαντασίας","1997","Μπάρι Σόνενφελντ"],"description":"Μια μυστική υπηρεσία με αυστηρά μαύρα κοστούμια επιτηρεί αθέατη τους εξωγήινους που ζουν ανάμεσά μας στη Γη, και ένας νεοσύλλεκτος αναλαμβάνει μια επικίνδυνη υπόθεση με τον έμπειρο συνεργάτη του. Βασισμένη σε κόμικ, ενώνει δράση, χιούμορ και ευφάνταστους εξωγήινους.","fact":"Η συσκευή που σβήνει με μια λάμψη τη μνήμη των μαρτύρων, ο νευραλυτής, έγινε ένα από τα αναγνωρίσιμα γκάτζετ της ποπ κουλτούρας.","wiki_en":"Men in Black (film)"},{"name":"Η Μέρα της Μαρμότας","emoji":"🔁","meta":["κομεντί","1993","Χάρολντ Ράμις"],"description":"Ένας κυνικός μετεωρολόγος της τηλεόρασης κολλάει σε μια χρονική θηλιά και ζει ξανά και ξανά την ίδια μέρα σε μια μικρή πόλη, ώσπου αλλάζει τελικά ως άνθρωπος. Ο τίτλος της ταινίας έγινε έκφραση για την ατέλειωτη επανάληψη των ίδιων πραγμάτων.","fact":"Ο ακριβής αριθμός των επαναλήψεων δεν λέγεται ποτέ, αλλά κατά τους υπολογισμούς των θαυμαστών θα μπορούσε να φτάνει χρόνια.","wiki_en":"Groundhog Day (film)"},{"name":"Η Μάσκα","emoji":"🎭","meta":["κομεντί φαντασίας","1994","Τσακ Ράσελ"],"description":"Ένας συνεσταλμένος τραπεζικός υπάλληλος βρίσκει μια αρχαία μάσκα που, μόλις τη φορέσει, τον μετατρέπει σε ένα τρελό πρόσωπο με πράσινο κεφάλι, υπερδυνάμεις και μηδέν αναστολές. Η ταινία έκανε τον Τζιμ Κάρεϊ αστέρι της εκκεντρικής σωματικής κομεντί.","fact":"Το κόμικ στο οποίο βασίζεται η ταινία ήταν πολύ πιο σκοτεινό και σκληρό από την κομεντί που βγήκε τελικά.","wiki_en":"The Mask (film)"},{"name":"Ο Ηλίθιος και ο Πανηλίθιος","emoji":"🚐","meta":["κομεντί","1994","Πίτερ Φάρελι"],"description":"Δύο αφελείς και ελαφρώς κουτοί φίλοι διασχίζουν όλη τη χώρα για να επιστρέψουν μια ξεχασμένη βαλίτσα με λεφτά σε μια όμορφη κοπέλα, χωρίς να υποψιάζονται ότι μέσα είναι λύτρα απαγωγής. Η παράλογη κομεντί με τον Τζιμ Κάρεϊ έγινε κλασικό της δεκαετίας του 1990.","fact":"Το βανάκι των ηρώων, ντυμένο σαν μαλλιαρός σκύλος, έγινε ένα από τα πιο αναγνωρίσιμα αυτοκίνητα της κινηματογραφικής κομεντί.","wiki_en":"Dumb and Dumber"},{"name":"The Hangover","emoji":"🐯","meta":["κομεντί","2009","Τοντ Φίλιπς"],"description":"Τρεις φίλοι ξυπνούν σε μια σουίτα ξενοδοχείου στο Λας Βέγκας μετά από μια τρελή νύχτα πριν από τον γάμο, χωρίς να θυμούνται τίποτα, και ο γαμπρός έχει εξαφανιστεί. Η κομεντί στήνεται γύρω από τις προσπάθειές τους να ανασυνθέσουν τη νύχτα από θρύψαλα στοιχείων.","fact":"Έγινε μια από τις εμπορικότερες κομεντί ακατάλληλης σήμανσης σε όλη την ιστορία των αιθουσών.","wiki_en":"The Hangover"},{"name":"American Pie","emoji":"🥧","meta":["εφηβική κομεντί","1999","Πολ Βάιτς"],"description":"Τέσσερις τελειόφοιτοι λυκείου κάνουν συμφωνία να χάσουν την παρθενιά τους πριν από τον χορό και περνούν για αυτό μια σειρά αμήχανων και ξεκαρδιστικών καταστάσεων. Η ταινία έγινε μια από τις πιο αναγνωρίσιμες εφηβικές κομεντί της εποχής και γέννησε ολόκληρη σειρά.","fact":"Γυρισμένη με πολύ μικρό προϋπολογισμό, η κομεντί έκανε απρόσμενα πάνω από διακόσια εκατομμύρια δολάρια παγκοσμίως.","wiki_en":"American Pie (film)"},{"name":"Ο Διάβολος Φοράει Prada","emoji":"👜","meta":["δραματική κομεντί","2006","Ντέιβιντ Φράνκελ"],"description":"Μια απόφοιτη δημοσιογραφίας πιάνει δουλειά βοηθός της δεσποτικής και απαιτητικής διευθύντριας ενός περιοδικού μόδας και χάνει σιγά σιγά τον εαυτό της κυνηγώντας την επιτυχία. Το μυθιστόρημα της Λόρεν Βάισμπεργκερ βασίστηκε στη δική της θητεία στον χώρο.","fact":"Πρότυπο για την αυταρχική ηρωίδα θεωρείται η Άννα Γουίντουρ, η θρυλική διευθύντρια της αμερικανικής Vogue.","wiki_en":"The Devil Wears Prada (film)"},{"name":"La La Land","emoji":"🎹","meta":["μιούζικαλ","2016","Ντάμιεν Σαζέλ"],"description":"Μια πρωτάρα ηθοποιός και ένας πιανίστας της τζαζ ερωτεύονται στο σημερινό Λος Άντζελες, προσπαθώντας να μη θυσιάσουν τις δικές τους καλλιτεχνικές φιλοδοξίες. Το μιούζικαλ αποτίει φόρο τιμής στα κλασικά του Χόλιγουντ και ξεχωρίζει για το χρώμα και τα χορευτικά του.","fact":"Στην τελετή των Όσκαρ η ταινία ανακοινώθηκε κατά λάθος ως καλύτερη ταινία και κράτησε το βραβείο για λίγα λεπτά, πριν ακουστεί ο αληθινός νικητής.","wiki_en":"La La Land (film)"},{"name":"Whiplash","emoji":"🥁","meta":["δράμα","2014","Ντάμιεν Σαζέλ"],"description":"Ένας φιλόδοξος νέος ντράμερ του ωδείου βρίσκεται στην τάξη ενός σκληρού και απαιτητικού μαέστρου, που ταπεινώνει τους σπουδαστές στο όνομα της μουσικής τελειότητας. Η ταινία μετρά το κόστος της εμμονής και στήνεται πάνω στη μονομαχία δασκάλου και μαθητή.","fact":"Ο Τζ. Κ. Σίμονς πήρε το Όσκαρ δεύτερου ανδρικού ρόλου για τον δεσποτικό δάσκαλο.","wiki_en":"Whiplash (2014 film)"},{"name":"Παράσιτα","emoji":"🪨","meta":["κοινωνικό θρίλερ","2019","Μπονγκ Τζουν-χο"],"description":"Μια φτωχή οικογένεια από ένα ημιυπόγειο της Σεούλ τρυπώνει σιγά σιγά, με δουλειές και με ψέματα, στο σπίτι μιας πλούσιας οικογένειας. Η νοτιοκορεάτικη ταινία δένει τη μαύρη κομεντί με ένα κοφτερό κοινωνικό δράμα για την ανισότητα.","fact":"Ήταν η πρώτη μη αγγλόφωνη ταινία στην ιστορία που πήρε Όσκαρ καλύτερης ταινίας.","wiki_en":"Parasite (2019 film)"},{"name":"Oppenheimer","emoji":"☢️","meta":["βιογραφικό δράμα","2023","Κρίστοφερ Νόλαν"],"description":"Ο φυσικός Ρόμπερτ Οπενχάιμερ ηγείται του μυστικού Σχεδίου Μανχάταν για την πρώτη ατομική βόμβα και, μετά τον πόλεμο, έρχεται αντιμέτωπος με τις πολιτικές συνέπειες και το ηθικό βάρος της εφεύρεσής του. Ο Κρίστοφερ Νόλαν γύρισε την ταινία κυρίως σε φιλμ.","fact":"Η έκρηξη της ατομικής βόμβας για τη σκηνή της δοκιμής «Τρίνιτι» αναπαραστάθηκε με πραγματικά εφέ, χωρίς ψηφιακά γραφικά.","wiki_en":"Oppenheimer (film)"},{"name":"Barbie","emoji":"💗","meta":["κομεντί","2023","Γκρέτα Γκέργουιγκ"],"description":"Η κλασική κούκλα Barbie, σε έναν τέλειο ροζ κόσμο, αρχίζει απρόσμενα να σκέφτεται τον θάνατο και την ατέλεια και ξεκινά με τον Κεν για τον αληθινό κόσμο, να βρει τον εαυτό της. Η ταινία δένει τη φωτεινή κομεντί με ένα ειρωνικό σχόλιο για την πιο γνωστή κούκλα.","fact":"Η παραγωγή αγόρασε τόσο ροζ χρώμα για τα σκηνικά που, όπως λέγεται, προκάλεσε προσωρινή έλλειψη στην αγορά.","wiki_en":"Barbie (film)"},{"name":"Dune","emoji":"🏜️","meta":["επιστημονική φαντασία","2021","Ντενί Βιλνέβ"],"description":"Ο κληρονόμος ενός αρχοντικού οίκου αναλαμβάνει τη διοίκηση του ερημικού πλανήτη Αρράκις, της μοναδικής πηγής της πολυτιμότερης ουσίας του σύμπαντος, και μπλέκεται σε θανάσιμες πολιτικές ίντριγκες. Η μεταφορά του Φρανκ Χέρμπερτ έμεινε για τα σκουλήκια της άμμου.","fact":"Για δεκαετίες το μυθιστόρημα του Φρανκ Χέρμπερτ θεωρούνταν αδύνατο να μεταφερθεί στο σινεμά, λόγω της πολυπλοκότητας του κόσμου του.","wiki_en":"Dune (2021 film)"},{"name":"Top Gun: Maverick","emoji":"✈️","meta":["ταινία δράσης","2022","Τζόζεφ Κοζίνσκι"],"description":"Ο βετεράνος πιλότος Μάβερικ επιστρέφει ως εκπαιδευτής στην επίλεκτη σχολή πιλότων, για να ετοιμάσει μια νέα γενιά για μια αποστολή που μοιάζει ανέφικτη. Δεκαετίες μετά την πρώτη ταινία, η συνέχεια έμεινε για τους αληθινούς αεροπορικούς ελιγμούς της.","fact":"Οι ηθοποιοί πέρασαν εκπαίδευση πτήσης και γυρίστηκαν μέσα σε αληθινά αεριωθούμενα, σε ελιγμούς με πραγματικές επιταχύνσεις.","wiki_en":"Top Gun: Maverick"},{"name":"The Hunger Games","emoji":"🏹","meta":["ταινία δράσης και φαντασίας","2012","Γκάρι Ρος"],"description":"Σε ένα δυστοπικό μέλλον, έφηβοι από τις φτωχές περιφέρειες στέλνονται κάθε χρόνο σε ένα τηλεοπτικό παιχνίδι μέχρι θανάτου, και μια κοπέλα δηλώνεται εθελόντρια στη θέση της μικρής αδελφής της. Η μεταφορά της Σούζαν Κόλινς έγινε μεγάλη εφηβική σειρά ταινιών.","fact":"Ο χαιρετισμός με τα τρία δάχτυλα, που ήρθε από τα βιβλία, χρησιμοποιήθηκε αργότερα ως σύμβολο διαμαρτυρίας σε διάφορες χώρες.","wiki_en":"The Hunger Games (film)"},{"name":"Twilight","emoji":"🧛","meta":["ρομαντικό δράμα φαντασίας","2008","Κάθριν Χάρντγουικ"],"description":"Μια συνηθισμένη μαθήτρια μετακομίζει σε μια μικρή βροχερή πόλη και ερωτεύεται έναν μυστηριώδη συμμαθητή, που αποδεικνύεται βαμπίρ σε πόλεμο με τη φύση του. Το μυθιστόρημα της Στεφενί Μέγιερ γέννησε μια από τις πιο προβεβλημένες εφηβικές σειρές με βαμπίρ.","fact":"Το Φορκς, η μικρή πόλη της Ουάσινγκτον όπου εξελίσσεται η ιστορία, έγινε τόπος προσκυνήματος για τους θαυμαστές μετά την ταινία.","wiki_en":"Twilight (2008 film)"},{"name":"Intouchables","emoji":"🤝","meta":["δραματική κομεντί","2011","Ολιβιέ Νακάς, Ερίκ Τολεντάνο"],"description":"Ένας πλούσιος αριστοκράτης, παράλυτος μετά από ατύχημα, προσλαμβάνει βοηθό του ένα νέο παιδί από φτωχό προάστιο, χωρίς καμία εμπειρία, και ανάμεσα σε δύο ανθρώπους που δεν έχουν τίποτα κοινό γεννιέται γερή φιλία. Η γαλλική ταινία βασίζεται σε αληθινή ιστορία.","fact":"Η υπόθεση βγήκε από την αληθινή φιλία του επιχειρηματία Φιλίπ Πότσο ντι Μπόργκο με τον βοηθό του.","wiki_en":"The Intouchables"},{"name":"Αμελί","emoji":"🎨","meta":["ρομαντική κομεντί","2001","Ζαν-Πιερ Ζενέ"],"description":"Μια ντροπαλή σερβιτόρα ενός παρισινού καφέ αποφασίζει να επεμβαίνει κρυφά και ευφάνταστα στις ζωές των γύρω της, στήνοντας μικρά καλά θαύματα και μένοντας η ίδια στη σκιά. Η ταινία έμεινε για το έντονα στιλιζαρισμένο Παρίσι της.","fact":"Πολλές σκηνές γυρίστηκαν σε ένα υπαρκτό καφέ της Μονμάρτρης, που μετά την πρεμιέρα έγινε τουριστικό αξιοθέατο.","wiki_en":"Amélie"},{"name":"Η Ζωή Είναι Ωραία","emoji":"🎪","meta":["τραγικωμωδία","1997","Ρομπέρτο Μπενίνι"],"description":"Ένας Εβραίος πατέρας στην κατεχόμενη από τους ναζί Ιταλία, κλεισμένος με τον μικρό γιο του σε στρατόπεδο, μετατρέπει τον εφιάλτη σε παιχνίδι που επινοεί για το παιδί, ώστε να προστατέψει την ψυχή του. Το μείγμα κομεντί και Ολοκαυτώματος χώρισε τους κριτικούς.","fact":"Ο Ρομπέρτο Μπενίνι σκηνοθέτησε, συνέγραψε το σενάριο και έπαιξε τον πρωταγωνιστικό ρόλο, για τον οποίο πήρε Όσκαρ.","wiki_en":"Life Is Beautiful"},{"name":"Ο Καλός, ο Κακός και ο Άσχημος","emoji":"🤠","meta":["γουέστερν","1966","Σέρτζιο Λεόνε"],"description":"Τρεις άντρες κυνηγούν το ίδιο έπαθλο — ένας ψύχραιμος πιστολέρο, ένας αδίστακτος πληρωμένος δολοφόνος και ένας πονηρός απατεώνας — στα ίχνη χρυσού του Εμφυλίου, θαμμένου σε ανώνυμο τάφο. Το ιταλικό γουέστερν του Λεόνε, με μουσική Μορικόνε, κλείνει την «τριλογία του δολαρίου».","fact":"Η περίφημη τριπλή μονομαχία του φινάλε είναι μονταρισμένη σχεδόν μουσικά, ανάμεσα σε κοντινά πλάνα προσώπων και χεριών.","wiki_en":"The Good, the Bad and the Ugly"},{"name":"Ψυχώ","emoji":"🚿","meta":["ψυχολογικό θρίλερ","1960","Άλφρεντ Χίτσκοκ"],"description":"Μια νέα γυναίκα που κρύβεται αφού έκλεψε ένα μεγάλο ποσό σταματά σε ένα απομονωμένο μοτέλ του δρόμου, το οποίο κρατά ένας παράξενος νέος υπό τη σκιά μιας δεσποτικής μητέρας. Η ταινία του Χίτσκοκ άλλαξε όλα όσα ξέραμε για το πώς χτίζεται η αγωνία.","fact":"Ο φόνος στο ντους, μια από τις πιο διάσημες σκηνές του σινεμά, γυρίστηκε σε πολλές μέρες για μετρημένα δευτερόλεπτα οθόνης.","wiki_en":"Psycho (1960 film)"},{"name":"Η Λάμψη","emoji":"🪓","meta":["ψυχολογικός τρόμος","1980","Στάνλεϊ Κιούμπρικ"],"description":"Ένας συγγραφέας πιάνει δουλειά επιστάτης σε ένα απομονωμένο ορεινό ξενοδοχείο για τη χειμερινή σεζόν μαζί με την οικογένειά του, αλλά σιγά σιγά υποκύπτει στη σκοτεινή δύναμη που κατοικεί στους τοίχους. Η μεταφορά του Στίβεν Κινγκ είναι από τις πιο ατμοσφαιρικές του τρόμου.","fact":"Ο Στίβεν Κινγκ, που έγραψε το βιβλίο, ήταν για χρόνια δυσαρεστημένος με την ανάγνωση του Κιούμπρικ και τη θεωρούσε πολύ ψυχρή.","wiki_en":"The Shining (film)"},{"name":"2001: Η Οδύσσεια του Διαστήματος","emoji":"🪐","meta":["επιστημονική φαντασία","1968","Στάνλεϊ Κιούμπρικ"],"description":"Ένας μυστηριώδης μαύρος μονόλιθος σπρώχνει μπροστά την ανθρωπότητα, από τους πρωτόγονους προγόνους μέχρι ένα ταξίδι στον Δία, όπου το πλήρωμα ενός σκάφους συγκρούεται με μια εξεγερμένη τεχνητή νοημοσύνη. Η ταινία έμεινε για τον διαλογιστικό ρυθμό και τα εφέ της.","fact":"Πολλά εφέ, φτιαγμένα πριν πατήσει άνθρωπος στη Σελήνη, πείθουν ακόμη χωρίς ούτε ένα καρέ ψηφιακών γραφικών.","wiki_en":"2001: A Space Odyssey (film)"},{"name":"Το Κουρδιστό Πορτοκάλι","emoji":"👁️","meta":["δυστοπία","1971","Στάνλεϊ Κιούμπρικ"],"description":"Ο νεαρός αρχηγός μιας συμμορίας του δρόμου σε ένα δυστοπικό Λονδίνο περνά από μια πειραματική κρατική θεραπεία που θέλει να του κόψει τη ροπή προς τη βία. Η μεταφορά του μυθιστορήματος του Άντονι Μπέρτζες προκάλεσε σφοδρές διαμάχες για την ωμή βία της.","fact":"Μετά από ένα κύμα κριτικής και πράξεις βίας κατά μίμηση, ο ίδιος ο Κιούμπρικ απέσυρε την ταινία από τις βρετανικές αίθουσες για πολλά χρόνια.","wiki_en":"A Clockwork Orange (film)"},{"name":"Καζαμπλάνκα","emoji":"🍸","meta":["ρομαντικό δράμα","1942","Μάικλ Κέρτιζ"],"description":"Ο ιδιοκτήτης ενός μπαρ στην Καζαμπλάνκα, υπό την κυβέρνηση του Βισύ, συναντά ξανά την παλιά του αγαπημένη, που φτάνει με τον άντρα της, μέλος της Αντίστασης, ψάχνοντας διέξοδο από τους ναζί. Γυρισμένη μέσα στον πόλεμο, έγινε το πρότυπο του ρομαντικού Χόλιγουντ.","fact":"Η φράση «Εδώ αρχίζει μια όμορφη φιλία» και πολλές άλλες ατάκες είναι από τις πιο πολυαναφερόμενες στην ιστορία του σινεμά.","wiki_en":"Casablanca (film)"},{"name":"Όσα Παίρνει ο Άνεμος","emoji":"🌾","meta":["ιστορικό ρομαντικό δράμα","1939","Βίκτορ Φλέμινγκ"],"description":"Η πεισματάρα κόρη ενός φυτευτή περνά τον Αμερικανικό Εμφύλιο και τα χρόνια που ακολουθούν, παλεύοντας απεγνωσμένα να κρατήσει το σπίτι της και κυνηγώντας άντρες που δεν μπορεί να έχει. Η τεράστια μεταφορά του μυθιστορήματος της Μάργκαρετ Μίτσελ έσπασε κάθε ρεκόρ.","fact":"Με βάση τον σημερινό πληθωρισμό, θεωρείται ακόμη μια από τις εμπορικότερες ταινίες στην ιστορία του κινηματογράφου.","wiki_en":"Gone with the Wind (film)"},{"name":"Ο Μάγος του Οζ","emoji":"🌈","meta":["μιούζικαλ","1939","Βίκτορ Φλέμινγκ"],"description":"Ένας ανεμοστρόβιλος παρασύρει ένα κορίτσι από το Κάνσας μαζί με το σπίτι του σε μια μαγική χώρα, και εκείνο πρέπει να ακολουθήσει τον κίτρινο πλακόστρωτο δρόμο ως τη Σμαραγδένια Πόλη για να γυρίσει σπίτι. Μια από τις πρώτες έγχρωμες μεγάλες επιτυχίες του Χόλιγουντ.","fact":"Το πέρασμα από το ασπρόμαυρο Κάνσας στο έγχρωμο Οζ είναι ένα από τα διασημότερα οπτικά τεχνάσματα του σινεμά.","wiki_en":"The Wizard of Oz (1939 film)"},{"name":"Πρόγευμα με Διαμάντια","emoji":"💎","meta":["ρομαντική κομεντί","1961","Μπλέικ Έντουαρντς"],"description":"Η Χόλι Γκολάιτλι, μια εκκεντρική κοσμική κοπέλα της Νέας Υόρκης που ζει με όνειρα χλιδής και αποφεύγει τους δεσμούς, πιάνει φιλία με τον νέο της γείτονα. Η νουβέλα του Τρούμαν Καπότε χάρισε στον αιώνα ένα είδωλο στιλ: μαύρο φόρεμα και μακριά πίπα.","fact":"Το μαύρο φόρεμα Givenchy της ηρωίδας, από μια από τις πιο γνωστές σκηνές, πουλήθηκε αργότερα σε δημοπρασία για ποσό ρεκόρ.","wiki_en":"Breakfast at Tiffany's (film)"},{"name":"Διακοπές στη Ρώμη","emoji":"🛵","meta":["ρομαντική κομεντί","1953","Γουίλιαμ Γουάιλερ"],"description":"Μια Ευρωπαία πριγκίπισσα, κουρασμένη από το πρωτόκολλο, ξεγλιστρά για μια νύχτα από τους συνοδούς της σε επίσκεψη στη Ρώμη και, κρύβοντας τον τίτλο της, περνά μια μέρα με έναν Αμερικανό δημοσιογράφο. Η ταινία χάρισε στην Όντρεϊ Χέπμπορν το πρώτο της Όσκαρ.","fact":"Η βόλτα των ηρώων με το σκούτερ στη Ρώμη εκτόξευσε τη δημοτικότητα της Vespa μετά την ταινία.","wiki_en":"Roman Holiday"},{"name":"Στη Φωλιά του Κούκου","emoji":"🏥","meta":["δράμα","1975","Μίλος Φόρμαν"],"description":"Ένας άντρας που προσποιείται ψυχική διαταραχή για να αποφύγει τη φυλακή καταλήγει σε ψυχιατρείο και σιγά σιγά εξεγείρεται κατά της σιδερένιας τάξης που κρατά μια αυστηρή προϊσταμένη νοσοκόμα. Η μεταφορά του Κεν Κίζι πήρε και τα πέντε μεγάλα Όσκαρ.","fact":"Γυρίστηκε σε ένα πραγματικό ψυχιατρείο του Όρεγκον, και ο διευθυντής του έπαιξε μάλιστα έναν μικρό ρόλο.","wiki_en":"One Flew Over the Cuckoo's Nest (film)"},{"name":"Αποκάλυψη Τώρα","emoji":"🚁","meta":["πολεμικό δράμα","1979","Φράνσις Φορντ Κόπολα"],"description":"Ένας Αμερικανός λοχαγός παίρνει μυστική εντολή να βρει και να εξοντώσει έναν συνταγματάρχη που αγρίεψε στη ζούγκλα και έφτιαξε δική του λατρεία μέσα στον πόλεμο του Βιετνάμ. Εμπνευσμένη από τον Τζόζεφ Κόνραντ, η ταινία είχε γυρίσματα που κράτησαν χρόνια.","fact":"Τα γυρίσματα ξέφυγαν τόσο πολύ από κάθε έλεγχο που αργότερα γυρίστηκε ξεχωριστό ντοκιμαντέρ γι' αυτά.","wiki_en":"Apocalypse Now"},{"name":"Οι Εφτά Σαμουράι","emoji":"⚔️","meta":["περιπετειώδες δράμα","1954","Ακίρα Κουροσάβα"],"description":"Ένα φτωχό ιαπωνικό χωριό προσλαμβάνει εφτά περιπλανώμενους σαμουράι για να το υπερασπιστούν από τις επιδρομές ληστών, και εκείνοι μαθαίνουν στους χωρικούς να αμύνονται. Το έπος του Ακίρα Κουροσάβα σημάδεψε το παγκόσμιο σινεμά και γέννησε τους «Επτά Γενναίους».","fact":"Όταν βγήκε, ήταν από τις ακριβότερες και πιο χρονοβόρες παραγωγές στην ιστορία του ιαπωνικού κινηματογράφου.","wiki_en":"Seven Samurai"},{"name":"Η Ειρωνεία της Μοίρας","emoji":"🎄","meta":["πρωτοχρονιάτικη κομεντί","1975","Ελντάρ Ριαζάνοφ"],"description":"Την παραμονή της Πρωτοχρονιάς μια παρέα φίλων τηρεί το έθιμο του λουτρού, και τον πιωμένο ήρωα τον βάζουν σε λάθος πτήση: ξυπνά σε άλλη πόλη, σε ξένο σπίτι με ολόιδια διεύθυνση. Η ρωσική τηλεόραση την προβάλλει κάθε Πρωτοχρονιά εδώ και δεκαετίες.","fact":"Τα τραγούδια μελοποιούν ποιήματα της Τσβετάγεβα, του Παστερνάκ και της Αχμαντούλινα, σε μουσική του Μικαέλ Ταριβερντίεφ.","wiki_en":"The Irony of Fate"},{"name":"Το Διαμαντένιο Χέρι","emoji":"💎","meta":["εκκεντρική κομεντί","1968","Λεονίντ Γκαϊντάι"],"description":"Έναν Σοβιετικό τουρίστα τον περνούν για κούριερ λαθρεμπόρων και, σε μια κρουαζιέρα στο εξωτερικό, του κρύβουν μια παρτίδα κοσμημάτων μέσα στον γύψο του χεριού του. Η κομεντί του Λεονίντ Γκαϊντάι έγινε ατάκες και τραγούδια και αγαπιέται ακόμη.","fact":"Το τραγούδι της ταινίας για το «Νησί της Κακοτυχίας» έγινε τόσο δημοφιλές που απέκτησε δική του ζωή.","wiki_en":"The Diamond Arm"},{"name":"Επιχείρηση «Υ» και άλλες περιπέτειες του Σούρικ","emoji":"🧱","meta":["εκκεντρική κομεντί","1965","Λεονίντ Γκαϊντάι"],"description":"Τρεις ξεχωριστές ιστορίες με τον άτυχο φοιτητή Σούρικ: τα βάζει με έναν τεμπέλη σε εργοτάξιο, δίνει εξετάσεις και χαλάει το σχέδιο απατεώνων να ληστέψουν μια αποθήκη. Η ταινία του Γκαϊντάι έχει και το περίφημο τρίο των μικροκακοποιών του.","fact":"Το τρίο των μικροκακοποιών είχε πρωτοεμφανιστεί σε μικρού μήκους ταινίες του Γκαϊντάι στις αρχές της δεκαετίας του 1960.","wiki_en":"Operation Y and Other Shurik's Adventures"},{"name":"Απαγωγή στον Καύκασο","emoji":"🐴","meta":["εκκεντρική κομεντί","1966","Λεονίντ Γκαϊντάι"],"description":"Ο φοιτητής Σούρικ, σε επίσκεψη στον Καύκασο, μπλέκει άθελά του στην απαγωγή μιας κοπέλας που ένας τοπικός αξιωματούχος θέλει να πάρει γυναίκα παρά τη θέλησή της, και ξεκινά να τη σώσει. Η κομεντί του Γκαϊντάι είναι από τις πιο πολυαναφερόμενες σοβιετικές ταινίες.","fact":"Ατάκες της ταινίας, όπως η πρόποση για τους αιωνόβιους ορεσίβιους και το «κρίμα το πουλάκι», ζουν ακόμη στα ρωσικά.","wiki_en":"Kidnapping, Caucasian Style"},{"name":"Ο Ιβάν Βασίλιεβιτς Αλλάζει Επάγγελμα","emoji":"👑","meta":["εκκεντρική κομεντί","1973","Λεονίντ Γκαϊντάι"],"description":"Η αυτοσχέδια μηχανή του χρόνου ενός εφευρέτη στέλνει κατά λάθος τον διαχειριστή μιας πολυκατοικίας στην εποχή του Ιβάν του Τρομερού και τον τσάρο σε ένα σοβιετικό διαμέρισμα, με κωμικά μπερδέματα. Βασίζεται σε θεατρικό του Μιχαήλ Μπουλγκάκοφ.","fact":"Και τον τρομερό τσάρο και τον δειλό διαχειριστή Μπούνσα τους παίζει ο ίδιος ηθοποιός, ο Γιούρι Γιακόβλεφ.","wiki_en":"Ivan Vasilievich: Back to the Future"},{"name":"Οι Τζέντλεμαν της Τύχης","emoji":"🎩","meta":["αστυνομική κομεντί","1971","Αλεξάντρ Σερί"],"description":"Έναν καλόκαρδο διευθυντή παιδικού σταθμού, φτυστό έναν σκληροτράχηλο κατάδικο, τον βάζουν να παραστήσει τον εγκληματία, ώστε να αποσπάσει από τους συγκρατούμενους πού κρύβεται ένα κλεμμένο χρυσό κράνος. Η κομεντί έγινε αμέσως παροιμιώδης.","fact":"Πολλές ατάκες της, όπως «Ποιος θα τον φυλακίσει; Μνημείο είναι!», πέρασαν κατευθείαν στην καθημερινή γλώσσα.","wiki_en":"Gentlemen of Fortune"},{"name":"Η Μόσχα δεν Πιστεύει στα Δάκρυα","emoji":"🏙️","meta":["ρομαντικό δράμα","1980","Βλαντίμιρ Μενσόφ"],"description":"Τρεις νέες κοπέλες φτάνουν από την επαρχία να κατακτήσουν τη Μόσχα στα τέλη της δεκαετίας του 1950· η ταινία τις ξαναβρίσκει είκοσι χρόνια μετά, όταν οι ζωές τους έχουν πάρει πολύ διαφορετικούς δρόμους. Πήρε το Όσκαρ ξενόγλωσσης ταινίας.","fact":"Ο σκηνοθέτης Βλαντίμιρ Μενσόφ δεν μπόρεσε να πάει στην τελετή και παρέλαβε το αγαλματίδιό του πολλά χρόνια αργότερα.","wiki_en":"Moscow Does Not Believe in Tears"},{"name":"Ειδύλλιο στο Γραφείο","emoji":"💼","meta":["τρυφερή κομεντί","1977","Ελντάρ Ριαζάνοφ"],"description":"Η αυστηρή και αδιόρατη για τους γύρω της διευθύντρια μιας στατιστικής υπηρεσίας ερωτεύεται χωρίς να το περιμένει έναν καινούριο, συνεσταλμένο υπάλληλο, που αποφασίζει να τη βοηθήσει να νιώσει πιο σίγουρη και πιο όμορφη. Η ταινία ξαναβλέπεται ακούραστα.","fact":"Βγήκε από το θεατρικό «Συνάδελφοι», που έγραψε ο Ελντάρ Ριαζάνοφ με τον Εμίλ Μπραγκίνσκι και παιζόταν ήδη στη σκηνή.","wiki_en":"Office Romance"},{"name":"Έρωτας και Περιστέρια","emoji":"🕊️","meta":["τρυφερή κομεντί","1984","Βλαντίμιρ Μενσόφ"],"description":"Ένας απλός οικογενειάρχης από τη ρωσική επαρχία πάει σε λουτρόπολη, ερωτεύεται απρόσμενα μια κοσμική λουόμενη και αφήνει για λίγο την οικογένειά του, ενώ γυναίκα και παιδιά προσπαθούν να τον φέρουν πίσω. Η κομεντί αγαπήθηκε πολύ για τη ζωή στο χωριό.","fact":"Τον μπεκρή θείο Μίτια τον παίζει ο Σεργκέι Γιούρσκι, ηθοποιός εντελώς άλλου, αστικού τύπου, με βαρύ μακιγιάζ για τον ρόλο.","wiki_en":"Love and Doves"},{"name":"Ο Λευκός Ήλιος της Ερήμου","emoji":"🏜️","meta":["σοβιετικό γουέστερν","1970","Βλαντίμιρ Μοτίλ"],"description":"Ο αποστρατευμένος ερυθροστρατιώτης Σουχόφ, γυρίζοντας σπίτι μέσα από την έρημο της Κεντρικής Ασίας, βρίσκεται να προστατεύει ολόκληρο το χαρέμι ενός καταδιωκόμενου αρχιληστή από τον πρώην κύριό του. Οι Ρώσοι κοσμοναύτες τη βλέπουν παραδοσιακά πριν από κάθε εκτόξευση.","fact":"Το τραγούδι «Εξοχότατη κυρία Τύχη», σε στίχους του Μπουλάτ Οκουτζάβα, το τραγούδησε ο Πάβελ Λουσπεκάγεφ.","wiki_en":"White Sun of the Desert"},{"name":"Ο Αδελφός","emoji":"🔫","meta":["αστυνομικό δράμα","1997","Αλεξέι Μπαλαμπάνοφ"],"description":"Ένα παλικάρι μόλις απολυμένο από τον στρατό φτάνει στην Πετρούπολη στον μεγάλο του αδελφό και μπλέκεται σιγά σιγά στους εγκληματικούς πολέμους της δεκαετίας του 1990, με τη δική του αντίληψη για το δίκαιο. Η ταινία έγινε πορτρέτο της μετασοβιετικής εποχής.","fact":"Η μουσική του συγκροτήματος Ναουτίλους Πομπίλιους από την ταινία έμεινε δεμένη για πάντα με τη μορφή του ήρωα.","wiki_en":"Brother (1997 film)"},{"name":"Ο Αδελφός 2","emoji":"✈️","meta":["αστυνομικό δράμα","2000","Αλεξέι Μπαλαμπάνοφ"],"description":"Ο ήρωας της πρώτης ταινίας πηγαίνει στην Αμερική για να μάθει τι απέγινε ένας παλιός συμπολεμιστής και να αποκαταστήσει το δίκιο, σε μια χώρα που δεν ξέρει και δεν καταλαβαίνει. Η συνέχεια χάρισε ακόμη πιο πολλές ατάκες και έγινε ο λόγος μιας γενιάς.","fact":"Ο διάλογος για το πού βρίσκεται η δύναμη, στα λεφτά ή στην αλήθεια, είναι από τις πιο αναγνωρίσιμες σκηνές του ρωσικού σινεμά.","wiki_en":"Brother 2"},{"name":"Στάλκερ","emoji":"🌫️","meta":["φιλοσοφική επιστημονική φαντασία","1979","Αντρέι Ταρκόφσκι"],"description":"Ένας οδηγός με το παρατσούκλι Στάλκερ περνά έναν συγγραφέα και έναν επιστήμονα μέσα από τη μυστηριώδη και επικίνδυνη Ζώνη, ως το δωμάτιο όπου, λέει ο μύθος, εκπληρώνεται η κρυφότερη επιθυμία. Ο Ταρκόφσκι έκανε το βιβλίο των αδελφών Στρουγκάτσκι παραβολή για την πίστη.","fact":"Μεγάλο μέρος του υλικού ξαναγυρίστηκε, επειδή καταστράφηκε στην επεξεργασία του φιλμ, και η παραγωγή κράτησε χρόνια.","wiki_en":"Stalker (1979 film)"},{"name":"Ο Πολίτης Κέιν","emoji":"📰","meta":["δράμα","1941","Όρσον Γουέλς"],"description":"Η πρώτη ταινία μεγάλου μήκους του Όρσον Γουέλς, για την άνοδο και την πτώση του μεγαλοεκδότη Τσαρλς Φόστερ Κέιν, μέσα από τις αναμνήσεις των ανθρώπων που τον γνώρισαν. Άλλαξε τη φωτογραφία, το μοντάζ και την αφήγηση και για δεκαετίες ήταν πρώτη σε κάθε λίστα.","fact":"Η μυστηριώδης τελευταία λέξη «Ρόουζμπαντ» έγινε ένα από τα πιο συζητημένα σύμβολα του σινεμά και μένει ανεξήγητη σχεδόν ως το φινάλε.","wiki_en":"Citizen Kane"},{"name":"Το Λιμάνι της Αγωνίας","emoji":"⚓","meta":["δράμα","1954","Ελία Καζάν"],"description":"Η ταινία του Ελία Καζάν για τον πρώην πυγμάχο Τέρι Μαλόι, λιμενεργάτη σε μια πόλη-λιμάνι, που βρίσκεται στριμωγμένος ανάμεσα στη συνδικαλιστική μαφία και τη συνείδησή του. Ο Μάρλον Μπράντο έδωσε μια από τις κορυφαίες ερμηνείες του και η ταινία πήρε οκτώ Όσκαρ.","fact":"Η κουβέντα του Τέρι με τον αδελφό του στο πίσω κάθισμα ενός ταξί είναι από τις πιο πολυσυζητημένες σκηνές ερμηνείας στο σινεμά.","wiki_en":"On the Waterfront"},{"name":"Λώρενς της Αραβίας","emoji":"🐪","meta":["έπος","1962","Ντέιβιντ Λιν"],"description":"Το έπος του Ντέιβιντ Λιν για τον Βρετανό αξιωματικό Τόμας Έντουαρντ Λόρενς, που ένωσε τις αραβικές φυλές σε εξέγερση κατά της Οθωμανικής Αυτοκρατορίας στον Α' Παγκόσμιο Πόλεμο. Η ταινία έμεινε για τα γυρίσματα στην έρημο και πήρε εφτά Όσκαρ.","fact":"Ο ρόλος έκανε αστέρι τον σχεδόν άγνωστο θεατρικό ηθοποιό Πίτερ Οτούλ και του έφερε την πρώτη από οκτώ υποψηφιότητες Όσκαρ, χωρίς ποτέ να το πάρει.","wiki_en":"Lawrence of Arabia (film)"},{"name":"Μπεν Χουρ","emoji":"🏇","meta":["ιστορικό δράμα","1959","Γουίλιαμ Γουάιλερ"],"description":"Από το μυθιστόρημα του Λιου Γουάλας: ο αρχοντικός Ιουδαίος Ιούδας Μπεν Χουρ, προδομένος από φίλο των παιδικών του χρόνων και πουλημένος ως σκλάβος, επιστρέφει για δικαίωση στα χρόνια του Χριστού. Η ταινία έμεινε για την αρματοδρομία και πήρε έντεκα Όσκαρ.","fact":"Η αρματοδρομία γυρίστηκε σε αρκετές εβδομάδες, σε μια τεράστια αρένα που χτίστηκε γι' αυτήν στα στούντιο Τσινετσιτά της Ρώμης.","wiki_en":"Ben-Hur (1959 film)"},{"name":"West Side Story","emoji":"💃","meta":["μιούζικαλ","1961","Ρόμπερτ Γουάιζ"],"description":"Μουσικό δράμα για την έχθρα δύο συμμοριών της Νέας Υόρκης, των Jets και των Sharks, με φόντο την απαγορευμένη αγάπη του Τόνι και της Μαρίας στο πνεύμα του «Ρωμαίου και της Ιουλιέτας». Η μουσική του Λέοναρντ Μπερνστάιν του χάρισε δέκα Όσκαρ.","fact":"Τη χορογραφία έκανε ο Τζερόμ Ρόμπινς, που υπέγραψε τη σκηνοθεσία μαζί με τον Ρόμπερτ Γουάιζ.","wiki_en":"West Side Story (1961 film)"},{"name":"Η Μελωδία της Ευτυχίας","emoji":"🎶","meta":["μιούζικαλ","1965","Ρόμπερτ Γουάιζ"],"description":"Η δόκιμη μοναχή Μαρία γίνεται γκουβερνάντα των εφτά παιδιών ενός αυστηρού Αυστριακού λοχαγού, του φον Τραπ, ενώνει την οικογένεια με τα τραγούδια και μετά τη βοηθά να ξεφύγει από τους ναζί που προσάρτησαν την Αυστρία. Το μιούζικαλ σάρωσε στα ταμεία.","fact":"Τα αλπικά λιβάδια της αρχής γυρίστηκαν γύρω από το Σάλτσμπουργκ, που από τότε έγινε τουριστικός προορισμός.","wiki_en":"The Sound of Music (film)"},{"name":"Ρεβέκκα","emoji":"🏚️","meta":["θρίλερ","1940","Άλφρεντ Χίτσκοκ"],"description":"Η πρώτη ταινία του Άλφρεντ Χίτσκοκ στο Χόλιγουντ, από το μυθιστόρημα της Δάφνης ντι Μοριέ: η νέα σύζυγος ενός πλούσιου χήρου μετακομίζει στο αρχοντικό του, το Μάντερλι, και νιώθει παντού την αόρατη παρουσία της νεκρής πρώτης γυναίκας του. Πήρε Όσκαρ καλύτερης ταινίας.","fact":"Το όνομα της ηρωίδας που αφηγείται την ιστορία δεν ακούγεται ούτε μία φορά σε όλη την ταινία.","wiki_en":"Rebecca (1940 film)"},{"name":"Δεσμώτης του Ιλίγγου","emoji":"🌀","meta":["θρίλερ","1958","Άλφρεντ Χίτσκοκ"],"description":"Ένας ντετέκτιβ με φοβία στα ύψη ερωτεύεται τη μυστηριώδη γυναίκα που τον πλήρωσαν να παρακολουθεί, και η έμμονη ιδέα τον ρουφά σε έναν ιστό απάτης. Ο Χίτσκοκ χρησιμοποίησε ένα νέο τέχνασμα, πλησίασμα της κάμερας με ταυτόχρονο ζουμ προς τα πίσω, το εφέ του ιλίγγου.","fact":"Όταν βγήκε την υποδέχτηκαν χλιαρά, και μισό αιώνα μετά η ψηφοφορία των κριτικών του Sight & Sound την έβαλε πρώτη όλων των εποχών.","wiki_en":"Vertigo (film)"},{"name":"Σιωπηλός Μάρτυς","emoji":"🔭","meta":["θρίλερ","1954","Άλφρεντ Χίτσκοκ"],"description":"Ένας φωτογράφος καθηλωμένος σε αναπηρικό αμαξίδιο παρακολουθεί από πλήξη τους γείτονές του από το παράθυρο και αρχίζει να υποπτεύεται ότι ο ένας σκότωσε τη γυναίκα του. Σχεδόν όλη η ταινία εξελίσσεται μέσα σε ένα δωμάτιο, στο πιο κλειστοφοβικό θρίλερ του Χίτσκοκ.","fact":"Η αυλή και τα γύρω διαμερίσματα χτίστηκαν όλα σε στούντιο ως ένα τεράστιο ενιαίο σκηνικό.","wiki_en":"Rear Window"},{"name":"Τα Πουλιά","emoji":"🐦","meta":["ταινία τρόμου","1963","Άλφρεντ Χίτσκοκ"],"description":"Σε μια παραθαλάσσια πόλη της Καλιφόρνιας τα πουλιά αρχίζουν να επιτίθενται μαζικά στους ανθρώπους χωρίς κανένα φανερό λόγο, κάνοντας την ήσυχη ζωή των κατοίκων εφιάλτη. Ο Χίτσκοκ άφησε επίτηδες την ταινία χωρίς μουσική, μόνο με κρωξίματα και φτεροκοπήματα.","fact":"Στις σκηνές των επιθέσεων χρησιμοποιήθηκαν και μηχανικά και ζωντανά πουλιά, κάποια δεμένα κυριολεκτικά στα ρούχα των ηθοποιών με πετονιά.","wiki_en":"The Birds (film)"},{"name":"Μερικοί το Προτιμούν Καυτό","emoji":"🎷","meta":["κομεντί","1959","Μπίλι Γουάιλντερ"],"description":"Δύο μουσικοί γίνονται κατά τύχη μάρτυρες μιας εκτέλεσης συμμοριών και, για να κρυφτούν από τη μαφία, ντύνονται γυναίκες και μπαίνουν σε μια γυναικεία ορχήστρα τζαζ. Η κομεντί με τη Μέριλιν Μονρόε θεωρείται συχνά η καλύτερη του αμερικανικού σινεμά.","fact":"Η Μέριλιν Μονρόε χρειάστηκε δεκάδες λήψεις για μία απλή ατάκα, και η ιστορία έμεινε ως θρύλος του κινηματογράφου.","wiki_en":"Some Like It Hot"},{"name":"Η Γέφυρα του Ποταμού Κβάι","emoji":"🌉","meta":["πολεμικό δράμα","1957","Ντέιβιντ Λιν"],"description":"Βρετανοί αιχμάλωτοι πολέμου σε ιαπωνικό στρατόπεδο αναγκάζονται να χτίσουν μια σιδηροδρομική γέφυρα, και ο διοικητής τους κάνει το έργο ζήτημα τιμής, ξεχνώντας ότι η γέφυρα θα εξυπηρετήσει τον εχθρό. Πήρε εφτά Όσκαρ, ανάμεσά τους ταινίας και σκηνοθεσίας.","fact":"Το εμβατήριο «Συνταγματάρχης Μπόγκι», που σφυρίζουν οι αιχμάλωτοι, έγινε μια από τις πιο αναγνωρίσιμες μελωδίες του σινεμά.","wiki_en":"The Bridge on the River Kwai"},{"name":"Πέρα από την Αφρική","emoji":"🦁","meta":["δράμα","1985","Σίντνεϊ Πόλακ"],"description":"Βασισμένη στα απομνημονεύματα της Δανέζας συγγραφέως Κάρεν Μπλίξεν: η ζωή της σε μια φυτεία καφέ στην Κένυα των αρχών του 20ού αιώνα και ο έρωτάς της με τον κυνηγό και τυχοδιώκτη Ντένις Φιντς Χάτον. Με τη Μέριλ Στριπ και τον Ρόμπερτ Ρέντφορντ, πήρε εφτά Όσκαρ.","fact":"Το πραγματικό σπίτι της Κάρεν Μπλίξεν στην Κένυα λειτουργεί σήμερα ως μουσείο για τη συγγραφέα και για την ταινία.","wiki_en":"Out of Africa (film)"},{"name":"Χορεύοντας με τους Λύκους","emoji":"🐺","meta":["γουέστερν","1990","Κέβιν Κόστνερ"],"description":"Ένας αξιωματικός της Ένωσης στον Αμερικανικό Εμφύλιο τοποθετείται σε ένα απομακρυσμένο φυλάκιο της μεθορίου και σιγά σιγά πλησιάζει μια φυλή Σιου, παίρνοντας τον τρόπο ζωής και τις αξίες τους. Το σκηνοθετικό ντεμπούτο του Κέβιν Κόστνερ πήρε εφτά Όσκαρ.","fact":"Μεγάλο μέρος των διαλόγων ακούγεται στη γλώσσα λακότα με αγγλικούς υπότιτλους — σπάνιο για μεγάλη παραγωγή του Χόλιγουντ.","wiki_en":"Dances with Wolves"},{"name":"Ο Άγγλος Ασθενής","emoji":"🏜️","meta":["δράμα","1996","Άντονι Μινγκέλα"],"description":"Σε ένα ρημαγμένο από τον πόλεμο ιταλικό μοναστήρι μια νοσοκόμα φροντίζει έναν ασθενή καμένο ως το απροσδιόριστο, και από τις αναμνήσεις του ξεδιπλώνεται μια τραγική ιστορία αγάπης στις ερήμους της Βόρειας Αφρικής. Η μεταφορά του Μάικλ Οντάατζε πήρε εννιά Όσκαρ.","fact":"Οι σκηνές της ερήμου γυρίστηκαν στη Σαχάρα, στη νότια Τυνησία, και του μοναστηριού σε ένα αληθινό παλιό μοναστήρι της Τοσκάνης.","wiki_en":"The English Patient (film)"},{"name":"Αμαντέους","emoji":"🎼","meta":["δράμα","1984","Μίλος Φόρμαν"],"description":"Η ιστορία του συνθέτη Αντόνιο Σαλιέρι και του ιδιοφυούς αλλά ατίθασου Βόλφγκανγκ Αμαντέους Μότσαρτ, όπως την αφηγείται ο γερασμένος Σαλιέρι, φαγωμένος από φθόνο και μεταμέλεια. Η ταινία του Μίλος Φόρμαν πήρε οκτώ Όσκαρ, ανάμεσά τους καλύτερης ταινίας.","fact":"Όσο δραματική κι αν είναι η αντιπαλότητα, οι ιστορικοί θεωρούν την έχθρα Σαλιέρι και Μότσαρτ μυθοπλασία.","wiki_en":"Amadeus (film)"},{"name":"Κάποτε στην Αμερική","emoji":"🎩","meta":["αστυνομικό δράμα","1984","Σέρτζιο Λεόνε"],"description":"Ένας γερασμένος γκάνγκστερ με το παρατσούκλι Νούντλς επιστρέφει στη Νέα Υόρκη δεκαετίες μετά και θυμάται τη νιότη του στους δρόμους της εβραϊκής συνοικίας, τη φιλία και την προδοσία που τον έδεσαν με την παρέα του. Η τελευταία ταινία του Λεόνε, η επική διαθήκη του.","fact":"Η αρχική εκδοχή διαρκεί σχεδόν τέσσερις ώρες· για τις αμερικανικές αίθουσες κόπηκε δραστικά και ξαναμοντάρθηκε σε χρονολογική σειρά.","wiki_en":"Once Upon a Time in America"},{"name":"Ο Εξορκιστής","emoji":"😈","meta":["ταινία τρόμου","1973","Γουίλιαμ Φρίντκιν"],"description":"Μετά από ανεξήγητες αλλαγές στη συμπεριφορά της δωδεκάχρονης κόρης της, μια ηθοποιός ζητά τη βοήθεια ιερέων, που κάνουν στο κορίτσι εξορκισμό. Η ταινία του Γουίλιαμ Φρίντκιν ήταν από τις πρώτες του τρόμου με υποψηφιότητα Όσκαρ καλύτερης ταινίας.","fact":"Στις πρώτες προβολές κάποιοι θεατές λιποθύμησαν, τόσο δυνατή ήταν η επίδραση της ταινίας.","wiki_en":"The Exorcist"},{"name":"Κινγκ Κονγκ","emoji":"🦍","meta":["περιπέτεια","1933","Μέριαν Κούπερ και Έρνεστ Σούντσακ"],"description":"Ένα κινηματογραφικό συνεργείο φτάνει σε ένα χαμένο νησί, βρίσκει έναν γιγάντιο πίθηκο, τον Κινγκ Κονγκ, που οι ντόπιοι λατρεύουν ως θεό, και τον φέρνει στη Νέα Υόρκη για θέαμα. Η ταινία του 1933 ήταν τομή στα σύνθετα γυρίσματα και στην καρέ-καρέ κίνηση.","fact":"Η φιγούρα του Κινγκ Κονγκ για τα καρέ-καρέ γυρίσματα ήταν μόλις μισό μέτρο ψηλή, αν και στην οθόνη φαίνεται τεράστια.","wiki_en":"King Kong (1933 film)"},{"name":"Λίνκολν","emoji":"🎩","meta":["βιογραφικό δράμα","2012","Στίβεν Σπίλμπεργκ"],"description":"Η ταινία του Στίβεν Σπίλμπεργκ επικεντρώνεται στους τελευταίους μήνες της ζωής του προέδρου Αβραάμ Λίνκολν, όταν δίνει την πολιτική μάχη για να περάσει η δέκατη τρίτη τροπολογία και να καταργηθεί η δουλεία. Ο Ντάνιελ Ντέι-Λιούις πήρε το τρίτο του Όσκαρ.","fact":"Ο Ντάνιελ Ντέι-Λιούις προετοιμάστηκε ανασυνθέτοντας τον τρόπο ομιλίας και το βάδισμα του Λίνκολν από περιγραφές συγχρόνων του.","wiki_en":"Lincoln (film)"},{"name":"Love Actually","emoji":"❤️","meta":["ρομαντική κομεντί","2003","Ρίτσαρντ Κέρτις"],"description":"Μια χριστουγεννιάτικη κομεντί που πλέκει τις ιστορίες καμιά δεκαριάς Λονδρέζων, από τον πρωθυπουργό μέχρι ένα σχολιαρόπαιδο, που ο καθένας με τον τρόπο του βρίσκει ή χάνει τον έρωτα πριν από τις γιορτές. Έγινε από τις πιο αγαπημένες χριστουγεννιάτικες ταινίες.","fact":"Γυρισμένη με μέτριο προϋπολογισμό, έκανε πολλαπλάσιες εισπράξεις παγκοσμίως και επιστρέφει στις οθόνες κάθε Χριστούγεννα.","wiki_en":"Love Actually"},{"name":"The Notebook","emoji":"💌","meta":["ρομαντικό δράμα","2004","Νικ Κασσαβέτης"],"description":"Ένας ηλικιωμένος άντρας διαβάζει σε μια τρόφιμο γηροκομείου την ιστορία αγάπης δύο νέων από διαφορετικές κοινωνικές τάξεις, που ο πόλεμος και οι συνθήκες χώρισαν, αλλά κράτησαν το αίσθημα για χρόνια. Το μυθιστόρημα του Νίκολας Σπαρκς έγινε το μελόδραμα της δεκαετίας του 2000.","fact":"Η ταινία γυρίστηκε στη Νότια Καρολίνα, ενώ το βιβλίο στο οποίο βασίζεται τοποθετείται στη γειτονική Βόρεια Καρολίνα.","wiki_en":"The Notebook (2004 film)"},{"name":"Ο Νονός II","emoji":"🍷","meta":["αστυνομικό δράμα","1974","Φράνσις Φορντ Κόπολα"],"description":"Η σάγκα των Κορλεόνε συνεχίζεται σε δύο παράλληλες γραμμές: ο νέος Βίτο Κορλεόνε χτίζει το όνομά του στην αλλαγή του αιώνα, ενώ ο γιος του Μάικλ σφίγγει την εξουσία του στη μεταπολεμική Αμερική. Ήταν η πρώτη συνέχεια στην ιστορία με Όσκαρ καλύτερης ταινίας.","fact":"Ο Ρόμπερτ Ντε Νίρο πήρε Όσκαρ ως ο νέος Βίτο Κορλεόνε, παρότι οι πιο πολλές ατάκες του ακούγονται στη σικελική διάλεκτο.","wiki_en":"The Godfather Part II"},{"name":"The Prestige","emoji":"🎩","meta":["μεταφυσικό δράμα","2006","Κρίστοφερ Νόλαν"],"description":"Δύο Λονδρέζοι ταχυδακτυλουργοί στα τέλη του 19ου αιώνα μετατρέπουν τον επαγγελματικό ανταγωνισμό σε προσωπικό πόλεμο φθοράς, πλειοδοτώντας σε όλο και πιο επικίνδυνες ψευδαισθήσεις. Ο Νόλαν έστησε την ταινία ως παζλ πολλών χρονικών γραμμών που λύνεται στο φινάλε.","fact":"Ο τίτλος παραπέμπει στην τρίτη, τελική πράξη ενός κόλπου, για την οποία μιλούν ρητά οι ίδιοι οι ήρωες.","wiki_en":"The Prestige (film)"},{"name":"Dunkirk","emoji":"🪖","meta":["πολεμικό δράμα","2017","Κρίστοφερ Νόλαν"],"description":"Η ταινία ξαναζωντανεύει την εκκένωση των βρετανικών και συμμαχικών δυνάμεων από τη γαλλική ακτή το 1940, όταν ο στρατός βρέθηκε στριμωγμένος στη θάλασσα από τους Γερμανούς. Ο Νόλαν την αφηγείται σε τρεις γραμμές — στεριά, θάλασσα και αέρα — σε διαφορετικούς χρόνους.","fact":"Για τις αερομαχίες χρησιμοποιήθηκαν αληθινά αεροπλάνα του Β' Παγκοσμίου Πολέμου, όχι μόνο ψηφιακά γραφικά.","wiki_en":"Dunkirk (2017 film)"},{"name":"Tenet","emoji":"⏳","meta":["επιστημονική φαντασία","2020","Κρίστοφερ Νόλαν"],"description":"Ένας ανώνυμος πράκτορας αναλαμβάνει να αποτρέψει μια απειλή που μπορεί να φέρει το τέλος του κόσμου, και για αυτό μαθαίνει μια τεχνολογία που αντιστρέφει τη ροή του χρόνου και τον αφήνει να κινείται προς το παρελθόν σαν σε κάτοπτρο. Από τις πιο δυσνόητες ταινίες του Νόλαν.","fact":"Πολλές «ανάστροφες» σκηνές γυρίστηκαν με τους κασκαντέρ να κινούνται πραγματικά προς τα πίσω, αντί να γυρίσει ανάποδα το φιλμ.","wiki_en":"Tenet (film)"},{"name":"The Dark Knight Rises","emoji":"🦇","meta":["ταινία υπερηρώων","2012","Κρίστοφερ Νόλαν"],"description":"Οχτώ χρόνια μετά την προηγούμενη ταινία, ένας γερασμένος και απογοητευμένος Μπρους Γουέιν πρέπει να ξαναφορέσει την κάπα, όταν το Γκόθαμ απειλείται από τον αδίστακτο μισθοφόρο Μπέιν. Το τελευταίο μέρος της τριλογίας του Νόλαν σάρωσε στα ταμεία.","fact":"Ο Τομ Χάρντι έφτιαξε για τον Μπέιν μια ιδιαίτερη βαθιά φωνή, που ντουμπλαρίστηκε εν μέρει ξανά όταν οι θεατές παραπονέθηκαν ότι δεν ακούγεται.","wiki_en":"The Dark Knight Rises"},{"name":"Man of Steel","emoji":"🦸","meta":["ταινία υπερηρώων","2013","Ζακ Σνάιντερ"],"description":"Η ταινία ξαναγράφει την καταγωγή του Σούπερμαν: ένας εξωγήινος από τον πλανήτη Κρύπτον, μεγαλωμένος στη Γη ως Κλαρκ Κεντ, μαθαίνει να δέχεται τη φύση του και αποφασίζει πώς θα βάλει τις δυνάμεις του στην υπηρεσία των ανθρώπων. Η ταινία ξεκίνησε από την αρχή το σύμπαν της DC.","fact":"Για πρώτη φορά μετά από δεκαετίες, η στολή του Σούπερμαν εδώ αφήνει έξω το γνώριμο κόκκινο σορτσάκι πάνω από το κολάν.","wiki_en":"Man of Steel (film)"},{"name":"Batman v Superman: Dawn of Justice","emoji":"⚔️","meta":["ταινία υπερηρώων","2016","Ζακ Σνάιντερ"],"description":"Ανήσυχος με την καταστροφική δύναμη του Σούπερμαν, ο Μπάτμαν αποφασίζει ότι πρέπει να τον σταματήσει πριν γίνει απειλή για την ανθρωπότητα, και η διαμάχη τους καταλήγει σε επική σύγκρουση των δύο πιο γνωστών ηρώων της DC. Εδώ εμφανίζεται και η πρώτη Wonder Woman.","fact":"Είναι η πρώτη εμφάνιση της Wonder Woman στη μεγάλη οθόνη, με την Γκαλ Γκαντότ, που μετά πρωταγωνίστησε σε δική της σειρά ταινιών.","wiki_en":"Batman v Superman: Dawn of Justice"},{"name":"Justice League","emoji":"🦸‍♂️","meta":["ταινία υπερηρώων","2017","Ζακ Σνάιντερ"],"description":"Ο Μπάτμαν και η Wonder Woman στήνουν μια ομάδα υπερηρώων — τον Φλας, τον Aquaman και τον Cyborg — για να αντιμετωπίσουν τον εξωγήινο εισβολέα Στέπενγουλφ, που ήρθε για τις πηγές δύναμης που κρύβονται στη Γη. Οι βασικοί ήρωες της DC μαζί για πρώτη φορά.","fact":"Μετά την αποχώρηση του Ζακ Σνάιντερ, μέρος των γυρισμάτων και του μοντάζ ολοκλήρωσε ο Τζος Γουίντον, και χρόνια μετά βγήκε η δική του εκδοχή.","wiki_en":"Justice League (film)"},{"name":"Aquaman","emoji":"🔱","meta":["ταινία υπερηρώων","2018","Τζέιμς Ουάν"],"description":"Μισός άνθρωπος και μισός Ατλάντιος, ο Άρθουρ Κάρι μαθαίνει ότι είναι ο νόμιμος κληρονόμος του υποθαλάσσιου θρόνου της Ατλαντίδας και πρέπει να αποτρέψει τον πόλεμο ανάμεσα στον ωκεανό και τη στεριά που ετοιμάζει ο ετεροθαλής αδελφός του. Σάρωσε στα ταμεία.","fact":"Πολλές υποβρύχιες σκηνές γυρίστηκαν σε ειδικές δεξαμενές, με σύστημα συρματόσχοινων που μιμούνταν την αιώρηση, χωρίς νερό.","wiki_en":"Aquaman (film)"},{"name":"Wonder Woman","emoji":"🛡️","meta":["ταινία υπερηρώων","2017","Πάτι Τζένκινς"],"description":"Η Αμαζόνα Νταϊάνα, μεγαλωμένη σε ένα νησί γυναικών πολεμιστριών, αφήνει το σπίτι της για να βοηθήσει να σταματήσει ο Α' Παγκόσμιος Πόλεμος και συναντά για πρώτη φορά τον κόσμο των ανθρώπων έξω από τον παράδεισο της Θεμίσκυρας. Η πρώτη ταινία υπερηρώων με γυναίκα σκηνοθέτη.","fact":"Η Γκαλ Γκαντότ υπηρέτησε στον ισραηλινό στρατό πριν γίνει ηθοποιός, κάτι που τη βοήθησε στις σκηνές μάχης.","wiki_en":"Wonder Woman (2017 film)"},{"name":"Suicide Squad","emoji":"💣","meta":["ταινία υπερηρώων","2016","Ντέιβιντ Έιρ"],"description":"Μια κυβερνητική υπηρεσία μαζεύει από τη φυλακή μια ομάδα επικίνδυνων υπερκακών, υποσχόμενη μείωση ποινής με αντάλλαγμα θανάσιμες μυστικές αποστολές. Η ταινία του Ντέιβιντ Έιρ παρουσίασε καλτ κακούς της DC, ανάμεσά τους τον Τζόκερ και τη Χάρλεϊ Κουίν.","fact":"Η Μάργκο Ρόμπι ετοιμάστηκε για τη Χάρλεϊ Κουίν μελετώντας τα παλιά κόμικς και τα κινούμενα σχέδια της δεκαετίας του 1990.","wiki_en":"Suicide Squad (2016 film)"},{"name":"Logan","emoji":"🐾","meta":["ταινία υπερηρώων","2017","Τζέιμς Μάνγκολντ"],"description":"Γερασμένος και δίχως πια την ικανότητα να αυτοθεραπεύεται, ο Λόγκαν κρύβεται κοντά στα σύνορα μαζί με τον άρρωστο καθηγητή Ξέιβιερ, ώσπου συναντά ένα κορίτσι με δυνάμεις σαν τις δικές του. Η σκληρή ταινία του Τζέιμς Μάνγκολντ πήρε υποψηφιότητα Όσκαρ σεναρίου.","fact":"Μαζί με την κανονική εκδοχή κυκλοφόρησε και μια εντελώς ασπρόμαυρη, με τον τίτλο Logan Noir.","wiki_en":"Logan (film)"},{"name":"X-Men","emoji":"🧬","meta":["ταινία υπερηρώων","2000","Μπράιαν Σίνγκερ"],"description":"Σε ένα κοντινό μέλλον, μεταλλαγμένοι άνθρωποι με παράξενες δυνάμεις κρύβονται από μια εχθρική κοινωνία, ενώ ο καθηγητής Ξέιβιερ μαζεύει μια ομάδα νέων μεταλλαγμένων για να υπερασπιστεί την ειρηνική συμβίωση. Η ταινία ξεκίνησε μια από τις πιο μακρόβιες σειρές υπερηρώων.","fact":"Τα κοστούμια έγιναν επίτηδες από μαύρο δέρμα, στη θέση των φανταχτερών κολάν των κόμικς, για να δείχνει η ταινία πιο αληθινή.","wiki_en":"X-Men (film)"},{"name":"X2: X-Men United","emoji":"🧬","meta":["ταινία υπερηρώων","2003","Μπράιαν Σίνγκερ"],"description":"Μια επίθεση μεταλλαγμένου στον πρόεδρο των ΗΠΑ δίνει σε έναν συνταγματάρχη την αφορμή για μεγάλη επιχείρηση κατά όλων των μεταλλαγμένων, αναγκάζοντας τους X-Men να συμμαχήσουν με τους εχθρούς τους για να σωθούν. Η συνέχεια μεγάλωσε πολύ τον κόσμο της πρώτης ταινίας.","fact":"Πολλοί κριτικοί και θαυμαστές τη λένε μια από τις σπάνιες συνέχειες που ξεπέρασαν την αρχική ταινία.","wiki_en":"X2 (film)"},{"name":"The Wolverine","emoji":"🗡️","meta":["ταινία υπερηρώων","2013","Τζέιμς Μάνγκολντ"],"description":"Ο Λόγκαν πηγαίνει στην Ιαπωνία με πρόσκληση ενός ετοιμοθάνατου μεγιστάνα που κάποτε του έσωσε τη ζωή, και μπλέκεται σε μια μάχη για την κληρονομιά που μπορεί να του κοστίσει για πρώτη φορά την αθανασία του. Ο Μάνγκολντ άφησε τις μεγάλες μάχες για το προσωπικό δράμα.","fact":"Η υπόθεση βασίζεται εν μέρει στα καλτ κόμικς για τον Wolverine των Κρις Κλέρμοντ και Φρανκ Μίλερ.","wiki_en":"The Wolverine (film)"},{"name":"Captain America: The First Avenger","emoji":"🛡️","meta":["ταινία υπερηρώων","2011","Τζο Τζόνστον"],"description":"Ο Στιβ Ρότζερς, ένας αδύναμος αλλά ατρόμητος νέος στον Β' Παγκόσμιο Πόλεμο, γίνεται πειραματόζωο σε ένα μυστικό πρόγραμμα που τον κάνει υπερστρατιώτη, και τα βάζει με τη ναζιστική οργάνωση Hydra. Η ταινία έστησε τη θέση του Κάπτεν Αμέρικα στο σύμπαν της Marvel.","fact":"Ο καχεκτικός Στιβ Ρότζερς φτιάχτηκε με ψηφιακή σμίκρυνση του Κρις Έβανς και με γυρίσματα ενός πιο λεπτού σωσία με το πρόσωπο του ηθοποιού.","wiki_en":"Captain America: The First Avenger"},{"name":"Thor","emoji":"🔨","meta":["ταινία υπερηρώων","2011","Κένεθ Μπράνα"],"description":"Ο Θορ, ο αλαζόνας διάδοχος του θρόνου του Άσγκαρντ, εξορίζεται από τον πατέρα του στη Γη επειδή χάλασε την ειρήνη, δίχως τις θεϊκές δυνάμεις και το σφυρί Μιόλνιρ, και πρέπει να αποδείξει ότι αξίζει τον τίτλο του. Η ταινία έφερε τη σκανδιναβική μυθολογία στη Marvel.","fact":"Ο Κρις Χέμσγουορθ έβαλε αισθητή μυϊκή μάζα για τον ρόλο, αλλάζοντας ριζικά τη φυσική του κατάσταση σε λίγους μήνες.","wiki_en":"Thor (film)"},{"name":"Doctor Strange","emoji":"🌀","meta":["ταινία υπερηρώων","2016","Σκοτ Ντέρικσον"],"description":"Ο Στίβεν Στρέιντζ, ένας λαμπρός και υπεροπτικός νευροχειρουργός που χάνει σε ένα τρακάρισμα την ακρίβεια των χεριών του, ψάχνει θεραπεία, φτάνει σε μια μυστική σχολή στο Κατμαντού και ανακαλύπτει τη μαγεία και τις παράλληλες διαστάσεις. Η ταινία έμεινε για τις λυγισμένες πόλεις της.","fact":"Οι σκηνές με τις πόλεις που λυγίζουν εμπνεύστηκαν από τις οπτικές απάτες του ζωγράφου Μάουριτς Έσερ.","wiki_en":"Doctor Strange (2016 film)"},{"name":"Black Panther","emoji":"🐾","meta":["ταινία υπερηρώων","2018","Ράιαν Κούγκλερ"],"description":"Μετά τον θάνατο του πατέρα του, ο πρίγκιπας Τ'Τσάλα επιστρέφει στη Γουακάντα, ένα τεχνολογικά προηγμένο αφρικανικό βασίλειο κρυμμένο από τον κόσμο, για να πάρει τον θρόνο και να το προστατέψει. Ήταν η πρώτη ταινία υπερηρώων με υποψηφιότητα Όσκαρ καλύτερης ταινίας.","fact":"Οι σχεδιαστές κοστουμιών και σκηνικών στηρίχτηκαν σε αληθινές παραδόσεις διαφόρων αφρικανικών πολιτισμών για να φτιάξουν τη Γουακάντα.","wiki_en":"Black Panther (film)"},{"name":"Ant-Man","emoji":"🐜","meta":["ταινία υπερηρώων","2015","Πέιτον Ριντ"],"description":"Ο μικροκλέφτης Σκοτ Λανγκ παίρνει από τον εφευρέτη Χανκ Πιμ μια στολή που τον κάνει να μικραίνει στο μέγεθος εντόμου και να διοικεί στρατιές μυρμηγκιών, και πρέπει να εμποδίσει την κλοπή μιας επικίνδυνης τεχνολογίας. Η ταινία έφερε στη Marvel έναν πιο κωμικό, μικρό τόνο.","fact":"Η ιδέα της στολής του Ant-Man εμφανίστηκε στα κόμικς από το 1962, πολύ πριν από τα κινηματογραφικά σύμπαντα των υπερηρώων.","wiki_en":"Ant-Man (film)"},{"name":"Spider-Man: Into the Spider-Verse","emoji":"🕸️","meta":["κινούμενα σχέδια","2018","Μπομπ Περσικέτι, Πίτερ Ράμσεϊ, Ρόντνεϊ Ρόθμαν"],"description":"Ο έφηβος Μάιλς Μοράλες αποκτά τις ίδιες δυνάμεις με τον Πίτερ Πάρκερ και γνωρίζει πολλές εκδοχές του Spider-Man από παράλληλα σύμπαντα, που τις ενώνει μια κοινή απειλή. Η ταινία πήρε Όσκαρ κινουμένων σχεδίων και άλλαξε την εικόνα που είχαμε για τους υπερήρωες στα κινούμενα σχέδια.","fact":"Οι σχεδιαστές έφτιαξαν μια τεχνική που μιμείται τον ρυθμό των καρέ των παλιών κόμικς, ακόμη και τις κουκκίδες της τυπογραφίας.","wiki_en":"Spider-Man: Into the Spider-Verse"},{"name":"Venom","emoji":"👅","meta":["ταινία υπερηρώων","2018","Ρούμπεν Φλάισερ"],"description":"Ο ερευνητής δημοσιογράφος Έντι Μπροκ, ψάχνοντας τα άπλυτα μιας εταιρείας, μολύνεται από ένα εξωγήινο συμβιωτικό πλάσμα που δένεται με το σώμα του και του δίνει απάνθρωπη δύναμη, ζητώντας ως αντάλλαγμα να υποταχθεί στα αρπακτικά του ένστικτα. Η ταινία ζει πάνω σε αυτή την ένταση.","fact":"Ο Venom πρωτοεμφανίστηκε στα κόμικς του Spider-Man στα τέλη της δεκαετίας του 1980, ως σκοτεινός αντίποδάς του.","wiki_en":"Venom (2018 film)"},{"name":"Το Χρονικό της Νάρνια: Το Λιοντάρι, η Μάγισσα και η Ντουλάπα","emoji":"🦁","meta":["ταινία φαντασίας","2005","Άντριου Άνταμσον"],"description":"Τέσσερα παιδιά, απομακρυσμένα από το Λονδίνο του πολέμου, περνούν κατά τύχη μέσα από μια ντουλάπα στη Νάρνια, μια μαγική χώρα που η κακιά Λευκή Μάγισσα κρατά σε αιώνιο χειμώνα, και συμμαχούν με το λιοντάρι Ασλάν. Η μεταφορά του Κ. Σ. Λιούις άνοιξε μια ολόκληρη σειρά.","fact":"Τα χιονισμένα τοπία της Νάρνια γυρίστηκαν στη Νέα Ζηλανδία, στην ίδια χώρα με την τριλογία του «Άρχοντα των Δαχτυλιδιών».","wiki_en":"The Chronicles of Narnia: The Lion, the Witch and the Wardrobe"},{"name":"Ο Άρχοντας των Δαχτυλιδιών: Οι Δύο Πύργοι","emoji":"💍","meta":["ταινία φαντασίας","2002","Πίτερ Τζάκσον"],"description":"Το δεύτερο μέρος της τριλογίας του Πίτερ Τζάκσον ακολουθεί τη διαλυμένη Συντροφιά: ο Φρόντο και ο Σαμ τραβούν για τη Μόρντορ με οδηγό τον Γκόλουμ, ενώ οι άλλοι μπλέκουν στη μεγάλη μάχη για το οχυρό του Χελμ. Η μάχη έμεινε ως μια από τις εντυπωσιακότερες του σινεμά.","fact":"Ο Γκόλουμ φτιάχτηκε με σύλληψη κίνησης, μια τεχνική που ο ηθοποιός Άντι Σέρκις βοήθησε πολύ να ωριμάσει.","wiki_en":"The Lord of the Rings: The Two Towers"},{"name":"Ο Άρχοντας των Δαχτυλιδιών: Η Επιστροφή του Βασιλιά","emoji":"👑","meta":["ταινία φαντασίας","2003","Πίτερ Τζάκσον"],"description":"Το τελευταίο μέρος της τριλογίας του Πίτερ Τζάκσον δένει όλες τις γραμμές: οι στρατοί του καλού ετοιμάζονται για την αποφασιστική μάχη στα τείχη της Μίνας Τίριθ, ενώ ο Φρόντο και ο Σαμ συνεχίζουν μόνοι προς το Βουνό της Μοίρας. Πήρε έντεκα Όσκαρ, ρεκόρ.","fact":"Είναι από τις πολύ λίγες ταινίες φαντασίας που πήραν ποτέ Όσκαρ καλύτερης ταινίας.","wiki_en":"The Lord of the Rings: The Return of the King"},{"name":"Ο Χόμπιτ: Ένα Αναπάντεχο Ταξίδι","emoji":"🗝️","meta":["ταινία φαντασίας","2012","Πίτερ Τζάκσον"],"description":"Ο ήσυχος χόμπιτ Μπίλμπο Μπάγκινς βρίσκεται να ακολουθεί μια ομάδα νάνων που ξεκινούν να πάρουν πίσω από τον δράκο Σμάουγκ την αρχαία πατρίδα τους, το Μοναχικό Βουνό. Το πρώτο μέρος της τριλογίας-προεισαγωγής ξαναγύρισε τους θεατές στη Μέση Γη μια δεκαετία μετά.","fact":"Γυρίστηκε με αυξημένο ρυθμό καρέ, 48 το δευτερόλεπτο αντί για τα συνηθισμένα 24, και προβλήθηκε έτσι σε κάποιες αίθουσες, χωρίζοντας τους θεατές.","wiki_en":"The Hobbit: An Unexpected Journey"},{"name":"Ο Χάρι Πότερ και η Κάμαρα με τα Μυστικά","emoji":"🐍","meta":["ταινία φαντασίας","2002","Κρις Κολόμπους"],"description":"Στη δεύτερη χρονιά τους στο Χόγκουαρτς, ο Χάρι και οι φίλοι του βρίσκονται μπροστά σε μυστηριώδεις επιθέσεις κατά μαθητών και προσπαθούν να λύσουν το αίνιγμα της θρυλικής Κάμαρας με τα Μυστικά. Η δεύτερη ταινία βάθυνε τη μυθολογία και το σκοτάδι του μαγικού κόσμου.","fact":"Εδώ ακούγεται για πρώτη φορά τα φιδίσια, η γλώσσα των φιδιών που ο Χάρι αποδεικνύεται ότι μιλάει.","wiki_en":"Harry Potter and the Chamber of Secrets (film)"},{"name":"Ο Χάρι Πότερ και ο Αιχμάλωτος του Αζκαμπάν","emoji":"🐺","meta":["ταινία φαντασίας","2004","Αλφόνσο Κουαρόν"],"description":"Στο Χόγκουαρτς φτάνει η είδηση ότι ο επικίνδυνος εγκληματίας Σείριος Μπλακ δραπέτευσε, και το σχολείο περιπολούν οι ζοφεροί φρουροί του Αζκαμπάν, οι παράφρονες που τρέφονται με ανθρώπινα αισθήματα. Η αλλαγή σκηνοθέτη έδωσε στην τρίτη ταινία πιο σκοτεινό ύφος.","fact":"Ο Αλφόνσο Κουαρόν ζήτησε από τους ηθοποιούς να γράψουν κείμενα με τη φωνή των ηρώων τους, για να τους καταλάβουν καλύτερα πριν τα γυρίσματα.","wiki_en":"Harry Potter and the Prisoner of Azkaban (film)"},{"name":"Ο Χάρι Πότερ και το Κύπελλο της Φωτιάς","emoji":"🔥","meta":["ταινία φαντασίας","2005","Μάικ Νιούελ"],"description":"Το Χόγκουαρτς φιλοξενεί το Τρίαθλο Μαγείας, με μαθητές από άλλες μαγικές σχολές της Ευρώπης, και στους πρωταθλητές βρίσκεται και το όνομα του Χάρι Πότερ, που δεν δήλωσε ποτέ συμμετοχή. Η τέταρτη ταινία βγάζει την ιστορία από το σχολείο σε διεθνή αναμέτρηση.","fact":"Ο Μάικ Νιούελ ήταν ο πρώτος Βρετανός σκηνοθέτης της σειράς: πριν από αυτόν τις ταινίες είχαν κάνει ένας Αμερικανός και ένας Μεξικανός.","wiki_en":"Harry Potter and the Goblet of Fire (film)"},{"name":"Ο Χάρι Πότερ και οι Κλήροι του Θανάτου: Μέρος 2","emoji":"⚡","meta":["ταινία φαντασίας","2011","Ντέιβιντ Γέιτς"],"description":"Η τελευταία ταινία της σάγκα του Χάρι Πότερ φέρνει την τελική μάχη ανάμεσα στις δυνάμεις του καλού και τον Βόλντεμορτ μέσα στα τείχη του Χόγκουαρτς, που γίνεται πεδίο πολέμου. Έκλεισε μια από τις πιο μακρόβιες και κερδοφόρες σειρές του κινηματογράφου.","fact":"Είναι η εμπορικότερη ταινία της σειράς και η μόνη από τις οκτώ που ξεπέρασε το ένα δισεκατομμύριο δολάρια παγκοσμίως.","wiki_en":"Harry Potter and the Deathly Hallows – Part 2"},{"name":"Φανταστικά Ζώα και πού Βρίσκονται","emoji":"🐾","meta":["ταινία φαντασίας","2016","Ντέιβιντ Γέιτς"],"description":"Η παράπλευρη ιστορία του κόσμου του Χάρι Πότερ μεταφέρεται στη Νέα Υόρκη της δεκαετίας του 1920, όπου ο εκκεντρικός μαγοζωολόγος Νιουτ Σκαμάντερ ταξιδεύει με μια βαλίτσα γεμάτη μαγικά πλάσματα και κατά λάθος αφήνει κάποια ελεύθερα. Ο τίτλος είναι βιβλίο που γράφει ο ίδιος.","fact":"Για πρώτη φορά στη σειρά το σενάριο το έγραψε η ίδια η Τζ. Κ. Ρόουλινγκ, και δεν προήλθε από διασκευή βιβλίου της.","wiki_en":"Fantastic Beasts and Where to Find Them (film)"},{"name":"Ο Πόλεμος των Άστρων: Επεισόδιο V – Η Αυτοκρατορία Αντεπιτίθεται","emoji":"❄️","meta":["διαστημική όπερα","1980","Ίρβιν Κέρσνερ"],"description":"Οι επαναστάτες υποχωρούν στον παγωμένο πλανήτη Χοθ υπό την πίεση της Αυτοκρατορίας, και ο Λουκ Σκαϊγουόκερ πηγαίνει στον βαλτώδη Ντάγκομπα να εκπαιδευτεί από τον σοφό δάσκαλο Τζεντάι Γιόντα, ενώ οι φίλοι του ξεφεύγουν από την καταδίωξη. Πολλοί τη λένε την καλύτερη της σάγκα.","fact":"Εδώ βλέπουν οι θεατές για πρώτη φορά τον Γιόντα, που σχεδιάστηκε ως μαριονέτα και κινούνταν από κουκλοπαίκτες.","wiki_en":"The Empire Strikes Back"},{"name":"Ο Πόλεμος των Άστρων: Επεισόδιο VI – Η Επιστροφή των Τζεντάι","emoji":"🌲","meta":["διαστημική όπερα","1983","Ρίτσαρντ Μάρκουαντ"],"description":"Ο Λουκ Σκαϊγουόκερ επιστρέφει για να ελευθερώσει τον Χαν Σόλο από το καρβονίτη, ενώ οι επαναστάτες ετοιμάζουν το αποφασιστικό χτύπημα στο νέο Άστρο του Θανάτου, με απρόσμενη βοήθεια από τους κατοίκους των δασών του Έντορ. Η ταινία έκλεισε την αρχική τριλογία.","fact":"Οι χνουδωτοί κάτοικοι των δασών του Έντορ, οι Εβόκ, επινοήθηκαν για αυτή την ταινία και μένουν από τα πιο αναγνωρίσιμα πλάσματα της σάγκα.","wiki_en":"Return of the Jedi"},{"name":"Ο Πόλεμος των Άστρων: Επεισόδιο I – Η Αόρατη Απειλή","emoji":"🤖","meta":["διαστημική όπερα","1999","Τζορτζ Λούκας"],"description":"Δύο ιππότες Τζεντάι στέλνονται να προστατέψουν τη βασίλισσα του Ναμπού από έναν εμπορικό αποκλεισμό και βρίσκουν στον ερημικό Τατουίν ένα σκλαβάκι, τον Άνακιν Σκαϊγουόκερ, με ασυνήθιστα ισχυρή σχέση με τη Δύναμη. Η πρώτη προεισαγωγή δείχνει πώς ξεκίνησε ο Νταρθ Βέιντερ.","fact":"Ο Τζαρ Τζαρ Μπινκς ήταν ένας από τους πρώτους εντελώς ψηφιακούς χαρακτήρες με μεγάλο ρόλο δίπλα σε ζωντανούς ηθοποιούς.","wiki_en":"Star Wars: Episode I – The Phantom Menace"},{"name":"Star Wars: Η Δύναμη Ξυπνάει","emoji":"⚡","meta":["διαστημική όπερα","2015","Τζέι Τζέι Έιμπραμς"],"description":"Δεκαετίες μετά την πτώση της Αυτοκρατορίας, μια νέα απειλή, το Πρώτο Τάγμα, απλώνεται στον γαλαξία, και η συλλέκτρια παλιοσίδερων Ρέι με τον πρώην στρατιώτη Φιν μπλέκουν σε μια σύγκρουση που συνεχίζει την αρχική τριλογία. Η ταινία άνοιξε νέα εποχή για τη σειρά.","fact":"Οι δημιουργοί στηρίχτηκαν επίτηδες σε αληθινά σκηνικά και πραγματικά ρομπότ, αντί να περάσουν εντελώς στα ψηφιακά γραφικά.","wiki_en":"Star Wars: The Force Awakens"},{"name":"Rogue One: A Star Wars Story","emoji":"🛰️","meta":["διαστημική όπερα","2016","Γκάρεθ Έντουαρντς"],"description":"Μια ομάδα ανιχνευτών των επαναστατών με αρχηγό την Τζιν Έρσο στέλνεται σε μια απελπισμένη αποστολή, να κλέψει τα σχέδια του Άστρου του Θανάτου, λίγο πριν από τα γεγονότα της ταινίας του 1977. Μιλά για το τίμημα που πληρώνουν οι ανώνυμοι για μια κοινή νίκη.","fact":"Αρκετοί χαρακτήρες της κλασικής τριλογίας αναπλάστηκαν με ψηφιακά γραφικά, ώστε να εμφανιστούν ξανά νέοι.","wiki_en":"Rogue One"},{"name":"Star Trek","emoji":"🖖","meta":["επιστημονική φαντασία","2009","Τζέι Τζέι Έιμπραμς"],"description":"Το ξεκίνημα από την αρχή της θρυλικής σειράς παρακολουθεί τον νέο Τζέιμς Κερκ και τον κύριο Σποκ, που συναντιούνται στο διαστημόπλοιο Enterprise και μαθαίνουν να συνεργάζονται απέναντι σε έναν εκδικητικό εξωγήινο από το μέλλον. Παρουσίασε το Star Trek σε νέα γενιά.","fact":"Η υπόθεση χρησιμοποιεί μια εναλλακτική γραμμή χρόνου, που άφησε τους δημιουργούς να ξαναδούν τους κλασικούς ήρωες χωρίς να χαλάσουν τον κανόνα.","wiki_en":"Star Trek (film)","wiki_ru":"Звёздный путь"},{"name":"Aliens","emoji":"👽","meta":["επιστημονική φαντασία","1986","Τζέιμς Κάμερον"],"description":"Δεκαετίες μετά τη συνάντησή της με το εξωγήινο θηρίο, η ανθυπασπίστρια Έλεν Ρίπλεϊ πηγαίνει με ένα απόσπασμα διαστημικών πεζοναυτών σε έναν αποικισμένο πλανήτη, όπου χάθηκε η επαφή με τους εποίκους, και βρίσκει ένα ολόκληρο σμήνος. Η συνέχεια άλλαξε τον τρόμο σε πολεμική δράση.","fact":"Η Σιγκούρνεϊ Γουίβερ πήρε υποψηφιότητα Όσκαρ πρώτου γυναικείου ρόλου ως Ρίπλεϊ, κάτι σπανιότατο για ταινία δράσης και φαντασίας.","wiki_en":"Aliens (film)"},{"name":"Ο Εξολοθρευτής","emoji":"🤖","meta":["επιστημονική φαντασία","1984","Τζέιμς Κάμερον"],"description":"Από το μέλλον στέλνεται στο Λος Άντζελες ένα κυβόργιο-δολοφόνος, προγραμματισμένο να εξοντώσει μια γυναίκα με το όνομα Σάρα Κόνορ, και πίσω του φτάνει ένας στρατιώτης για να την προστατέψει. Η μικρού προϋπολογισμού ταινία έκανε τον Σβαρτσενέγκερ παγκόσμιο αστέρι.","fact":"Το «I'll be back» του εξολοθρευτή ήταν στο σενάριο μια κοινή, υπηρεσιακή φράση, και έγινε μια από τις διασημότερες ατάκες του σινεμά.","wiki_en":"The Terminator"},{"name":"Εξολοθρευτής 3: Η Εξέγερση των Μηχανών","emoji":"🤖","meta":["επιστημονική φαντασία","2003","Τζόναθαν Μόστοου"],"description":"Χρόνια αφότου αποτράπηκε η μέρα της κρίσης, ο μεγαλωμένος Τζον Κόνορ γίνεται ξανά στόχος ενός νεότερου, πιο εξελιγμένου εξολοθρευτή, και για την προστασία του φτάνει άλλο ένα μοντέλο. Η τρίτη ταινία συνέχισε την ιστορία χωρίς τον σκηνοθέτη που ξεκίνησε τη σειρά.","fact":"Ο βασικός αντίπαλος εδώ είναι η T-X, το πρώτο γυναικείο μοντέλο εξολοθρευτή στη σειρά.","wiki_en":"Terminator 3: Rise of the Machines"},{"name":"The Matrix Reloaded","emoji":"💊","meta":["επιστημονική φαντασία","2003","Οι Γουατσόφσκι"],"description":"Ο Νίο και οι σύμμαχοί του από τη Ζιόν συνεχίζουν τον αγώνα κατά των μηχανών που κρατούν την ανθρωπότητα σε μια εικονική πραγματικότητα, και μαθαίνουν νέα πράγματα για τη φύση της Μήτρας και τη θέση τους σε αυτή. Η δεύτερη ταινία μεγάλωσε φιλοσοφία και δράση.","fact":"Η μάχη του Νίο με δεκάδες αντίγραφα του πράκτορα Σμιθ απαίτησε τεχνολογία ψηφιακής κλωνοποίησης του ηθοποιού σε εκατοντάδες λήψεις.","wiki_en":"The Matrix Reloaded"},{"name":"The Matrix Revolutions","emoji":"🕶️","meta":["επιστημονική φαντασία","2003","Οι Γουατσόφσκι"],"description":"Το τελευταίο μέρος της τριλογίας φέρνει τον πόλεμο ανθρώπων και μηχανών στο κρίσιμο σημείο, με τη μοίρα της Ζιόν και της ίδιας της Μήτρας να κρέμεται από τις τελευταίες κινήσεις του Νίο στους δύο κόσμους. Βγήκε μόλις λίγους μήνες μετά την προηγούμενη ταινία.","fact":"Η κυκλοφορία στήθηκε ως παγκόσμιο γεγονός: η ταινία άνοιξε σε όλο τον κόσμο σχεδόν την ίδια ώρα, σε κάθε ζώνη ώρας.","wiki_en":"The Matrix Revolutions"},{"name":"Επιστροφή στο Μέλλον II","emoji":"🛹","meta":["επιστημονική φαντασία","1989","Ρόμπερτ Ζεμέκις"],"description":"Ο Μάρτι ΜακΦλάι και ο δόκτορ Έμετ Μπράουν πετούν με τη μηχανή του χρόνου στο 2015, για να αποτρέψουν μια καταστροφή στο μέλλον της οικογένειάς του, αλλά μια τυχαία παρέμβαση στραβώνει και το παρελθόν και το παρόν. Η συνέχεια έμεινε για τις προβλέψεις της.","fact":"Το ιπτάμενο σανίδι της ταινίας, το χόβερμπορντ, έγινε από τότε στόχος μηχανικών και ερασιτεχνών που πάλεψαν να το φτιάξουν αληθινό.","wiki_en":"Back to the Future Part II"},{"name":"Επιστροφή στο Μέλλον III","emoji":"🤠","meta":["επιστημονική φαντασία","1990","Ρόμπερτ Ζεμέκις"],"description":"Ο Μάρτι ΜακΦλάι πηγαίνει με τη μηχανή του χρόνου στο 1885, στην Άγρια Δύση, να σώσει τον δόκτορα Μπράουν, που έχει κολλήσει εκεί και έχει ερωτευτεί τη δασκάλα του χωριού. Το τελευταίο μέρος άλλαξε το μέλλον με το γουέστερν, κρατώντας το χιούμορ της σειράς.","fact":"Η δεύτερη και η τρίτη ταινία γυρίστηκαν σε ένα ενιαίο μπλοκ παραγωγής και βγήκαν στις αίθουσες με διαφορά περίπου έξι μηνών.","wiki_en":"Back to the Future Part III"},{"name":"Ιντιάνα Τζόουνς και ο Ναός της Καταδίκης","emoji":"💎","meta":["περιπέτεια","1984","Στίβεν Σπίλμπεργκ"],"description":"Ο τυχοδιώκτης αρχαιολόγος Ιντιάνα Τζόουνς καταλήγει σε ένα ινδικό χωριό, όπου μια τοπική λατρεία αρπάζει παιδιά και μια ιερή πέτρα, και πρέπει να κατεβεί σε ένα υπόγειο ναό γεμάτο θανατερές παγίδες. Η προεισαγωγή είναι πιο σκοτεινή και σκληρή από τις άλλες ταινίες.","fact":"Εν μέρει εξαιτίας των σκληρών σκηνών της, το αμερικανικό σύστημα σήμανσης πρόσθεσε αργότερα την ενδιάμεση κατηγορία PG-13.","wiki_en":"Indiana Jones and the Temple of Doom"},{"name":"Ιντιάνα Τζόουνς και η Τελευταία Σταυροφορία","emoji":"🏺","meta":["περιπέτεια","1989","Στίβεν Σπίλμπεργκ"],"description":"Ο Ιντιάνα Τζόουνς ξεκινά να βρει τον χαμένο πατέρα του και το θρυλικό Άγιο Δισκοπότηρο, κυνηγώντας το μαζί με ναζί πράκτορες που θέλουν το ίδιο κειμήλιο. Εδώ έρχεται για πρώτη φορά μαζί του ο πατέρας του, ο καθηγητής Χένρι Τζόουνς, με τον Σον Κόνερι.","fact":"Ο Σον Κόνερι, στον ρόλο του πατέρα του Ιντιάνα, ήταν στην πραγματικότητα μόλις δώδεκα χρόνια μεγαλύτερος από τον Χάρισον Φορντ.","wiki_en":"Indiana Jones and the Last Crusade"},{"name":"Οι Πειρατές της Καραϊβικής: Το Σεντούκι του Νεκρού","emoji":"🐙","meta":["περιπέτεια","2006","Γκορ Βερμπίνσκι"],"description":"Ο καπετάνιος Τζακ Σπάροου προσπαθεί να ξεπληρώσει το χρέος του στον Ντέιβι Τζόουνς, καπετάνιο του Ιπτάμενου Ολλανδού, ενώ ο Γουίλ Τέρνερ και η Ελίζαμπεθ Σουόν μπλέκουν σε ένα επικίνδυνο κυνήγι για το σεντούκι με την καρδιά του άρχοντα των θαλασσών.","fact":"Για το πρόσωπο του Ντέιβι Τζόουνς με τα πλοκάμια, ο Μπιλ Νάι χρειάστηκε να παίξει με στολή σύλληψης κίνησης.","wiki_en":"Pirates of the Caribbean: Dead Man's Chest"},{"name":"Οι Πειρατές της Καραϊβικής: Στην Άκρη του Κόσμου","emoji":"🏴‍☠️","meta":["περιπέτεια","2007","Γκορ Βερμπίνσκι"],"description":"Καπετάνιοι πειρατές από όλες τις θάλασσες μαζεύονται σε Συμβούλιο των Αδελφών για να αντιμετωπίσουν την Εταιρεία Ανατολικών Ινδιών, που θέλει να ξεριζώσει την πειρατεία, ενώ οι φίλοι του Τζακ Σπάροου πρέπει να τον φέρουν πίσω από τον κόσμο των νεκρών.","fact":"Για τη μεγάλη τελική μάχη στη δίνη χτίστηκαν γιγάντια σκηνικά πάνω σε μια πλατφόρμα-γυροσκόπιο που περιστρεφόταν.","wiki_en":"Pirates of the Caribbean: At World's End"},{"name":"The Fast and the Furious","emoji":"🏎️","meta":["ταινία δράσης","2001","Ρομπ Κοέν"],"description":"Ένας μυστικός αστυνομικός μπαίνει στην πιάτσα των αγώνων δρόμου του Λος Άντζελες για να ερευνήσει μια σειρά ληστειών σε φορτηγά, αλλά δένεται σιγά σιγά με τον αρχηγό της παρέας και την αδελφή του. Η πρώτη ταινία ξεκίνησε μια από τις πιο μακρόβιες σειρές του σινεμά.","fact":"Ο προϋπολογισμός της πρώτης ταινίας ήταν μικρός, αλλά η λατρεία των αγώνων δρόμου που γέννησε ανέβασε τη σειρά στις μεγάλες παραγωγές.","wiki_en":"The Fast and the Furious","wiki_ru":"Форсаж"},{"name":"Furious 7","emoji":"🚗","meta":["ταινία δράσης","2015","Τζέιμς Ουάν"],"description":"Η παρέα των οδηγών και πρώην κακοποιών τα βάζει με έναν πληρωμένο δολοφόνο που εκδικείται για τον αδελφό του, και η δράση περνά από τους αμερικανικούς αυτοκινητόδρομους στους δρόμους του Άμπου Ντάμπι και στα βουνά του Καυκάσου. Από τις εμπορικότερες της σειράς.","fact":"Τα γυρίσματα διακόπηκαν όταν σκοτώθηκε σε τροχαίο ο Πολ Γουόκερ: το σενάριο ξαναγράφτηκε και οι σκηνές του τελείωσαν με τα αδέλφια του και ψηφιακά.","wiki_en":"Furious 7"},{"name":"Mission: Impossible II","emoji":"🕶️","meta":["ταινία δράσης","2000","Τζον Γούο"],"description":"Ο πράκτορας Ίθαν Χαντ πηγαίνει στο Σίδνεϊ για να σταματήσει έναν παλιό συνεργάτη που έκλεψε ένα θανατηφόρο ιό και σχεδιάζει να τον πουλήσει μαζί με το εμβόλιο, βγάζοντας κέρδος από μια τεχνητή επιδημία. Ξεχωρίζει για τη σχεδόν χορευτική δράση του Τζον Γούο.","fact":"Πολλά από τα ριψοκίνδυνα πλάνα, μαζί και η αναρρίχηση στην αρχή της ταινίας, τα έκανε ο Τομ Κρουζ μόνος, χωρίς σωσία.","wiki_en":"Mission: Impossible II"},{"name":"Mission: Impossible – Ghost Protocol","emoji":"🏙️","meta":["ταινία δράσης","2011","Μπραντ Μπερντ"],"description":"Μετά από μια έκρηξη στο Κρεμλίνο, για την οποία κατηγορούνται πράκτορες της IMF, η υπηρεσία διαλύεται, και ο Ίθαν Χαντ με μια μικρή ομάδα πρέπει να δράσει μόνος, χωρίς κρατική στήριξη, για να αποτρέψει πυρηνική απειλή. Η ταινία έμεινε για την αναρρίχηση στον ουρανοξύστη.","fact":"Ο Τομ Κρουζ γύρισε τη σκηνή στο Μπουρτζ Χαλίφα σε αληθινό ύψος πάνω από τετρακόσια μέτρα, με ελάχιστη ψηφιακή επεξεργασία.","wiki_en":"Mission: Impossible – Ghost Protocol"},{"name":"Goldfinger","emoji":"🔫","meta":["ταινία δράσης","1964","Γκάι Χάμιλτον"],"description":"Ο πράκτορας 007 Τζέιμς Μποντ ερευνά τον μεγιστάνα του χρυσού Γκόλντφινγκερ, που σχεδιάζει να μολύνει με ραδιενέργεια το αποθεματικό χρυσού στο Φορτ Νοξ και να ρίξει την παγκόσμια οικονομία. Η τρίτη ταινία Μποντ όρισε τη συνταγή της σειράς.","fact":"Εδώ εμφανίστηκε για πρώτη φορά το περίφημο Aston Martin DB5 του Μποντ, που έγινε ένα από τα σύμβολα της σειράς.","wiki_en":"Goldfinger (film)"},{"name":"No Time to Die","emoji":"🎯","meta":["ταινία δράσης","2021","Κάρι Τζότζι Φουκουνάγκα"],"description":"Αποσυρμένος από την υπηρεσία, ο Τζέιμς Μποντ απολαμβάνει μια ήσυχη ζωή στη Τζαμάικα, ώσπου ένας παλιός φίλος από τη CIA του ζητά βοήθεια για να βρει έναν απαχθέντα επιστήμονα, που το πρόγραμμά του κρύβει θανατηφόρο όπλο. Η πέμπτη και τελευταία ταινία με τον Ντάνιελ Κρεγκ.","fact":"Με διάρκεια περίπου 163 λεπτών, είναι η πιο μακροσκελής ταινία της επίσημης σειράς Μποντ.","wiki_en":"No Time to Die"},{"name":"Skyfall","emoji":"🏴","meta":["ταινία δράσης","2012","Σαμ Μέντες"],"description":"Μετά από μια αποτυχημένη επιχείρηση και ένα τραύμα, ο Τζέιμς Μποντ γυρίζει στην υπηρεσία για να εντοπίσει έναν πρώην πράκτορα της MI6 που έγινε κυβερνοτρομοκράτης και απειλεί προσωπικά την Μ και όλη τη βρετανική υπηρεσία. Βγήκε για τα πενήντα χρόνια της σειράς και πήρε δύο Όσκαρ.","fact":"Το τραγούδι της Adele ήταν το πρώτο από ταινία Μποντ που πήρε Όσκαρ· τα προηγούμενα έφταναν μόνο ως την υποψηφιότητα.","wiki_en":"Skyfall"},{"name":"Die Another Day","emoji":"❄️","meta":["ταινία δράσης","2002","Λι Ταμαχόρι"],"description":"Μετά από μακρά αιχμαλωσία στη Βόρεια Κορέα, ο Τζέιμς Μποντ γυρίζει στην υπηρεσία και ερευνά τη σχέση ενός μυστηριώδους μεγιστάνα με το εμπόριο διαμαντιών και με ένα επικίνδυνο δορυφορικό όπλο. Βγήκε για τα σαράντα χρόνια της σειράς και ήταν η τελευταία του Πιρς Μπρόσναν.","fact":"Εδώ ο Μποντ παίρνει ένα αυτοκίνητο με προσαρμοστική κάλυψη που το κάνει αόρατο — από τα πιο απίθανα γκάτζετ όλης της σειράς.","wiki_en":"Die Another Day"},{"name":"John Wick: Chapter 2","emoji":"🐺","meta":["ταινία δράσης","2017","Τσαντ Σταχέλσκι"],"description":"Ο αποσυρμένος πληρωμένος δολοφόνος Τζον Γουίκ αναγκάζεται να γυρίσει στον κόσμο των συμβολαίων από ένα παλιό χρέος τιμής σε έναν Ιταλό αρχιμαφιόζο, και οι άγραφοι νόμοι αυτού του κόσμου βάζουν στο τραπέζι την ίδια τη ζωή του. Η συνέχεια μεγάλωσε πολύ αυτό το σύμπαν.","fact":"Ο Κιάνου Ριβς δούλεψε μόνος πολλές από τις δύσκολες σκηνές μάχης, με μήνες εντατικής προπόνησης πριν από τα γυρίσματα.","wiki_en":"John Wick: Chapter 2"},{"name":"John Wick: Chapter 3 – Parabellum","emoji":"🐴","meta":["ταινία δράσης","2019","Τσαντ Σταχέλσκι"],"description":"Κηρυγμένος παράνομος επειδή παρέβη τους ιερούς κανόνες του κόσμου των δολοφόνων, ο Τζον Γουίκ τρέχει για τη ζωή του στους δρόμους της Νέας Υόρκης ψάχνοντας συμμάχους, με τεράστια αμοιβή στο κεφάλι του. Η τρίτη ταινία μπαίνει πιο βαθιά σε αυτή τη μυστική διεθνή οργάνωση.","fact":"Σε μια σκηνή ο Τζον Γουίκ πολεμά τους διώκτες του χρησιμοποιώντας ως όπλα βιβλία βιβλιοθήκης — σπάνιο δείγμα αυτοσχέδιας μάχης.","wiki_en":"John Wick: Chapter 3 – Parabellum"},{"name":"Η Μικρή Γοργόνα","emoji":"🧜‍♀️","meta":["κινούμενα σχέδια","1989","Ρον Κλέμεντς, Τζον Μάσκερ"],"description":"Η μικρή γοργόνα Άριελ ονειρεύεται να ζήσει με τους ανθρώπους και, ερωτευμένη με έναν πρίγκιπα, κάνει μια επικίνδυνη συμφωνία με τη θαλάσσια μάγισσα Ούρσουλα, δίνοντας τη φωνή της για ένα ζευγάρι πόδια. Η εκδοχή της Disney άνοιξε την αναγέννηση του στούντιο.","fact":"Το τραγούδι Under the Sea πήρε Όσκαρ και έγινε μια από τις πιο αναγνωρίσιμες μελωδίες της Disney.","wiki_en":"The Little Mermaid (1989 film)"},{"name":"Η Πεντάμορφη και το Τέρας","emoji":"🌹","meta":["κινούμενα σχέδια","1991","Γκάρι Τράουσντεϊλ, Κερκ Ουάιζ"],"description":"Η φιλομαθής Μπελ δέχεται να μείνει αιχμάλωτη στο κάστρο ενός μαγεμένου πρίγκιπα που έγινε τέρας, για να ελευθερώσει τον πατέρα της, και πίσω από την τραχιά όψη του οικοδεσπότη ανακαλύπτει σιγά σιγά μια καλή ψυχή. Η πρώτη ταινία κινουμένων σχεδίων με υποψηφιότητα καλύτερης ταινίας.","fact":"Το βαλς στην αίθουσα χορού φτιάχτηκε με τρισδιάστατο ψηφιακό φόντο — τότε, για τα σχέδια με το χέρι, ήταν πραγματικό άλμα.","wiki_en":"Beauty and the Beast (1991 film)"},{"name":"Αλαντίν","emoji":"🧞","meta":["κινούμενα σχέδια","1992","Ρον Κλέμεντς, Τζον Μάσκερ"],"description":"Ο μικροκλέφτης του δρόμου Αλαντίν βρίσκει ένα μαγικό λυχνάρι με ένα τζίνι που εκπληρώνει τρεις ευχές, και τις ξοδεύει για να κερδίσει την καρδιά της πριγκίπισσας Γιασμίν, κάνοντας τον πρίγκιπα. Η ταινία από τις «Χίλιες και Μία Νύχτες» έμεινε για το χρώμα και το τζίνι της.","fact":"Το τζίνι το έντυσε φωνητικά ο κωμικός Ρόμπιν Γουίλιαμς, που αυτοσχεδίασε μεγάλο μέρος των ατακών του στο στούντιο.","wiki_en":"Aladdin (1992 Disney film)"},{"name":"Ποκαχόντας","emoji":"🍃","meta":["κινούμενα σχέδια","1995","Μάικ Γκάμπριελ, Έρικ Γκόλντμπεργκ"],"description":"Η Ποκαχόντας, κόρη αρχηγού ινδιάνικης φυλής, συναντά τον Άγγλο άποικο λοχαγό Τζον Σμιθ και προσπαθεί να αποτρέψει τη σύγκρουση ανάμεσα στους δικούς της και στους νεοφερμένους. Η ταινία της Disney στηρίζεται στη μυθοποιημένη ιστορία ενός υπαρκτού προσώπου του 17ου αιώνα.","fact":"Ήταν η πρώτη ταινία μεγάλου μήκους της Disney με ηρωίδα βασισμένη σε αληθινό ιστορικό πρόσωπο.","wiki_en":"Pocahontas (1995 film)"},{"name":"Μουλάν","emoji":"⚔️","meta":["κινούμενα σχέδια","1998","Τόνι Μπάνκροφτ, Μπάρι Κουκ"],"description":"Η Μουλάν ντύνεται άντρας και παίρνει τη θέση του άρρωστου πατέρα της στον αυτοκρατορικό στρατό της Κίνας, για να υπερασπιστεί τη χώρα από την εισβολή των Ούννων. Η ταινία της Disney στηρίζεται σε αρχαίο κινέζικο μύθο και έδωσε μια από τις πρώτες γυναίκες πολεμιστές του στούντιο.","fact":"Ο μύθος της Χούα Μουλάν είναι γνωστός στην Κίνα από την «Μπαλάντα της Μουλάν», που γράφτηκε πριν από περίπου δεκαπέντε αιώνες.","wiki_en":"Mulan (1998 film)"},{"name":"Monsters, Inc.","emoji":"👹","meta":["κινούμενα σχέδια","2001","Πιτ Ντόκτερ"],"description":"Σε ένα εργοστάσιο όπου τα τέρατα τρομάζουν παιδιά για να βγάλουν ενέργεια από τις κραυγές τους, ο καλόκαρδος γίγαντας Σάλι και ο μονόφθαλμος συνεργάτης του Μάικ αφήνουν κατά λάθος ένα κοριτσάκι στον κόσμο τους, σπάζοντας κάθε κανόνα. Η Pixar γυρίζει τους παιδικούς φόβους ανάποδα.","fact":"Για να κινηθεί ρεαλιστικά η γούνα του Σάλι χρειάστηκε ειδική τεχνολογία προσομοίωσης τριχώματος, που μετά χρησιμοποιήθηκε και αλλού.","wiki_en":"Monsters, Inc."},{"name":"Οι Απίθανοι","emoji":"🦸‍♀️","meta":["κινούμενα σχέδια","2004","Μπραντ Μπερντ"],"description":"Μια οικογένεια πρώην υπερηρώων, που αναγκάστηκε να κρύψει τις δυνάμεις της και να ζήσει κανονικά αφότου απαγορεύτηκε η ηρωική δράση, ξαναπιάνει δουλειά όταν ένας πανούργος κακός κινείται εναντίον τους. Από τις πρώτες ταινίες κινουμένων σχεδίων που πήραν σοβαρά τους υπερήρωες.","fact":"Ήταν η πρώτη ταινία μεγάλου μήκους της Pixar με κυρίως ανθρώπινους χαρακτήρες, αντί για παιχνίδια, έντομα ή ζώα.","wiki_en":"The Incredibles"},{"name":"Αυτοκίνητα","emoji":"🏎️","meta":["κινούμενα σχέδια","2006","Τζον Λάσετερ"],"description":"Το αλαζονικό αγωνιστικό αυτοκίνητο Κεραυνός ΜακΚουίν, στον δρόμο του για ένα σημαντικό πρωτάθλημα, κολλάει σε μια μικρή πόλη πάνω στον θρυλικό δρόμο Route 66 και μαθαίνει σιγά σιγά να εκτιμά τη φιλία πάνω από τη δόξα. Η ταινία ζει σε έναν κόσμο από ζωντανά αυτοκίνητα.","fact":"Οι σχεδιαστές έκαναν αληθινά οδικά ταξίδια στον ιστορικό δρόμο Route 66, για να πιάσουν την ατμόσφαιρα των μικρών αμερικανικών πόλεων.","wiki_en":"Cars (film)"},{"name":"Ρατατούι","emoji":"🐀","meta":["κινούμενα σχέδια","2007","Μπραντ Μπερντ"],"description":"Ο Ρεμί, ένας ποντικός με εκλεπτυσμένη μύτη και όνειρο να γίνει σεφ, βοηθά κρυφά έναν άχρηστο βοηθό μαγείρου να φτιάχνει πιάτα υψηλής γαστρονομίας σε μεγάλο παρισινό εστιατόριο, οδηγώντας τον από κάτω από τον σκούφο του. Μια τρυφερή ιστορία για το δικαίωμα στο όνειρο.","fact":"Οι σχεδιαστές του στούντιο πέρασαν από επαγγελματικές κουζίνες, ώστε το μαγείρεμα να φαίνεται αληθινό.","wiki_en":"Ratatouille (film)"},{"name":"Τα Μυστικά του Μυαλού","emoji":"🧠","meta":["κινούμενα σχέδια","2015","Πιτ Ντόκτερ"],"description":"Μέσα στο κεφάλι ενός κοριτσιού, της Ράιλι, ζουν τα συναισθήματά της σε πρόσωπα — η Χαρά, η Λύπη, ο Θυμός, ο Φόβος και η Αποστροφή — και παλεύουν με τη μετακόμιση της οικογένειας και με το μεγάλωμα της κυρίας τους. Η Pixar δίνει σχήμα στη μνήμη και στην ψυχή.","fact":"Οι δημιουργοί συμβουλεύτηκαν ψυχολόγους και νευροεπιστήμονες, για να δώσουν στα συναισθήματα και στη μνήμη πειστική μορφή.","wiki_en":"Inside Out (2015 film)"},{"name":"Ζωούπολη","emoji":"🦊","meta":["κινούμενα σχέδια","2016","Μπάιρον Χάουαρντ, Ριτς Μουρ"],"description":"Η αποφασισμένη κουνέλα Τζούντι Χοπς γίνεται το πρώτο κουνέλι στην αστυνομία μιας μεγαλούπολης όπου ζουν μόνο ζώα, και πρέπει να συνεργαστεί με μια πονηρή αλεπού απατεώνα για να λύσει μια παράξενη υπόθεση εξαφανίσεων. Η ταινία μιλά για προκαταλήψεις και στερεότυπα.","fact":"Οι σχεδιαστές έδωσαν σε κάθε συνοικία της Ζωούπολης δική της αρχιτεκτονική, στα μέτρα ζώων από ποντίκια μέχρι ελέφαντες.","wiki_en":"Zootopia"},{"name":"Μοάνα","emoji":"🌊","meta":["κινούμενα σχέδια","2016","Ρον Κλέμεντς, Τζον Μάσκερ"],"description":"Η Μοάνα, κόρη του αρχηγού ενός πολυνησιακού νησιού, ξεκινά ένα επικίνδυνο ταξίδι στον ωκεανό μαζί με τον ημίθεο Μάουι, για να επιστρέψει την καρδιά μιας θεάς της φύσης που εκείνος έκλεψε και να σώσει τον λαό της. Η Disney στηρίχτηκε στους μύθους του Ειρηνικού.","fact":"Οι δημιουργοί συμβουλεύτηκαν για χρόνια ιστορικούς, ανθρωπολόγους και θαλασσοπόρους της Ωκεανίας, για να αποδώσουν σωστά τον πολιτισμό τους.","wiki_en":"Moana (2016 film)"},{"name":"Μαλλιά Κουβάρια","emoji":"👱‍♀️","meta":["κινούμενα σχέδια","2010","Νέιθαν Γκρένο, Μπάιρον Χάουαρντ"],"description":"Μια κοπέλα με μαγικά μαλλιά απίστευτου μήκους, κλεισμένη χρόνια από μια μάγισσα σε ψηλό πύργο, βγαίνει για πρώτη φορά από την κρυψώνα της με τη βοήθεια ενός γοητευτικού κλέφτη, για να δει τα φώτα που κάθε χρόνο κοιτάζει από το παράθυρο. Από τους αδελφούς Γκριμ.","fact":"Η κίνηση των μακριών μαλλιών της Ραπουνζέλ πήρε στους σχεδιαστές πολύ χρόνο και χρειάστηκε δική της τεχνολογία προσομοίωσης.","wiki_en":"Tangled"},{"name":"Wreck-It Ralph","emoji":"🕹️","meta":["κινούμενα σχέδια","2012","Ριτς Μουρ"],"description":"Ο Ραλφ, ο κακός ενός παλιού βιντεοπαιχνιδιού, κουράζεται να είναι ο κακός και ταξιδεύει μέσα στα άλλα παιχνίδια του αρκαδικού μηχανήματος ψάχνοντας ένα μετάλλιο που θα αποδείξει ότι μπορεί να είναι και καλός. Η ταινία παίζει έξυπνα με τα κλασικά βιντεοπαιχνίδια.","fact":"Στην ταινία εμφανίζονται περαστικοί γνωστοί χαρακτήρες από αληθινά βιντεοπαιχνίδια, όπως του Sonic the Hedgehog και του Pac-Man.","wiki_en":"Wreck-It Ralph"},{"name":"Πώς να Εκπαιδεύσετε τον Δράκο σας","emoji":"🐉","meta":["κινούμενα σχέδια","2010","Ντιν ΝτεΜπλουά, Κρις Σάντερς"],"description":"Ο Χίκαπ, ένας νέος Βίκινγκ σε ένα χωριό κυνηγών δράκων, αντί να σκοτώσει έναν πληγωμένο μαύρο δράκο τον εξημερώνει κρυφά και ανακαλύπτει ότι οι δράκοι δεν είναι τα τέρατα που πιστεύουν οι δικοί του. Μια από τις πιο ζεστές ιστορίες φιλίας της DreamWorks.","fact":"Φτιάχνοντας τον μαύρο δράκο, οι σχεδιαστές δανείστηκαν συνήθειες γατών και άλλων αληθινών ζώων, για να μοιάζει ζωντανός.","wiki_en":"How to Train Your Dragon (film)","wiki_ru":"Как приручить дракона"},{"name":"Μαδαγασκάρη","emoji":"🦒","meta":["κινούμενα σχέδια","2005","Έρικ Ντάρνελ, Τομ ΜακΓκραθ"],"description":"Τέσσερα ζώα από ζωολογικό κήπο της Νέας Υόρκης — ένα λιοντάρι, μια ζέβρα, μια καμηλοπάρδαλη και μια ιπποπόταμος — καταλήγουν στο άγριο νησί της Μαδαγασκάρης και μαθαίνουν να ζουν χωρίς τις ανέσεις του κλουβιού. Η ταινία έμεινε για τους χαρακτήρες της.","fact":"Κάποιοι χαρακτήρες, ιδίως οι ακούραστοι πιγκουίνοι, άρεσαν τόσο που αργότερα απέκτησαν δικές τους σειρές και ταινίες.","wiki_en":"Madagascar (2005 film)"},{"name":"Kung Fu Panda","emoji":"🐼","meta":["κινούμενα σχέδια","2008","Μαρκ Όσμπορν, Τζον Στίβενσον"],"description":"Ο Πο, ένα αδέξιο και τεμπέλικο πάντα που δουλεύει στο μαγαζί με τα νουντλς του πατέρα του, επιλέγεται απρόσμενα ως ο θρυλικός Πολεμιστής Δράκος και πρέπει να μάθει πολεμικές τέχνες με έναν αυστηρό δάσκαλο, για να σώσει την κοιλάδα. Κομεντί με άρωμα κλασικού κουνγκ φου.","fact":"Οι δημιουργοί συμβουλεύτηκαν αληθινούς δασκάλους πολεμικών τεχνών, ώστε οι κινήσεις των ηρώων να είναι τεχνικά σωστές.","wiki_en":"Kung Fu Panda","wiki_ru":"Кунг-фу панда"},{"name":"Ο Εφιάλτης πριν από τα Χριστούγεννα","emoji":"🎃","meta":["κινούμενα σχέδια","1993","Χένρι Σέλικ"],"description":"Ο Τζακ Σκέλινγκτον, βασιλιάς του Χαλοουίν, κουρασμένος να τρομάζει κόσμο χρόνο με τον χρόνο, ανακαλύπτει μια μαγική πόρτα προς τον κόσμο των Χριστουγέννων και αποφασίζει να στήσει τη γιορτή με τον δικό του τρόπο. Παραγωγή του Τιμ Μπάρτον, έγινε καλτ κλασικό.","fact":"Όλη η ταινία είναι κουκλοταινία καρέ-καρέ, και για τις εκφράσεις του Τζακ Σκέλινγκτον φτιάχτηκαν αρκετές εκατοντάδες εναλλάξιμα κεφάλια.","wiki_en":"The Nightmare Before Christmas"},{"name":"Η Εποχή των Παγετώνων","emoji":"🐿️","meta":["κινούμενα σχέδια","2002","Κρις Γουέτζ"],"description":"Ένα μαμούθ, ένας βραδύποδας και μια σπαθόδοντη τίγρη της εποχής των πάγων, που στην αρχή δεν εμπιστεύονται ο ένας τον άλλον, ενώνουν δυνάμεις για να γυρίσουν ένα ανθρώπινο βρέφος στη φυλή του και γίνονται μια παράξενη αλλά γερή οικογένεια. Ξεκίνησε μια μακρόβια σειρά.","fact":"Ο δευτεραγωνιστής Σκρατ, ο σκίουρος που κυνηγά αιώνια ένα βελανίδι, δεν λέει λέξη και έγινε ένα από τα σύμβολα της σειράς.","wiki_en":"Ice Age (2002 film)"},{"name":"Εγώ, ο Απαισιότατος","emoji":"🍌","meta":["κινούμενα σχέδια","2010","Πιερ Κοφέν, Κρις Ρενό"],"description":"Ο Γκρου, ένας κακός που όλο αποτυχαίνει, σχεδιάζει να κλέψει το φεγγάρι και υιοθετεί τρία ορφανά κορίτσια για να τα χρησιμοποιήσει στο σχέδιό του, αλλά δένεται μαζί τους αληθινά. Η ταινία παρουσίασε τα μικροσκοπικά κίτρινα μίνιονς, που έγιναν φαινόμενο από μόνα τους.","fact":"Τα μίνιονς, σχεδιασμένα ως δευτεραγωνιστές, απέκτησαν αργότερα δικές τους ταινίες, που έβγαλαν ακόμη πιο πολλά από την αρχική.","wiki_en":"Despicable Me"},{"name":"Οι Τρεις από το Προστοκβάσινο","emoji":"🐱","meta":["κινούμενα σχέδια","1978","Βλαντίμιρ Ποπόφ"],"description":"Ένα αγόρι με το παρατσούκλι θείος Φιόντορ πάει να ζήσει σε ένα σπίτι στο χωριό Προστοκβάσινο μαζί με τον γάτο Ματρόσκιν που μιλάει και τον καλόκαρδο σκύλο Σάρικ, και οι τρεις τους νοικοκυρεύονται και μπλέκουν σε αστείες καθημερινές ιστορίες. Αγαπημένο σοβιετικό κλασικό.","fact":"Η ατάκα του γάτου Ματρόσκιν «για να πουλήσεις κάτι άχρηστο, πρέπει πρώτα να αγοράσεις κάτι άχρηστο» έγινε λαϊκή παροιμία.","wiki_en":"Three from Prostokvashino","wiki_ru":"Трое из Простоквашино"},{"name":"Γουίνι το Αρκουδάκι","emoji":"🍯","meta":["κινούμενα σχέδια","1969","Φιόντορ Χιτρούκ"],"description":"Η πρώτη από τις σοβιετικές ταινίες για το αρκουδάκι με το πριονίδι στο κεφάλι, που ξεκινά με τον φίλο του Γουρουνάκι για μέλι στις μέλισσες, κάνοντας το συννεφάκι. Η μεταφορά του Άλαν Μιλν από τον Φιόντορ Χιτρούκ έφτιαξε έναν Γουίνι πολύ διαφορετικό από της Disney.","fact":"Τη φωνή του Γουίνι έδωσε ο Γιεβγκένι Λεόνοφ, που η χροιά του έγινε αχώριστη από το αρκουδάκι για γενιές θεατών.","wiki_en":"Winnie-the-Pooh (1969 film)","wiki_ru":"Винни-Пух (мультфильм)"},{"name":"Ο Σκαντζόχοιρος στην Ομίχλη","emoji":"🦔","meta":["κινούμενα σχέδια","1975","Γιούρι Νορστέιν"],"description":"Ένας μικρός σκαντζόχοιρος ξεκινά να πάει στον φίλο του Αρκουδάκι για να μετρήσουν τα αστέρια, αλλά χάνει τον δρόμο μέσα σε πυκνή ομίχλη, όπου συναντά παράξενες και τρομακτικές μορφές. Η ταινία του Γιούρι Νορστέιν έχει ψηφιστεί από κριτικούς στις κορυφαίες όλων των εποχών.","fact":"Για να φτιάξουν την πυκνή ομίχλη, οι σχεδιαστές γύρισαν σε στρώσεις, με πολλά φύλλα ημιδιάφανου χαρτιού.","wiki_en":"Hedgehog in the Fog"},{"name":"Ήταν Κάποτε ένας Σκύλος","emoji":"🐺","meta":["κινούμενα σχέδια","1982","Εντουάρντ Ναζάροφ"],"description":"Ένας γερασμένος σκύλος, που τον έδιωξαν τα αφεντικά του, συναντά στο δάσος έναν λύκο ο οποίος, αντί να τον φάει, του προτείνει ένα απρόσμενο σχέδιο σωτηρίας, και αρχίζει μια παράξενη φιλία. Η μικρού μήκους ταινία έμεινε για το λιτό χιούμορ και τις ατάκες της.","fact":"Το «Τώρα θα σου τραγουδήσω» του λύκου έχει γίνει από καιρό αυτοτελές αστείο στην καθημερινή ρωσική γλώσσα.","wiki_en":"There Once Was a Dog"},{"name":"Οι Μουσικοί της Βρέμης","emoji":"🎸","meta":["κινούμενα σχέδια","1969","Ινέσα Κοβαλέφσκαγια"],"description":"Μια παρέα πλανόδιων ζώων-μουσικών με αρχηγό τον γοητευτικό Τροβαδούρο περιπλανιέται στους δρόμους ενός παραμυθένιου βασιλείου και βοηθά την Πριγκίπισσα να ξεφύγει από έναν δεσποτικό βασιλιά. Το σοβιετικό μιούζικαλ έμεινε για τα ροκ εν ρολ τραγούδια του.","fact":"Σχεδόν όλα τα τραγούδια τα είπε ένας άνθρωπος, ο Ολέγκ Ανόφριεφ, που έντυσε φωνητικά και τον Τροβαδούρο και τους πιο πολλούς ήρωες.","wiki_en":"The Bremen Town Musicians (1969 film)","wiki_ru":"Бременские музыканты (мультфильм)"},{"name":"Το Ιπτάμενο Καράβι","emoji":"⛵","meta":["κινούμενα σχέδια","1979","Γκάρι Μπαρντίν"],"description":"Ο Ιβάν, ένα φτωχό αλλά πολυμήχανο παλικάρι του χωριού, φτιάχνει με τη βοήθεια παραμυθένιων συμμάχων ένα μαγικό ιπτάμενο καράβι, για να κερδίσει την κόρη του τσάρου κόντρα στα σχέδια του καυχησιάρη Πολκάν. Από ρωσικό λαϊκό παραμύθι, έμεινε για τα τραγούδια του.","fact":"Το τραγούδι των Μπάμπα Γιάγκα από αυτή την ταινία ακούγεται ακόμη σε παιδικές γιορτές, ως αναγνωρίσιμο κωμικό νούμερο.","wiki_en":"The Flying Ship (1979 film)","wiki_ru":"Летучий корабль (мультфильм)"},{"name":"Η Βασίλισσα του Χιονιού","emoji":"❄️","meta":["κινούμενα σχέδια","1957","Λεβ Αταμάνοφ"],"description":"Η μικρή Γκέρντα ξεκινά ένα επικίνδυνο ταξίδι στις παγωμένες βόρειες χώρες, για να βρει και να σώσει τον φίλο της Κάι, που η δολερή Βασίλισσα του Χιονιού του πάγωσε την καρδιά. Η σοβιετική εκδοχή του Χανς Κρίστιαν Άντερσεν είναι κορυφή των σχεδίων με το χέρι.","fact":"Η ταινία εντυπωσίασε βαθιά τον Ιάπωνα σχεδιαστή Χαγιάο Μιγιαζάκι, που αργότερα την ανέφερε ως πηγή έμπνευσής του.","wiki_en":"The Snow Queen (1957 film)"},{"name":"Οι Δώδεκα Μήνες","emoji":"🔥","meta":["κινούμενα σχέδια","1956","Ιβάν Ιβάνοφ-Βάνο, Μιχαήλ Μπότοφ"],"description":"Μια ιδιότροπη μικρή βασίλισσα απαιτεί γάλανθους μέσα στον χειμώνα, και η προγονή της μητριάς στέλνεται στο παγωμένο δάσος, όπου βρίσκει όλους τους δώδεκα μήνες του χρόνου μαζεμένους γύρω από μια μαγική φωτιά. Από θεατρικό του Σαμουήλ Μαρσάκ, κλασικό της Πρωτοχρονιάς.","fact":"Κάθε ένας από τους δώδεκα μήνες πήρε στην ταινία δική του μορφή και δικό του χαρακτήρα, στο πνεύμα της εποχής του.","wiki_en":"The Twelve Months (1956 film)","wiki_ru":"Двенадцать месяцев (мультфильм)"},{"name":"Τσεμπουράσκα","emoji":"🐵","meta":["κινούμενα σχέδια","1971","Ρομάν Κατσάνοφ"],"description":"Ένα μυστηριώδες πλάσμα με μεγάλα αυτιά, άγνωστο στην επιστήμη, που βρέθηκε σε ένα κιβώτιο με πορτοκάλια, ψάχνει φίλους μαζί με τον κροκόδειλο Γκένα, βοηθά τους γύρω του και χαλάει τα σχέδια της κακιάς γριάς Σαπακλιάκ. Η κουκλοταινία έκανε τον Τσεμπουράσκα σύμβολο.","fact":"Ο Τσεμπουράσκα έπιασε τόσο πολύ που έγινε αργότερα επίσημη μασκότ της ρωσικής ομάδας σε αρκετούς Ολυμπιακούς Αγώνες.","wiki_en":"Cheburashka","wiki_ru":"Чебурашка (мультфильм)"},{"name":"Κιν-τζα-τζα!","emoji":"🛸","meta":["επιστημονική φαντασία","1986","Γκεόργκι Ντανέλια"],"description":"Ένας εργοδηγός και ένας φοιτητής που έτυχε να στέκεται δίπλα του μεταφέρονται, μέσω μιας παράξενης συσκευής εξωγήινου, στον ερημικό πλανήτη Πλιουκ ενός άλλου γαλαξία, όπου πρέπει να μάθουν παράλογους κοινωνικούς κανόνες. Μια σατιρική παραβολή για τις ανθρώπινες ιεραρχίες.","fact":"Η επινοημένη λέξη «κου», που στον Πλιουκ αντικαθιστά σχεδόν ό,τι θέλει να πει κανείς, έγινε παροιμιώδης στα ρωσικά.","wiki_en":"Kin-dza-dza!"},{"name":"Καρδιά Σκύλου","emoji":"🐕","meta":["τραγικωμωδία","1988","Βλαντίμιρ Μπόρτκο"],"description":"Ο καθηγητής Πρεομπραζένσκι μεταμοσχεύει σε ένα αδέσποτο σκυλί ανθρώπινη υπόφυση, και το σκυλί γίνεται σιγά σιγά ένας χυδαίος, αναιδής άνθρωπος με το όνομα Σαρίκοφ, που του φέρνει μόνο μπελάδες. Η μεταφορά του Μπουλγκάκοφ είναι από τις καλύτερες σοβιετικές τηλεταινίες.","fact":"Η ατάκα του καθηγητή «Η ερήμωση δεν είναι στα αποχωρητήρια, είναι στα κεφάλια» ζει εδώ και δεκαετίες μόνη της.","wiki_en":"Heart of a Dog (film)","wiki_ru":"Собачье сердце (фильм)"},{"name":"Στη Μάχη Πάνε Μόνο οι Παλιοί","emoji":"✈️","meta":["πολεμικό δράμα","1973","Λεονίντ Μπίκοφ"],"description":"Ένας έμπειρος πιλότος μαχητικού με το παρατσούκλι Μαέστρο φτιάχνει μια μοίρα από άβγαλτους νεοσύλλεκτους και την κάνει τη φημισμένη «μοίρα που τραγουδά», προσπαθώντας να κρατήσει τα παιδιά ανθρώπους μέσα στον πόλεμο. Από τις πιο αγαπημένες σοβιετικές ταινίες.","fact":"Ο Λεονίντ Μπίκοφ λάτρευε την αεροπορία και δεν ήταν μόνο σκηνοθέτης και πρωταγωνιστής, αλλά και συν-σεναριογράφος της ταινίας.","wiki_en":"Only Old Men Are Going into Battle","wiki_ru":"В бой идут одни «старики»"},{"name":"Αξιωματικοί","emoji":"🎖️","meta":["πολεμικό δράμα","1971","Βλαντίμιρ Ρογκοβόι"],"description":"Η ταινία παρακολουθεί δύο φίλους αξιωματικούς και τη γυναίκα που αγαπούν και οι δύο, σε αρκετές δεκαετίες σοβιετικής ιστορίας, από τον Εμφύλιο ως τον Β' Παγκόσμιο Πόλεμο, δείχνοντας πώς αντέχουν η τιμή και η φιλία. Έγινε το πρότυπο για τις γενιές της στολής.","fact":"Η φράση «υπάρχει κι ένα τέτοιο επάγγελμα: να υπερασπίζεσαι την πατρίδα» είναι από τις γνωστότερες του σοβιετικού σινεμά.","wiki_en":"Officers (1971 film)","wiki_ru":"Офицеры (фильм)"},{"name":"Οι Αυγές Εδώ Είναι Ήσυχες","emoji":"🌲","meta":["πολεμικό δράμα","1972","Στανισλάβ Ροστότσκι"],"description":"Ένας επιλοχίας ενός μικρού αντιαεροπορικού φυλακίου παίρνει ένα απόσπασμα νεαρών γυναικών πυροβολητών στα δάση της Καρελίας, να εντοπίσουν Γερμανούς σαμποτέρ, και η εύθραυστη ομάδα δίνει άνιση μάχη. Από τον Μπορίς Βασίλιεφ, μια σπαρακτική ταινία για τις γυναίκες στον πόλεμο.","fact":"Η ταινία αναγνωρίστηκε διεθνώς και πήρε υποψηφιότητα Όσκαρ ξενόγλωσσης ταινίας.","wiki_en":"The Dawns Here Are Quiet (1972 film)","wiki_ru":"А зори здесь тихие (фильм, 1972)"},{"name":"Η Μοίρα ενός Ανθρώπου","emoji":"🎖️","meta":["πολεμικό δράμα","1959","Σεργκέι Μπονταρτσούκ"],"description":"Ο παλιός μαχητής του μετώπου Αντρέι Σοκόλοφ διηγείται σε έναν τυχαίο συνοδοιπόρο τη ζωή του: την αιχμαλωσία, τον χαμό της οικογένειάς του και το νέο νόημα που βρήκε μετά τον πόλεμο. Το ντεμπούτο του Μπονταρτσούκ μίλησε από τα πρώτα ειλικρινά για τους αιχμαλώτους.","fact":"Ο Σεργκέι Μπονταρτσούκ σκηνοθέτησε και έπαιξε τον πρωταγωνιστή, φτιάχνοντας μια μορφή σύμβολο της λαϊκής αντοχής.","wiki_en":"Destiny of a Man","wiki_ru":"Судьба человека (фильм)"},{"name":"Όταν Περνούν οι Γερανοί","emoji":"🕊️","meta":["πολεμικό δράμα","1957","Μιχαήλ Καλατόζοφ"],"description":"Ένα νεαρό ζευγάρι χωρίζει όταν ο άντρας φεύγει εθελοντής στο μέτωπο, και η κοπέλα που μένει πίσω περνά βομβαρδισμούς, απώλειες και μια δύσκολη ηθική επιλογή. Η ταινία του Μιχαήλ Καλατόζοφ παραμένει η μόνη σοβιετική που πήρε τον Χρυσό Φοίνικα στις Κάννες.","fact":"Ο διευθυντής φωτογραφίας Σεργκέι Ουρουσέφσκι γύρισε σκηνές με τρόπους πολύ μπροστά από την εποχή, με μακρά αδιάκοπα κινούμενα πλάνα.","wiki_en":"The Cranes Are Flying"},{"name":"Μπαλάντα για έναν Στρατιώτη","emoji":"🎗️","meta":["πολεμικό δράμα","1959","Γκριγκόρι Τσουχράι"],"description":"Ένας νεαρός στρατιώτης παίρνει μια σύντομη άδεια επειδή χτύπησε ένα εχθρικό τανκ και ξεκινά να δει τη μητέρα του, αλλά στον δρόμο συναντά ανθρώπους που χρειάζονται βοήθεια, κι έτσι για τη συνάντηση μένουν μετρημένα λεπτά. Ένα απλό, συγκινητικό κλασικό.","fact":"Η ταινία πήρε ειδικό βραβείο στις Κάννες και υποψηφιότητα Όσκαρ πρωτότυπου σεναρίου.","wiki_en":"Ballad of a Soldier"},{"name":"Τα Παιδικά Χρόνια του Ιβάν","emoji":"🌒","meta":["πολεμικό δράμα","1962","Αντρέι Ταρκόφσκι"],"description":"Ο Ιβάν, ένα αγόρι που έχασε την οικογένειά του στον πόλεμο, γίνεται μικρός ανιχνευτής και περνά ξανά και ξανά τη γραμμή του μετώπου, όσο κι αν προσπαθούν οι μεγαλύτεροι αξιωματικοί να τον κρατήσουν μακριά. Το πρώτο μεγάλου μήκους του Ταρκόφσκι πήρε Χρυσό Λέοντα.","fact":"Ο Ταρκόφσκι ανέλαβε το έργο αφού τα γυρίσματα είχε ήδη ξεκινήσει άλλος σκηνοθέτης, και το ξαναγύρισε σχεδόν ολόκληρο με τη δική του ματιά.","wiki_en":"Ivan's Childhood"},{"name":"Αντρέι Ρουμπλιόφ","emoji":"🎨","meta":["ιστορικό δράμα","1966","Αντρέι Ταρκόφσκι"],"description":"Σε μια σειρά επεισοδίων η ταινία παρακολουθεί τη ζωή και την πνευματική αναζήτηση του μεσαιωνικού αγιογράφου Αντρέι Ρουμπλιόφ, μέσα στις σκληρές διαμάχες των ηγεμόνων και τις ταταρικές επιδρομές της παλιάς Ρωσίας. Μια από τις κορυφές του παγκόσμιου σινεμά.","fact":"Λόγω της δύσκολης διαδρομής της στη λογοκρισία, η πλήρης εκδοχή του δημιουργού βγήκε στις σοβιετικές αίθουσες χρόνια μετά τα γυρίσματα.","wiki_en":"Andrei Rublev (film)"},{"name":"Ο Καθρέφτης","emoji":"🪞","meta":["δράμα","1975","Αντρέι Ταρκόφσκι"],"description":"Η αυτοβιογραφική και σκόπιμα μη γραμμική ταινία του Ταρκόφσκι ενώνει αναμνήσεις της παιδικής ηλικίας, όνειρα και τους κλυδωνισμούς του 20ού αιώνα σε ένα ποιητικό ρεύμα εικόνων, στη θέση της υπόθεσης. Από τα πιο προσωπικά και τολμηρά έργα του.","fact":"Η ίδια ηθοποιός παίζει τη μητέρα του ήρωα σε διάφορες ηλικίες και τη γυναίκα του, κάτι που δυναμώνει το μπλέξιμο των εποχών.","wiki_en":"Mirror (1975 film)"},{"name":"Σολάρις","emoji":"🪐","meta":["επιστημονική φαντασία","1972","Αντρέι Ταρκόφσκι"],"description":"Ένας ψυχολόγος φτάνει σε έναν τροχιακό σταθμό πάνω από τον αινιγματικό πλανήτη-ωκεανό Σολάρις, όπου το πλήρωμα βλέπει οπτασίες που υλοποιούν τις βαθύτερες μνήμες και ενοχές του. Ο Ταρκόφσκι νοιάζεται πιο πολύ για τον έσω κόσμο παρά για την τεχνολογία του μέλλοντος.","fact":"Ο Ταρκόφσκι περιόρισε επίτηδες τα φουτουριστικά σκηνικά και τις τεχνικές λεπτομέρειες, για να μείνει το βάρος στο ανθρώπινο δράμα.","wiki_en":"Solaris (1972 film)"},{"name":"Άσσα","emoji":"🎸","meta":["δράμα","1987","Σεργκέι Σολοβιόφ"],"description":"Μια νέα κοπέλα που έρχεται στη χειμωνιάτικη Γιάλτα με τον αρχιμαφιόζο Κριμόφ ερωτεύεται τον παράξενο νεαρό μουσικό Μπανανάν, και η ιστορία τους ξετυλίγεται πάνω στη ροκ κουλτούρα που ξυπνά στα χρόνια της περεστρόικα. Η ταινία έγινε έμβλημα των τελών της δεκαετίας του 1980.","fact":"Στην ταινία ακούγονται τραγούδια του συγκροτήματος Κινό, και στο φινάλε εμφανίζεται ο ίδιος ο Βίκτορ Τσόι με το «Αλλαγές».","wiki_en":"Assa (film)"},{"name":"Η Βελόνα","emoji":"💉","meta":["δράμα","1988","Ρασίντ Νουγκμάνοφ"],"description":"Ένας νέος με το παρατσούκλι Μόρο γυρίζει στην πόλη του και προσπαθεί να τραβήξει την παλιά του κοπέλα έξω από τα ναρκωτικά, βάζοντάς τα με όσους βγάζουν λεφτά από τον πόνο της. Ορόσημο του νέου κύματος του Καζακστάν, έγινε καλτ χάρη στον Βίκτορ Τσόι.","fact":"Μέρος της ταινίας γυρίστηκε στην αποξηραμένη Αράλη, και τα πλάνα με τα εγκαταλειμμένα πλοία μέσα στην άμμο έμειναν αξέχαστα.","wiki_en":"The Needle (1988 film)"},{"name":"Η Ειρωνεία της Μοίρας 2","emoji":"🥂","meta":["ρομαντική κομεντί","2007","Τιμούρ Μπεκμαμπέτοφ"],"description":"Τρεις δεκαετίες μετά την παραμονή της Πρωτοχρονιάς της κλασικής ταινίας, τα παιδιά των ηρώων της επαναλαμβάνουν κατά τύχη τη μοίρα των γονιών τους, μπλεγμένα σε ένα παρόμοιο γιορτινό μπέρδεμα στη σημερινή Μόσχα. Η συνέχεια έφερε την υπόθεση στον 21ο αιώνα.","fact":"Στη συνέχεια επέστρεψαν ηθοποιοί της αρχικής ταινίας, παίζοντας τους ίδιους ήρωες γερασμένους.","wiki_en":"Irony of Fate 2","wiki_ru":"Ирония судьбы. Продолжение"},{"name":"Το Γκαράζ","emoji":"🚗","meta":["τραγικωμωδία","1979","Ελντάρ Ριαζάνοφ"],"description":"Μια συνέλευση του συνεταιρισμού που μοιράζει θέσεις για γκαράζ γίνεται ολονύχτιος πόλεμος, όπου φαινομενικά καθωσπρέπει υπάλληλοι ενός ινστιτούτου ξεγυμνώνουν κάθε μικροσυμβιβασμό και υποκρισία τους. Η σάτιρα του Ριαζάνοφ παίζεται σχεδόν όλη σε ένα δωμάτιο.","fact":"Ο ίδιος ο Ελντάρ Ριαζάνοφ παίζει έναν αμίλητο υπάλληλο, που κοιμάται ήσυχος πάνω σε ένα βαλσαμωμένο ζώο όλη τη φασαρία.","wiki_en":"Garage (film)","wiki_ru":"Гараж (фильм)"},{"name":"Φθινοπωρινός Μαραθώνιος","emoji":"🍂","meta":["τραγικωμωδία","1979","Γκεόργκι Ντανέλια"],"description":"Ένας ήπιος και αναποφάσιστος μεταφραστής τραβιέται ανάμεσα στη γυναίκα του, την ερωμένη του και τις ατέλειωτες παρακλήσεις των άλλων, χωρίς να μπορεί να αρνηθεί σε κανέναν, και κάνει σιγά σιγά την καλοσύνη του πηγή δυστυχίας για όλους. Κομεντί και αληθινό δράμα μαζί.","fact":"Η ατάκα «καλά καθόμαστε!» από αυτή την ταινία έφυγε από καιρό από το πλαίσιό της και ζει μόνη της στα ρωσικά.","wiki_en":"Autumn Marathon"},{"name":"Σταθμός για Δύο","emoji":"🚉","meta":["ρομαντικό δράμα","1982","Ελντάρ Ριαζάνοφ"],"description":"Ένας πιανίστας της πρωτεύουσας, που τον περιμένει δίκη για κάτι που δεν έκανε, χάνει το τρένο και γνωρίζει τη σερβιτόρα του κυλικείου ενός επαρχιακού σταθμού, και ανάμεσά τους γεννιέται μια δύσκολη αλλά ειλικρινής σχέση. Λυρισμός και κοφτερή κοινωνική σάτιρα μαζί.","fact":"Η σερβιτόρα είναι από τους πιο σημαντικούς ρόλους της Λιουντμίλα Γκουρτσένκο, που ένωσε εδώ την κομεντί με το δράμα.","wiki_en":"Station for Two"},{"name":"Μιμίνο","emoji":"🚁","meta":["τραγικωμωδία","1977","Γκεόργκι Ντανέλια"],"description":"Ένας Γεωργιανός πιλότος, που πετά με μικρό ελικόπτερο πάνω από ορεινά χωριά, ονειρεύεται τα μεγάλα αεροπλάνα και ξεκινά να κατακτήσει τη Μόσχα, όπου πιάνει απρόσμενα φιλία με έναν Αρμένιο οδηγό φορτηγού. Μια ζεστή κομεντί, από τις πιο αγαπημένες σοβιετικές.","fact":"Η ατάκα του Ρούμπικ «έτσι νομίζω εγώ!» έγινε τόσο γνωστή που την αναγνωρίζουν ακόμη και όσοι δεν έχουν δει την ταινία.","wiki_en":"Mimino","wiki_ru":"Мимино"},{"name":"Αφόνια","emoji":"🔧","meta":["τραγικωμωδία","1975","Γκεόργκι Ντανέλια"],"description":"Ένας υδραυλικός με το παρατσούκλι Αφόνια ζει έκλυτη εργένικη ζωή, κλέβει στα μεροκάματα και τα πίνει, ώσπου μια σειρά τυχαίων συναντήσεων τον βάζει να σκεφτεί τη μοναξιά του και το κενό αυτής της ζωής. Ο Ντανέλια δένει το καθημερινό χιούμορ με ένα πικρό δίδαγμα.","fact":"Ο Αφόνια είναι από τους πιο αναγνωρίσιμους ρόλους του Λεονίντ Κουραβλιόφ, σταθερής παρουσίας στις σοβιετικές κομεντί της εποχής.","wiki_en":"Afonya","wiki_ru":"Афоня"},{"name":"Το Πλήρωμα","emoji":"🛫","meta":["ταινία καταστροφής","1979","Αλεξάντρ Μίτα"],"description":"Τρία μέλη του πληρώματος ενός επιβατικού αεροσκάφους, με πολύ διαφορετικούς χαρακτήρες και προσωπικά προβλήματα, βρίσκονται μπροστά σε αληθινή καταστροφή, όταν στη μακρινή πόλη όπου πέταξαν για τραυματίες ξεσπά φονικός σεισμός. Από τις πρώτες σοβιετικές ταινίες καταστροφής.","fact":"Για τις σκηνές με το χτυπημένο αεροσκάφος χρησιμοποιήθηκε ένα αληθινό, αποσυρμένο αεροπλάνο, όχι μόνο μακέτες και σκηνικά.","wiki_en":"Air Crew","wiki_ru":"Экипаж (фильм, 1979)"},{"name":"Οι Πειρατές του 20ού Αιώνα","emoji":"🏴‍☠️","meta":["ταινία δράσης","1979","Μπορίς Ντούροφ"],"description":"Το πλήρωμα ενός σοβιετικού εμπορικού πλοίου δέχεται επίθεση από σύγχρονους πειρατές λαθρεμπόρους που κυνηγούν ένα φορτίο οπίου, και οι ναυτικοί αναγκάζονται να τα βάλουν με καλά οπλισμένους κακοποιούς. Από τις πρώτες σοβιετικές ταινίες δράσης με πολεμικές τέχνες.","fact":"Έγινε από τις εμπορικότερες ταινίες στην ιστορία των σοβιετικών αιθουσών, κυρίως χάρη στις ασυνήθιστες τότε σκηνές μάχης σώμα με σώμα.","wiki_en":"Pirates of the 20th Century","wiki_ru":"Пираты XX века"},{"name":"Ο Άνθρωπος-Αμφίβιο","emoji":"🐟","meta":["επιστημονική φαντασία","1961","Γκενάντι Καζάνσκι, Βλαντίμιρ Τσεμποταριόφ"],"description":"Ο Ιχθύανδρος, που ως παιδί του μεταμοσχεύτηκαν βράγχια καρχαρία, ζει ελεύθερα και στη στεριά και στον βυθό, αλλά ερωτεύεται μια κοινή θνητή και πρέπει να διαλέξει ανάμεσα στους δύο κόσμους. Από τις πρώτες σοβιετικές ταινίες με μεγάλα υποβρύχια γυρίσματα.","fact":"Οι υποβρύχιες σκηνές γυρίστηκαν στη Μαύρη Θάλασσα χωρίς σύγχρονο καταδυτικό εξοπλισμό, κάτι πραγματικά επικίνδυνο για τους ηθοποιούς.","wiki_en":"Amphibian Man","wiki_ru":"Человек-амфибия (фильм)"},{"name":"Οι Περιπέτειες του Ηλεκτρόνικ","emoji":"🤖","meta":["επιστημονική φαντασία","1979","Κονσταντίν Μπρόμπεργκ"],"description":"Ένας επιστήμονας φτιάχνει ένα ρομπότ-μαθητή, τον Ηλεκτρόνικ, ολόιδιο με ένα αληθινό αγόρι, τον Σεργκέι Σιροέζκιν, και όταν το ρομπότ δραπετεύει από το εργαστήριο αρχίζει μια σειρά μπερδεμάτων με τους δύο σωσίες. Αγαπημένη σοβιετική παιδική τηλεταινία.","fact":"Το τραγούδι «Οι φτερωτές κούνιες» από αυτή την ταινία έγινε ένα από τα πιο γνωστά παιδικά τραγούδια της σοβιετικής εποχής.","wiki_en":"The Adventures of Elektronik","wiki_ru":"Приключения Электроника"},{"name":"Οι Δώδεκα Καρέκλες","emoji":"🪑","meta":["κομεντί","1971","Λεονίντ Γκαϊντάι"],"description":"Ο πρώην ευγενής Ιππόλιτ Βορομπιάνινοφ και ο πανούργος τυχοδιώκτης Οστάπ Μπέντερ κυνηγούν τα οικογενειακά διαμάντια, κρυμμένα σε μία από δώδεκα καρέκλες που ξεπουλήθηκαν σε όλη τη χώρα μετά την επανάσταση. Από το μυθιστόρημα των Ιλφ και Πετρόφ.","fact":"Τον Οστάπ Μπέντερ παίζει εδώ ο Αρτσίλ Γκομιασβίλι, αν και τον ίδιο ήρωα έχουν δώσει και άλλοι γνωστοί ηθοποιοί.","wiki_en":"The Twelve Chairs (1971 film)"},{"name":"Αδύνατον!","emoji":"🎭","meta":["κομεντί","1975","Λεονίντ Γκαϊντάι"],"description":"Τρεις ξεχωριστές κωμικές ιστορίες, από τα πρώτα ευθυμογραφήματα του Μιχαήλ Ζόστσενκο, όπου άτυχοι Σοβιετικοί πολίτες μπλέκουν σε γελοίες καθημερινές καταστάσεις από δική τους πονηριά ή απληστία. Ο Γκαϊντάι μάζεψε ξανά πλειάδα ηθοποιών για αυτή την ταινία.","fact":"Και οι τρεις ιστορίες παίζονται στη δεκαετία του 1920 της Νέας Οικονομικής Πολιτικής, ακριβώς την εποχή για την οποία έγραφε ο Ζόστσενκο.","wiki_en":"It Can't Be! (film)","wiki_ru":"Не может быть! (фильм)"},{"name":"Σπορτλότο-82","emoji":"🎟️","meta":["κομεντί","1982","Λεονίντ Γκαϊντάι"],"description":"Ένας νέος σε διακοπές σε θέρετρο της Μαύρης Θάλασσας χάνει ένα λαχείο με μεγάλο κέρδος και ξεκινά με μια καινούρια γνωριμία να το βρει, ενώ στα ίχνη του ίδιου λαχείου είναι κι ένας επιτήδειος μαυραγορίτης. Μια από τις ύστερες κομεντί του Γκαϊντάι.","fact":"Ο τίτλος παραπέμπει στο υπαρκτό σοβιετικό λαχείο Σπορτλότο, που τότε το έπαιζε όλη η χώρα.","wiki_en":"Sportloto-82","wiki_ru":"Спортлото-82"},{"name":"Οι Πύλες Ποκρόφσκι","emoji":"🏙️","meta":["κομεντί","1982","Μιχαήλ Καζακόφ"],"description":"Η ζεστή, νοσταλγική κομεντί παίζεται σε ένα κοινόχρηστο διαμέρισμα της συνοικίας Ποκρόφσκι της Μόσχας στα μέσα της δεκαετίας του 1950, όπου μπλέκονται οι ζωές και οι έρωτες μερικών γραφικών γειτόνων. Από τις πιο αγαπημένες σοβιετικές τηλεταινίες.","fact":"Πέρασε μέτρια στην πρώτη τηλεοπτική προβολή, αλλά έγινε με τα χρόνια καλτ και παίζεται από τότε συνεχώς στην τηλεόραση.","wiki_en":"Pokrovsky Gates","wiki_ru":"Покровские ворота (фильм)"},{"name":"Η Φόρμουλα του Έρωτα","emoji":"🪄","meta":["κομεντί","1984","Μαρκ Ζαχάροφ"],"description":"Ο μυστηριώδης κόμης Καλιόστρο, που φημολογείται ότι έχει μαγικές δυνάμεις και τη φόρμουλα της αιώνιας νιότης, φτάνει σε ένα ρωσικό αρχοντικό της επαρχίας στα τέλη του 18ου αιώνα, και οι ντόπιοι ευγενείς τον βάζουν αμέσως στην υπηρεσία των συμφερόντων τους.","fact":"Η ατάκα «θέλεις μεγάλη αγάπη, αλλά καθαρή;» από αυτή την ταινία έγινε από καιρό ειρωνικό λαϊκό ρητό.","wiki_en":"The Formula of Love","wiki_ru":"Формула любви"},{"name":"Ο Ίδιος ο Μυνχάουζεν","emoji":"🎈","meta":["κομεντί","1979","Μαρκ Ζαχάροφ"],"description":"Ο θρυλικός βαρόνος Μυνχάουζεν προσπαθεί να πείσει μια τυπολάτρη γερμανική κοινωνία ότι οι απίστευτες περιπέτειές του συνέβησαν αληθινά, και συναντά τη γραφειοκρατική απαίτηση να αποδείξει επισήμως την ταυτότητά του. Ο Ζαχάροφ κάνει το παραμύθι παραβολή για τον κομφορμισμό.","fact":"Το «Χαμογελάτε, κύριοι, χαμογελάτε» του Μυνχάουζεν είναι από τις πιο πολυαναφερόμενες ατάκες της σοβιετικής τηλεόρασης.","wiki_en":"The Very Same Munchhausen","wiki_ru":"Тот самый Мюнхгаузен"},{"name":"Ένα Συνηθισμένο Θαύμα","emoji":"🐻","meta":["παραμύθι","1978","Μαρκ Ζαχάροφ"],"description":"Ένας μάγος που ζει μακριά από ανθρώπους μεταμορφώνει μια αρκούδα σε όμορφο νέο, αλλά τον προειδοποιεί ότι θα ξαναγίνει θηρίο αν τον φιλήσει μια ερωτευμένη πριγκίπισσα — και μετά παρακολουθεί την ιστορία να ξετυλίγεται. Από θεατρικό του Γεβγκένι Σβαρτς.","fact":"Τη μουσική έγραψε ο Γκενάντι Γκλαντκόφ και τους στίχους ο Γιούλι Κιμ, που τότε αναγκαζόταν να υπογράφει με ψευδώνυμο.","wiki_en":"An Ordinary Miracle","wiki_ru":"Обыкновенное чудо (фильм, 1978)"},{"name":"Γεια σας, Είμαι η Θεία σας!","emoji":"👒","meta":["κομεντί","1975","Βίκτορ Τίτοφ"],"description":"Ο αλήτης Μπαμπς Μπάμπερλεϊ, που βρέθηκε κατά τύχη στο σπίτι δύο φοιτητών της Οξφόρδης, δέχεται να παραστήσει την πλούσια θεία τους από τη Βραζιλία, «εκεί που τα δάση έχουν πολλές, πολλές άγριες μαϊμούδες», και το μικρό ψέμα γίνεται χιονοστιβάδα παρεξηγήσεων.","fact":"Τον πρωταγωνιστή παίζει ο Αλεξάντρ Καλιάγκιν, που η εκκεντρική σωματική του δεινότητα έκανε τον ρόλο αξέχαστο.","wiki_en":"Hello, I'm Your Aunt!","wiki_ru":"Здравствуйте, я ваша тётя!"},{"name":"Μορόζκο","emoji":"❄️","meta":["παραμύθι","1964","Αλεξάντρ Ρόου"],"description":"Η ιδιότροπη κόρη της μητριάς και η καλόκαρδη ορφανή Ναστένκα συναντούν και οι δύο τον Μορόζκο, το αυστηρό πνεύμα του χειμωνιάτικου δάσους, που δοκιμάζει την καλοσύνη και την εργατικότητά τους πριν ανταμείψει ή τιμωρήσει. Κλασικό σοβιετικό παραμύθι των γιορτών.","fact":"Στις ΗΠΑ κυκλοφόρησε ως Jack Frost και αργότερα έγινε στόχος καλοπροαίρετης κοροϊδίας σε μια καλτ εκπομπή για παράξενες ταινίες.","wiki_en":"Morozko","wiki_ru":"Морозко"},{"name":"Οι Περιπέτειες του Μπουρατίνο","emoji":"🪵","meta":["μουσικό παραμύθι","1975","Λεονίντ Νετσάγεφ"],"description":"Ο Μπουρατίνο, ένα ξύλινο αγόρι που σκάλισε ο παπα-Κάρλο από ένα κούτσουρο, ξεκινά για το σχολείο, αλλά στον δρόμο ενδίδει στους πειρασμούς του γάτου Μπαζίλιο και της αλεπούς Αλίσα και μπλέκει σε επικίνδυνες και αστείες περιπέτειες για ένα χρυσό κλειδί.","fact":"Τα τραγούδια της ταινίας, μαζί και το περίφημο «Μπουρατίνο», ακούγονται από τότε σε παιδικές γιορτές σε όλη τη χώρα.","wiki_en":"The Adventures of Buratino","wiki_ru":"Приключения Буратино (фильм)"},{"name":"Το Σκιάχτρο","emoji":"🎒","meta":["δράμα","1983","Ρολάν Μπίκοφ"],"description":"Ένα καινούριο κορίτσι σε μια σχολική τάξη παίρνει πάνω του ξένη ευθύνη και γίνεται στόχος σκληρού εκφοβισμού από τους συμμαθητές του, μένοντας ολομόναχο σε αυτή τη δοκιμασία. Από τις πρώτες σοβιετικές ταινίες που μίλησαν ανοιχτά για τον σχολικό εκφοβισμό.","fact":"Τον πρωταγωνιστικό ρόλο έπαιξε η δωδεκάχρονη Κριστίνα Ορμπακάιτε, για την οποία η ταινία ήταν το ντεμπούτο της.","wiki_en":"Scarecrow (1983 film)","wiki_ru":"Чучело (фильм)"},{"name":"Ο Διανομέας","emoji":"📮","meta":["τραγικωμωδία","1986","Κάρεν Σαχναζάροφ"],"description":"Ένας απόφοιτος λυκείου που δεν πέρασε στο πανεπιστήμιο πιάνει δουλειά διανομέας σε ένα περιοδικό, και με τον ειρωνικό, λίγο θρασύ τρόπο του μπερδεύει τους μεγάλους, που είναι μαθημένοι σε άλλους κανόνες. Η ταινία έπιασε τη διάθεση της νεολαίας της περεστρόικα.","fact":"Πρωταγωνιστής ήταν ο Φιόντορ Ντουναγέφσκι, για τον οποίο ήταν από τους λίγους αξιοσημείωτους ρόλους μιας σύντομης καριέρας.","wiki_en":"Courier (1986 film)","wiki_ru":"Курьер"},{"name":"Η Μικρή Βέρα","emoji":"🏭","meta":["δράμα","1988","Βασίλι Πιτσούλ"],"description":"Μια νέα κοπέλα από οικογένεια εργατών σε μια επαρχιακή βιομηχανική πόλη προσπαθεί να ξεφύγει από μια πνιγηρή ρουτίνα και τις διαρκείς συγκρούσεις με τους γονείς της, μέσα από τη σχέση της με έναν νέο. Από τις πρώτες σοβιετικές ταινίες που μίλησαν ανοιχτά για τους νέους.","fact":"Γυρίστηκε στο Ζντάνοφ, τη σημερινή Μαριούπολη, και τα εργοστασιακά προάστια της πόλης έγιναν σχεδόν ξεχωριστός χαρακτήρας.","wiki_en":"Little Vera"},{"name":"Βίι","emoji":"👹","meta":["ταινία τρόμου","1967","Κονσταντίν Γερσόφ, Γκεόργκι Κροπατσόφ"],"description":"Ένας νεαρός ιεροσπουδαστής, που έγινε κατά λάθος αιτία θανάτου μιας μάγισσας, είναι υποχρεωμένος να διαβάζει πάνω από το φέρετρό της σε μια παλιά εκκλησία τρεις νύχτες στη σειρά, και κάθε νύχτα οι δυνάμεις του άλλου κόσμου πιέζουν πιο πολύ. Από τον Γκόγκολ.","fact":"Για τη μορφή του τέρατος Βίι και των άλλων πλασμάτων, το συνεργείο χρησιμοποίησε μακιγιάζ και μηχανισμούς προχωρημένους για την εποχή.","wiki_en":"Viy (1967 film)"},{"name":"Νυχτερινή Περιπολία","emoji":"🌙","meta":["ταινία φαντασίας","2004","Τιμούρ Μπεκμαμπέτοφ"],"description":"Στη σημερινή Μόσχα κρατά έναν αιώνιο, κρυμμένο από τους απλούς ανθρώπους πόλεμο ανάμεσα στις δυνάμεις του Φωτός και του Σκότους, και ο Μοσχοβίτης Αντόν, που ανακαλύπτει ότι είναι Άλλος, βρίσκεται στο κέντρο του, στο πλευρό του Φωτός. Από το βιβλίο του Σεργκέι Λουκιανένκο.","fact":"Έσπασε το ρεκόρ εισπράξεων για ρωσική ταινία στην εποχή της, περνώντας μπροστά από πολλές παραγωγές του Χόλιγουντ εκείνης της χρονιάς.","wiki_en":"Night Watch (2004 film)"},{"name":"Ημερήσια Περιπολία","emoji":"☀️","meta":["ταινία φαντασίας","2006","Τιμούρ Μπεκμαμπέτοφ"],"description":"Η ιστορία του πολέμου Φωτός και Σκότους στη Μόσχα ανεβαίνει επίπεδο, όταν μπαίνει στο παιχνίδι ένα αρχαίο αντικείμενο ικανό να ξαναγράψει την ίδια τη μοίρα του κόσμου. Η συνέχεια της «Νυχτερινής Περιπολίας» μεγάλωσε κι άλλο τα εφέ και το θέαμα της πρώτης ταινίας.","fact":"Κάποιες από τις τελικές σκηνές γυρίστηκαν σε αληθινά σημεία της Μόσχας, μεταμορφωμένα με ψηφιακά γραφικά.","wiki_en":"Day Watch","wiki_ru":"Дневной Дозор (фильм)"},{"name":"Ο 9ος Λόχος","emoji":"🪖","meta":["πολεμικό δράμα","2005","Φιόντορ Μπονταρτσούκ"],"description":"Μια ομάδα νεαρών κληρωτών περνά σκληρή εκπαίδευση πριν σταλεί στο Αφγανιστάν, και μετά βρίσκεται σε ένα απομονωμένο ύψωμα που η σοβιετική μονάδα πρέπει να κρατήσει απέναντι σε πολύ ισχυρότερο εχθρό. Από τις πιο γνωστές ρωσικές ταινίες για εκείνον τον πόλεμο.","fact":"Η υπόθεση βασίζεται στην αληθινή μάχη για το ύψωμα 3234, που δόθηκε στο Αφγανιστάν το 1988.","wiki_en":"9th Company"},{"name":"T-34","emoji":"🪖","meta":["πολεμικό δράμα","2018","Αλεξέι Σιντόροφ"],"description":"Ένας νεαρός Σοβιετικός οδηγός άρματος πέφτει αιχμάλωτος των Γερμανών και, χρόνια μετά, τον βάζουν να δοκιμάσει ένα κατασχεμένο T-34 απέναντι σε έμπειρο γερμανικό πλήρωμα — κάτι που του δίνει απρόσμενη ευκαιρία για τολμηρή απόδραση. Από τις εμπορικότερες ρωσικές πολεμικές ταινίες.","fact":"Για τα γυρίσματα κατασκευάστηκαν αρκετά λειτουργικά αντίγραφα αρμάτων T-34 και γερμανικών οχημάτων της εποχής σε φυσικό μέγεθος.","wiki_en":"T-34 (2018 film)","wiki_ru":"Т-34"},{"name":"Τρία Δευτερόλεπτα","emoji":"🏀","meta":["αθλητικό δράμα","2017","Αντόν Μεγκερντίτσεφ"],"description":"Η ταινία ξαναζωντανεύει τον θρυλικό τελικό του μπάσκετ στους Ολυμπιακούς Αγώνες του 1972 ανάμεσα στην ΕΣΣΔ και τις ΗΠΑ, έναν από τους πιο δραματικούς και πιο αμφισβητημένους αγώνες στην ιστορία του αθλήματος. Έγινε μία από τις μεγάλες ρωσικές εισπρακτικές επιτυχίες.","fact":"Οι σχολιαστές θυμούνται ακόμη τα τελευταία δευτερόλεπτα εκείνου του τελικού ως μία από τις πιο αγωνιώδεις στιγμές του μπάσκετ.","wiki_en":"Three Seconds (film)","wiki_ru":"Движение вверх (фильм)"},{"name":"Ο Θρύλος Νο 17","emoji":"🏒","meta":["αθλητικό δράμα","2013","Νικολάι Λεμπέντεφ"],"description":"Η ταινία παρακολουθεί τη διαμόρφωση του θρυλικού Σοβιετικού χοκεΐστα Βαλέρι Χαρλάμοφ, τον δύσκολο δρόμο του προς την κορυφή και την αναμέτρησή του με την αστρική καναδική ομάδα στην ιστορική σειρά αγώνων του 1972. Από τις πιο επιτυχημένες ρωσικές αθλητικές ταινίες.","fact":"Το προπονητικό κέντρο όπου ετοιμάστηκαν οι ηθοποιοί για τις σκηνές του χόκεϊ το έτρεχαν αληθινοί επαγγελματίες προπονητές.","wiki_en":"Legend No. 17","wiki_ru":"Легенда №17"},{"name":"Ο Βίκινγκ","emoji":"⚔️","meta":["ιστορικό δράμα","2016","Αντρέι Κραφτσούκ"],"description":"Η ταινία καλύπτει τα πρώτα χρόνια της βασιλείας του πρίγκιπα Βλαντίμιρ Σβιατοσλάβιτς, τη μάχη του για τον θρόνο του Κιέβου και τη μοιραία επιλογή μιας νέας πίστης για την παλιά Ρωσία. Το ιστορικό έπος του Αντρέι Κραφτσούκ ήταν από τις ακριβότερες ρωσικές παραγωγές.","fact":"Για τις σκηνές μάχης χτίστηκαν σκηνικά του αρχαίου Κιέβου και χρησιμοποιήθηκαν εκατοντάδες κασκαντέρ και κομπάρσοι.","wiki_en":"Viking (2016 film)"},{"name":"Στάλινγκραντ","emoji":"🏚️","meta":["πολεμικό δράμα","2013","Φιόντορ Μπονταρτσούκ"],"description":"Μια μικρή ομάδα Σοβιετικών στρατιωτών ταμπουρώνεται σε ένα μισογκρεμισμένο σπίτι κοντά στον Βόλγα, στη μάχη του Στάλινγκραντ, και μαζί με μια κοπέλα που ζει ακόμη εκεί προσπαθεί να κρατήσει τη θέση. Ήταν από τις πρώτες ρωσικές ταινίες γυρισμένες σε IMAX 3D.","fact":"Η ταινία ήταν η πρόταση της Ρωσίας για το Όσκαρ ξενόγλωσσης ταινίας.","wiki_en":"Stalingrad (2013 film)"},{"name":"Ο Ηλίθιος","emoji":"🏚️","meta":["κοινωνικό δράμα","2014","Γιούρι Μπίκοφ"],"description":"Ένας υδραυλικός βρίσκει σε έναν παλιό εργατικό ξενώνα μια ρωγμή που σημαίνει ότι το κτίριο θα πέσει, και περνά μια ολόκληρη νύχτα προσπαθώντας να πείσει αδιάφορους αξιωματούχους να εκκενώσουν εκατοντάδες ενοίκους, βρίσκοντας μπροστά του τοίχο διαφθοράς.","fact":"Όλη η ταινία εξελίσσεται μέσα σε μία νύχτα, σχεδόν σε πραγματικό χρόνο, κι αυτό σφίγγει ακόμη πιο πολύ την ένταση.","wiki_en":"The Fool (2014 film)"},{"name":"Αρρυθμία","emoji":"❤️‍🩹","meta":["δράμα","2017","Μπορίς Χλέμπνικοφ"],"description":"Ένας γιατρός του ασθενοφόρου, που δίνει τα πάντα στους ασθενείς του αλλά έχει στραγγίξει συναισθηματικά, ισορροπεί στο χείλος του διαζυγίου με τη γυναίκα του, γιατρό κι εκείνη, προσπαθώντας να κρατήσει και τη δουλειά και τον γάμο. Πήρε το μεγάλο βραβείο στο Κινοτάβρ.","fact":"Πολλές σκηνές περιστατικών γυρίστηκαν με αληθινούς γιατρούς ως συμβούλους, για να αποδοθεί σωστά η δουλειά τους.","wiki_en":"Arrhythmia (film)"},{"name":"Χωρίς Αγάπη","emoji":"🏚️","meta":["δράμα","2017","Αντρέι Ζβιάγκιντσεφ"],"description":"Ένα ζευγάρι μέσα σε ένα άσχημο διαζύγιο, απορροφημένο από τις αμοιβαίες κατηγορίες και τις νέες του σχέσεις, καταλαβαίνει πολύ αργά ότι ο γιος τους έχει εξαφανιστεί από το σπίτι. Το δράμα του Ζβιάγκιντσεφ πήρε βραβείο επιτροπής στις Κάννες και υποψηφιότητα Όσκαρ.","fact":"Είναι από τις πιο βραβευμένες ρωσικές ταινίες στα διεθνή φεστιβάλ της τελευταίας δεκαετίας.","wiki_en":"Loveless (film)"},{"name":"Λεβιάθαν","emoji":"🐋","meta":["δράμα","2014","Αντρέι Ζβιάγκιντσεφ"],"description":"Ένας μηχανικός αυτοκινήτων σε μια μικρή παραθαλάσσια πόλη τα βάζει με τον διεφθαρμένο δήμαρχο, που θέλει να του πάρει το σπίτι και τη γη του, και αυτή η χαμένη μάχη γκρεμίζει σιγά σιγά όλη του τη ζωή. Το δράμα πήρε Χρυσή Σφαίρα και υποψηφιότητα Όσκαρ.","fact":"Ο τίτλος παραπέμπει και στο βιβλικό τέρας και στην ομώνυμη πραγματεία του Τόμας Χομπς για τη φύση της κρατικής εξουσίας.","wiki_en":"Leviathan (2014 film)"},{"name":"Ελένα","emoji":"🏢","meta":["δράμα","2011","Αντρέι Ζβιάγκιντσεφ"],"description":"Μια γυναίκα μεγάλης ηλικίας, παντρεμένη με έναν εύπορο άντρα από άλλον κοινωνικό κόσμο, βρίσκεται μπροστά σε δύσκολη ηθική επιλογή, όταν ο ενήλικος γιος της από τον πρώτο της γάμο χρειάζεται επειγόντως χρήματα και ο σύζυγος δεν σκοπεύει να βοηθήσει.","fact":"Οι κριτικοί ξεχώρισαν το συγκρατημένο, σχεδόν ντοκιμαντερίστικο ύφος της, χωρίς περιττή μουσική και μεγαλοστομία.","wiki_en":"Elena (2011 film)"},{"name":"Η Επιστροφή","emoji":"🚤","meta":["δράμα","2003","Αντρέι Ζβιάγκιντσεφ"],"description":"Δύο έφηβοι αδελφοί που μεγάλωσαν χωρίς πατέρα τον συναντούν ξαφνικά μετά από χρόνια απουσίας, και εκείνος τους παίρνει σε ένα μυστηριώδες ταξίδι σε μια μακρινή λίμνη, που ξεσκεπάζει σιγά σιγά τη δύσκολη σχέση τους. Το ντεμπούτο του πήρε Χρυσό Λέοντα στη Βενετία.","fact":"Είναι σπάνιο μια πρώτη ταινία σκηνοθέτη να παίρνει κατευθείαν το μεγάλο βραβείο ενός από τα τρία μεγάλα ευρωπαϊκά φεστιβάλ.","wiki_en":"The Return (2003 film)"},{"name":"Φορτίο 200","emoji":"🚔","meta":["δράμα","2007","Αλεξέι Μπαλαμπάνοφ"],"description":"Σε μια επαρχιακή πόλη της ύστερης σοβιετικής εποχής ένας βάναυσος αστυνομικός απαγάγει μια κοπέλα, και η μοίρα της δένεται με την κατάρρευση κάθε ηθικού κανόνα μιας εποχής που σβήνει. Το ζοφερό, επίτηδες σοκαριστικό δράμα του Μπαλαμπάνοφ προκάλεσε θύελλα αντιδράσεων.","fact":"Ο τίτλος είναι ο στρατιωτικός κώδικας «φορτίο 200», που στο σοβιετικό σύστημα σήμαινε τη μεταφορά σορών στρατιωτικών.","wiki_en":"Cargo 200","wiki_ru":"Груз 200 (фильм)"},{"name":"Τυφλόμυγα","emoji":"🔫","meta":["μαύρη κομεντί","2005","Αλεξέι Μπαλαμπάνοφ"],"description":"Δύο μικροκακοποιοί σε μια επαρχιακή πόλη της δεκαετίας του 1990 προσπαθούν να κλείσουν μια δουλειά με μια βαλίτσα ναρκωτικά, αλλά η απλή αποστολή γίνεται αλυσίδα παράλογων και αιματηρών παρεξηγήσεων με άλλες συμμορίες. Μια γκροτέσκα σάτιρα της δεκαετίας των συμμοριών.","fact":"Η ταινία μάζεψε πλειάδα Ρώσων ηθοποιών, πολλοί από τους οποίους έπαιξαν γκροτέσκους εγκληματίες, πολύ μακριά από τους συνήθεις ρόλους τους.","wiki_en":"Dead Man's Bluff"},{"name":"Γκόρκο!","emoji":"🥂","meta":["κομεντί","2013","Ζόρα Κριζόβνικοφ"],"description":"Ένα νεαρό ζευγάρι ονειρεύεται έναν μικρό σύγχρονο γάμο, αλλά οι γονείς επιμένουν σε πλουσιοπάροχο παραδοσιακό γλέντι με όλα τα συμπράγκαλα, και η γιορτή γίνεται αλυσίδα κωμικών καταστροφών. Ο τίτλος είναι η κραυγή που φωνάζουν οι καλεσμένοι στους ρωσικούς γάμους.","fact":"Είναι γυρισμένη σαν ερασιτεχνικό υλικό από κάμερα γάμου, κάτι που δίνει σε όσα βλέπουμε αίσθηση ντοκιμαντέρ.","wiki_en":"Gorko!"},{"name":"Γιόλκι","emoji":"🎄","meta":["πρωτοχρονιάτικη κομεντί","2010","Τιμούρ Μπεκμαμπέτοφ κ.ά."],"description":"Την παραμονή της Πρωτοχρονιάς ένα μήνυμα για τον πρόεδρο της χώρας περνά από στόμα σε στόμα μέσα από μια αλυσίδα τυχαίων γνωριμιών, ενώ παράλληλα ξετυλίγονται αστείες γιορτινές ιστορίες σε διάφορες ρωσικές πόλεις. Η ταινία ξεκίνησε μια ετήσια σειρά.","fact":"Η επιτυχία της πρώτης ταινίας έφερε ολόκληρη σειρά συνεχειών, που έβγαιναν κάθε φορά ακριβώς για την Πρωτοχρονιά.","wiki_en":"Yolki (film)","wiki_ru":"Ёлки (фильм)"},{"name":"Η Καλύτερη Ταινία","emoji":"🎬","meta":["κομεντί παρωδίας","2008","Κιρίλ Κουζίν"],"description":"Μια παρωδία στημένη ως σειρά σκετς: οι δημιουργοί περνούν από μέσα τους τα κλισέ δημοφιλών ρωσικών ταινιών, σειρών και διαφημίσεων, ξαναπαίζοντας γνωστές σκηνές. Μάζεψε πλειάδα Ρώσων κωμικών και ήταν μεγάλη εισπρακτική επιτυχία της χρονιάς της.","fact":"Ο τίτλος και το ύφος παρωδούν τις χολιγουντιανές σειρές παρωδίας, όπως το Scary Movie, προσαρμοσμένες σε ρωσικό υλικό.","wiki_en":"The Best Movie"},{"name":"Λιουμπόφ-Μόρκοφ","emoji":"🥕","meta":["κομεντί","2007","Αλεξάντρ Στριζένοφ"],"description":"Ένα ζευγάρι που έχει κουραστεί το ένα με το άλλο μετά από χρόνια γάμου ανταλλάσσει απρόσμενα σώματα μετά από μια συνεδρία με μέντιουμ, και ο καθένας πρέπει να ζήσει μια μέρα στο πετσί του άλλου. Έγινε από τις πιο δημοφιλείς ρωσικές οικογενειακές κομεντί της εποχής.","fact":"Η επιτυχία της έφερε αρκετές συνέχειες, όπου το ίδιο ζευγάρι μπλέκει ξανά σε παρόμοιες μαγικές μεταμορφώσεις.","wiki_en":"Lyubov-Morkov","wiki_ru":"Любовь-морковь"},{"name":"Ο Ιβάν Τσαρέβιτς και ο Γκρίζος Λύκος","emoji":"🐺","meta":["κινούμενα σχέδια","2011","Βλαντίμιρ Τοροπτσίν"],"description":"Ο Ιβάν, ο άτυχος μικρότερος γιος του τσάρου, ξεκινά με έναν πανέξυπνο Γκρίζο Λύκο που μιλάει για να φέρει το Πυρόπουλο και να γιατρέψει τον άρρωστο πατέρα του, περνώντας από κωμικές περιπέτειες με ήρωες της λαϊκής παράδοσης. Παραμύθι με σύγχρονο χιούμορ.","fact":"Η επιτυχία της πρώτης ταινίας ξεκίνησε ολόκληρη σειρά συνεχειών για τον Ιβάν Τσαρέβιτς και τον λύκο σύντροφό του.","wiki_en":"Ivan Tsarevich and the Grey Wolf","wiki_ru":"Иван Царевич и Серый Волк"},{"name":"Οι Τρεις Μπογατίρ και η Βασίλισσα της Σαμαχάν","emoji":"🐴","meta":["κινούμενα σχέδια","2010","Σεργκέι Γκλέζιν"],"description":"Οι ήρωες Ίλια Μούρομετς, Ντομπρίνια Νικίτιτς και Αλιόσα Ποπόβιτς, μαζί με τον αιώνια πονηρό πρίγκιπα του Κιέβου, μπλέκουν με τη δολερή Βασίλισσα της Σαμαχάν, που τα μάγια της αναποδογυρίζουν τη ζωή της πόλης. Μία από τις ταινίες μιας δημοφιλούς ρωσικής σειράς.","fact":"Οι ταινίες για τους τρεις μπογατίρ έγιναν μία από τις πιο μακρόβιες και κερδοφόρες ρωσικές σειρές κινουμένων σχεδίων.","wiki_en":"Three Bogatyrs and the Shamakhan Queen","wiki_ru":"Три богатыря и Шамаханская царица"},{"name":"Χόλοπ","emoji":"🎩","meta":["κομεντί","2019","Κλιμ Σιπένκο"],"description":"Έναν κακομαθημένο πλούσιο κληρονόμο, μετά από μια ακόμη ασχήμια, η οικογένειά του τον ρίχνει με τέχνασμα σε ένα σκηνοθετημένο χωριό δουλοπάροικων του 19ου αιώνα, όπου τον βάζουν να ζήσει και να δουλέψει με αληθινούς χωρικούς, για να μάθει ταπεινοφροσύνη.","fact":"Όταν βγήκε, ήταν η εμπορικότερη ρωσική ταινία στις εγχώριες αίθουσες, με εισπράξεις πάνω από τρία δισεκατομμύρια ρούβλια.","wiki_en":"Kholop","wiki_ru":"Холоп (фильм, 2019)"},{"name":"Ταγματάρχης Γκρομ: Ο Γιατρός της Πανούκλας","emoji":"🦇","meta":["ταινία υπερηρώων","2021","Όλεγκ Τρόφιμ"],"description":"Ο άκαμπτος αστυνομικός της Πετρούπολης Ίγκορ Γκρομ τα βάζει με έναν μυστηριώδη μασκοφόρο τιμωρό, τον Γιατρό της Πανούκλας, που αποδίδει δική του δικαιοσύνη στους διεφθαρμένους της πόλης. Από τις πρώτες αξιόλογες ρωσικές απόπειρες σε σινεμά υπερηρώων.","fact":"Η ταινία βασίζεται σε σειρά ρωσικών κόμικς του εκδοτικού οίκου Bubble, που κυκλοφορούν από τις αρχές της δεκαετίας του 2010.","wiki_en":"Major Grom: Plague Doctor"},{"name":"Έλξη","emoji":"🛸","meta":["επιστημονική φαντασία","2017","Φιόντορ Μπονταρτσούκ"],"description":"Μετά τη συντριβή ενός άγνωστου σκάφους στα όρια της Μόσχας, ο πανικός και η επιθετικότητα απλώνονται στη φοβισμένη γειτονιά, ενώ η κόρη ενός αξιωματικού βρίσκει απρόσμενα κοινή γλώσσα με τον εξωγήινο επισκέπτη. Θέαμα και δράμα του φόβου μαζί.","fact":"Οι σκηνές της συντριβής γυρίστηκαν σε μεγάλα σκηνικά που μιμούνταν μια αληθινή συνοικία κατοικιών της Μόσχας.","wiki_en":"Attraction (2017 film)"},{"name":"Avatar: Ο Δρόμος του Νερού","emoji":"🌊","meta":["επιστημονική φαντασία","2022","Τζέιμς Κάμερον"],"description":"Χρόνια μετά την πρώτη ταινία, ο πρώην πεζοναύτης Τζέικ Σάλι και η οικογένειά του από τους Να'βι αναγκάζονται να αφήσουν το δάσος τους και να ζητήσουν καταφύγιο στις φυλές των υφάλων της Πανδώρας, για να γλιτώσουν από μια νέα ανθρώπινη απειλή.","fact":"Σε κάποιες υποβρύχιες σκηνές οι ηθοποιοί κρατούσαν πραγματικά την αναπνοή τους για πολλή ώρα, χωρίς καταδυτικό εξοπλισμό.","wiki_en":"Avatar: The Way of Water"},{"name":"Deadpool 2","emoji":"⚔️","meta":["ταινία υπερηρώων","2018","Ντέιβιντ Λιτς"],"description":"Ο κυνικός και αθεράπευτα φλύαρος μεταλλαγμένος μισθοφόρος Deadpool φτιάχνει δική του ομάδα υπερηρώων, για να προστατέψει έναν νεαρό μεταλλαγμένο από έναν αδίστακτο στρατιώτη-κυβόργιο που έρχεται από το μέλλον. Η συνέχεια κράτησε το μαύρο χιούμορ της πρώτης.","fact":"Η ταινία είναι γεμάτη αστεία σε βάρος άλλων σειρών υπερηρώων, ανάμεσά τους των συμπάντων της Marvel, της DC και των X-Men.","wiki_en":"Deadpool 2"},{"name":"Joker: Folie à Deux","emoji":"🃏","meta":["αστυνομικό δράμα","2024","Τοντ Φίλιπς"],"description":"Ο Άρθουρ Φλεκ, πια κρατούμενος στο ψυχιατρείο του Άρκαμ, γνωρίζει μια ασθενή, τη Χάρλεϊ Κουίνζελ, και τους δύο τους δένει μια αμοιβαία έλξη και μια κοινή περιφρόνηση για τον έξω κόσμο. Η συνέχεια της βραβευμένης ταινίας του 2019 έκανε την καταγωγή του κακού μιούζικαλ.","fact":"Σε αντίθεση με την πρώτη ταινία, μεγάλο μέρος της ιστορίας εδώ προχωρά μέσα από μουσικά νούμερα των πρωταγωνιστών.","wiki_en":"Joker: Folie à Deux"},{"name":"Cruella","emoji":"🐶","meta":["αστυνομικό δράμα","2021","Κρεγκ Γκιλέσπι"],"description":"Η προϊστορία της γνωστής κακιάς της Disney: η Εστέλα, μια ταλαντούχα αλλά μη αναγνωρισμένη σχεδιάστρια μόδας στο πανκ Λονδίνο της δεκαετίας του 1970, γίνεται σιγά σιγά η θρασεία και εκδικητική Κρουέλα ντε Βιλ. Η ταινία στηρίζεται στην αισθητική του πανκ ροκ.","fact":"Τα κοστούμια έφτιαξε η Τζένι Μπίβαν, που πήρε γι' αυτά Όσκαρ, εμπνεόμενη από τη μόδα της πανκ σκηνής του Λονδίνου.","wiki_en":"Cruella (film)"},{"name":"Πολύ Σκληρός για να Πεθάνει 2","emoji":"✈️","meta":["ταινία δράσης","1990","Ρένι Χάρλιν"],"description":"Ο αστυνομικός Τζον ΜακΚλέιν βρίσκεται ξανά σε λάθος μέρος τη λάθος στιγμή — αυτή τη φορά σε ένα αεροδρόμιο που καταλαμβάνουν ένοπλοι μισθοφόροι, απειλώντας εκατοντάδες επιβάτες σε αεροπλάνα που κάνουν κύκλους στον αέρα. Η δράση βγαίνει από τον ουρανοξύστη.","fact":"Όπως και η πρώτη ταινία, εξελίσσεται την παραμονή των Χριστουγέννων, κάτι που έγινε σήμα κατατεθέν όλης της σειράς.","wiki_en":"Die Hard 2"},{"name":"Πολύ Σκληρός για να Πεθάνει 3","emoji":"💣","meta":["ταινία δράσης","1995","Τζον ΜακΤίερναν"],"description":"Ένας μυστηριώδης τρομοκράτης βάζει τον εξαντλημένο Τζον ΜακΚλέιν να λύνει θανάσιμους γρίφους σε όλη τη Νέα Υόρκη, ώσπου εκείνος καταλαβαίνει ότι όλη αυτή η δοκιμασία είναι αντιπερισπασμός για ένα πολύ μεγαλύτερο έγκλημα. Η τρίτη ταινία έφερε πίσω τον αρχικό σκηνοθέτη.","fact":"Για πρώτη φορά στη σειρά, ο συνεργάτης του ΜακΚλέιν είναι πολίτης, ο Ζεύς, τον οποίο παίζει ο Σάμιουελ Λ. Τζάκσον.","wiki_en":"Die Hard with a Vengeance"},{"name":"Men in Black II","emoji":"👽","meta":["επιστημονική φαντασία","2002","Μπάρι Σόνενφελντ"],"description":"Ο πράκτορας Τζέι ξαναφέρνει στην υπηρεσία τον παλιό συνεργάτη του Κέι, χρόνια αφότου του έσβησαν τη μνήμη της δουλειάς, ώστε μαζί να σταματήσουν μια επικίνδυνη εξωγήινη που κυνηγά ένα αντικείμενο κρυμμένο στη Γη. Η κωμική ιστορία των φυλάκων του πλανήτη συνεχίζεται.","fact":"Επιστρέφουν τα αγαπημένα του κοινού εξωγήινα σκουλήκια, με αισθητά πιο πολύ χρόνο στην οθόνη αυτή τη φορά.","wiki_en":"Men in Black II"},{"name":"Godzilla vs. Kong","emoji":"🦖","meta":["επιστημονική φαντασία","2021","Άνταμ Γουίνγκαρντ"],"description":"Δύο θρυλικά γιγάντια τέρατα, η ερπετόμορφη Γκοτζίλα και ο τεράστιος πίθηκος Κονγκ, συγκρούονται σε μια επική μάχη, ενώ οι άνθρωποι ψάχνουν την αληθινή αιτία της ξαφνικής επιθετικότητας της Γκοτζίλα. Η ταινία ένωσε δύο μεγάλες σειρές σε ένα σύμπαν τεράτων.","fact":"Για τη μάχη με την Γκοτζίλα, ο Κονγκ μεγάλωσε αισθητά: σε αυτό το σύμπαν είναι πολύ πιο μεγάλος από ό,τι στη δική του ταινία.","wiki_en":"Godzilla vs. Kong"},{"name":"Jurassic World","emoji":"🦕","meta":["επιστημονική φαντασία","2015","Κόλιν Τρέβοροου"],"description":"Δύο δεκαετίες μετά το πρώτο «Ιουρασικό Πάρκο», στο νησί λειτουργεί κανονικό θεματικό πάρκο με δεινόσαυρους, ώσπου οι επιστήμονες φτιάχνουν ένα νέο υβριδικό θηρίο, που αποδεικνύεται πολύ πιο επικίνδυνο από ό,τι περίμεναν. Η επανεκκίνηση σάρωσε στα ταμεία.","fact":"Έσπασε το ρεκόρ εισπράξεων πρώτου τριημέρου στην εποχή της, όταν βγήκε το 2015.","wiki_en":"Jurassic World"},{"name":"Μην Κοιτάς Πάνω","emoji":"☄️","meta":["σατιρική κομεντί","2021","Άνταμ Μακέι"],"description":"Δύο άγνωστοι αστρονόμοι ανακαλύπτουν έναν κομήτη που θα καταστρέψει σίγουρα τη Γη και προσπαθούν να συνεννοηθούν με πολιτικούς και μέσα απορροφημένα στα δικά τους άμεσα συμφέροντα, όχι στην καταστροφή που έρχεται. Μια σάτιρα για το πώς καταναλώνουμε την πληροφορία.","fact":"Παρά την υπόθεση φαντασίας, οι δημιουργοί τη σχεδίασαν ως μεταφορά της αδιαφορίας της κοινωνίας για την κλιματική αλλαγή.","wiki_en":"Don't Look Up"},{"name":"Green Book","emoji":"🚗","meta":["δράμα","2018","Πίτερ Φάρελι"],"description":"Ένας τραχύς πορτιέρης από το Μπρονξ πιάνει δουλειά οδηγός και σωματοφύλακας ενός εκλεπτυσμένου μαύρου πιανίστα που κάνει περιοδεία στον ρατσιστικό Νότο των ΗΠΑ της δεκαετίας του 1960, και στο μακρύ ταξίδι γεννιέται μια απρόσμενη φιλία. Πήρε Όσκαρ καλύτερης ταινίας.","fact":"Ο τίτλος παραπέμπει στον υπαρκτό οδηγό Green Book, που τότε έδειχνε στους μαύρους ταξιδιώτες πού ήταν ασφαλείς στον Νότο.","wiki_en":"Green Book","wiki_ru":"Зелёная книга (фильм)"},{"name":"1917","emoji":"🪖","meta":["πολεμικό δράμα","2019","Σαμ Μέντες"],"description":"Δύο νέοι Βρετανοί στρατιώτες του Α' Παγκοσμίου Πολέμου παίρνουν εντολή να μεταφέρουν σε γειτονικό σύνταγμα το μήνυμα που ακυρώνει μια επίθεση, για να σώσουν χιλιάδες συντρόφους από γερμανική παγίδα. Ο Σαμ Μέντες τη γύρισε ώστε να μοιάζει με ένα αδιάκοπο πλάνο.","fact":"Για να κρατηθεί η ψευδαίσθηση του συνεχούς πλάνου, το συνεργείο πρόβαρε τις δυσκολότερες σκηνές με κινούμενη κάμερα για μήνες.","wiki_en":"1917 (2019 film)"},{"name":"Ο Αρειανός","emoji":"🚀","meta":["επιστημονική φαντασία","2015","Ρίντλεϊ Σκοτ"],"description":"Ένας αστροναύτης μένει κατά λάθος πίσω στον Άρη, όταν το πλήρωμα εκκενώνει εν μέσω αμμοθύελλας, και πρέπει να επιβιώσει μόνος σε έναν εχθρικό πλανήτη, με μόνα εργαλεία τις επιστημονικές του γνώσεις και την εφευρετικότητά του. Από το μυθιστόρημα του Άντι Γουίαρ.","fact":"Οι σεναριογράφοι και οι σύμβουλοι δούλεψαν με αληθινούς ειδικούς της NASA, ώστε οι τρόποι επιβίωσης του ήρωα να είναι ρεαλιστικοί.","wiki_en":"The Martian (film)"},{"name":"Gravity","emoji":"🛰️","meta":["επιστημονική φαντασία","2013","Αλφόνσο Κουαρόν"],"description":"Μια καταιγίδα συντριμμιών καταστρέφει το σκάφος στη διάρκεια ενός διαστημικού περιπάτου, και μια πρωτάρα αστροναύτης μένει μόνη στην τροχιά, να παλεύει για τη ζωή της στην έλλειψη βαρύτητας με το οξυγόνο να λιγοστεύει. Ο Κουαρόν εντυπωσίασε με τα μακριά πλάνα του.","fact":"Για την ψευδαίσθηση της απουσίας βαρύτητας, οι ηθοποιοί μπήκαν σε ειδική κατασκευή με ελεγχόμενο φωτισμό που μιμούνταν το διάστημα.","wiki_en":"Gravity (2013 film)"},{"name":"Scream","emoji":"🔪","meta":["ταινία τρόμου","1996","Γουές Κρέιβεν"],"description":"Μια ήσυχη αμερικανική πόλη χτυπιέται από μια σειρά βάναυσων φόνων, που κάνει ένας μασκοφόρος δολοφόνος ο οποίος ξέρει απέξω τους κανόνες του κλασικού σλάσερ και εξετάζει πάνω σε αυτούς τα θύματά του. Ο Γουές Κρέιβεν αναβίωσε το είδος κοροϊδεύοντας τα κλισέ του.","fact":"Η μάσκα του δολοφόνου έγινε μια από τις πιο αναγνωρίσιμες εικόνες της ποπ κουλτούρας, μαζί και στις στολές του Χαλοουίν.","wiki_en":"Scream (1996 film)"},{"name":"Halloween","emoji":"🔪","meta":["ταινία τρόμου","1978","Τζον Κάρπεντερ"],"description":"Χρόνια αφότου σκότωσε παιδί την αδελφή του, ο ψυχικά ασταθής Μάικλ Μάιερς δραπετεύει από το ψυχιατρείο και γυρίζει στην πόλη του τη νύχτα του Χαλοουίν, για να κυνηγήσει τους έφηβους της γειτονιάς. Η μικρού προϋπολογισμού ταινία θεμελίωσε το σλάσερ.","fact":"Το περίφημο ανατριχιαστικό μουσικό θέμα το έγραψε ο ίδιος ο Τζον Κάρπεντερ και έγινε από τις πιο αναγνωρίσιμες μελωδίες του τρόμου.","wiki_en":"Halloween (1978 film)"},{"name":"Παρασκευή και 13","emoji":"🏕️","meta":["ταινία τρόμου","1980","Σον Κάνινγκχαμ"],"description":"Μια ομάδα νεαρών ομαδαρχών, που ετοιμάζουν να ξανανοίξουν μια κατασκήνωση εγκαταλειμμένη μετά από τραγωδία, ξεκληρίζονται ένας ένας από έναν άγνωστο δολοφόνο, που εκδικείται για ένα παιδί που πνίγηκε παλιά στην ίδια λίμνη. Ξεκίνησε μια μακρόβια σειρά τρόμου.","fact":"Ο Τζέισον Βούρχις, το σύμβολο της σειράς, μόλις εμφανίζεται στην πρώτη ταινία, και η περίφημη μάσκα του χόκεϊ έρχεται στην τρίτη.","wiki_en":"Friday the 13th (1980 film)"},{"name":"Εφιάλτης στον Δρόμο με τις Λεύκες","emoji":"🧤","meta":["ταινία τρόμου","1984","Γουές Κρέιβεν"],"description":"Ένας καμένος δολοφόνος με κοκκινοπράσινο ριγέ πουλόβερ και λεπίδες στη θέση των δαχτύλων κυνηγά τους έφηβους μιας γειτονιάς μέσα στα όνειρά τους, από όπου τα θύματά του δεν ξυπνούν ζωντανά. Ο Γουές Κρέιβεν χάρισε στον τρόμο τον Φρέντι Κρούγκερ.","fact":"Ο Ρόμπερτ Ένγκλουντ, που έπαιξε τον Φρέντι Κρούγκερ, τον ενσάρκωσε για δεκαετίες σε σχεδόν όλες τις ταινίες και τις σειρές του κύκλου.","wiki_en":"A Nightmare on Elm Street"},{"name":"Saw","emoji":"🩸","meta":["ταινία τρόμου","2004","Τζέιμς Ουάν"],"description":"Δύο άντρες που δεν γνωρίζονται ξυπνούν αλυσοδεμένοι σε ένα βρόμικο μπάνιο και ανακαλύπτουν ότι είναι παίκτες στο θανατερό παιχνίδι ενός μυστηριώδους δολοφόνου, που δοκιμάζει τα θύματά του με περίτεχνες ηθικές και σωματικές παγίδες. Το φτηνό ντεμπούτο του Τζέιμς Ουάν.","fact":"Γυρίστηκε σε δεκαοχτώ μόνο μέρες με ελάχιστο προϋπολογισμό, και παρ' όλα αυτά έβγαλε πολλαπλάσια χρήματα παγκοσμίως.","wiki_en":"Saw (2004 film)"},{"name":"It","emoji":"🎈","meta":["ταινία τρόμου","2017","Άντι Μουσκιέτι"],"description":"Μια ομάδα περιθωριοποιημένων παιδιών σε μια μικρή αμερικανική πόλη ενώνεται απέναντι σε ένα αρχαίο κακό, που παίρνει τη μορφή των χειρότερων φόβων τους και εμφανίζεται συνήθως ως ο σατανικός κλόουν Πεννιγουάιζ. Από τις εμπορικότερες ταινίες τρόμου στην ιστορία.","fact":"Ο Πεννιγουάιζ του Μπιλ Σκάρσγκαρντ έγινε μια από τις πιο αναγνωρίσιμες ενσαρκώσεις κακού του Στίβεν Κινγκ στο σινεμά.","wiki_en":"It (2017 film)"},{"name":"A Quiet Place","emoji":"🤫","meta":["ταινία τρόμου","2018","Τζον Κραζίνσκι"],"description":"Μια οικογένεια επιβιώνει σε έναν κόσμο κατακτημένο από τυφλά πλάσματα με υπερευαίσθητη ακοή, και πρέπει να μιλά με νοήματα και να κινείται σε σχεδόν απόλυτη σιωπή, για να μην την εντοπίσουν. Ο Τζον Κραζίνσκι έστησε την ταινία με ελάχιστους διαλόγους και ήχους.","fact":"Μεγάλο μέρος των διαλόγων περνά μέσα από την αμερικανική νοηματική γλώσσα, αντί από τον λόγο.","wiki_en":"A Quiet Place"},{"name":"The Conjuring","emoji":"🕯️","meta":["ταινία τρόμου","2013","Τζέιμς Ουάν"],"description":"Ένα ζευγάρι μετακομίζει σε μια παλιά αγροικία στο Ρόουντ Άιλαντ, όπου συμβαίνουν όλο και πιο τρομακτικά πράγματα, και αναγκάζεται να καλέσει τους γνωστούς ερευνητές του παραφυσικού, τους συζύγους Γουόρεν. Βασίζεται σε αληθινή υπόθεσή τους και ξεκίνησε ένα σύμπαν τρόμου.","fact":"Πήρε ακατάλληλη σήμανση όχι για το αίμα και τη βία, που σχεδόν δεν υπάρχουν, αλλά για την τρομακτική της ατμόσφαιρα.","wiki_en":"The Conjuring"},{"name":"Insidious","emoji":"👻","meta":["ταινία τρόμου","2010","Τζέιμς Ουάν"],"description":"Αφότου ο γιος τους πέφτει μυστηριωδώς σε κώμα, μια οικογένεια βρίσκεται μπροστά σε όλο και πιο τρομακτικά φαινόμενα στο σπίτι και καλεί μια μέντιουμ, που τα εξηγεί ως σύνδεση του παιδιού με ένα επέκεινα. Το φτηνό γύρισμα του Τζέιμς Ουάν απέδωσε τρελά κέρδη.","fact":"Εδώ εμφανίζεται πρώτη φορά η μέντιουμ Ελίζ Ρέινιερ, που έγινε μετά κεντρική μορφή όλης της σειράς, μαζί και των προεισαγωγών.","wiki_en":"Insidious (film)"},{"name":"Get Out","emoji":"🌀","meta":["θρίλερ τρόμου","2017","Τζόρνταν Πιλ"],"description":"Ένας νέος μαύρος φωτογράφος πηγαίνει στην εξοχή να γνωρίσει την οικογένεια της λευκής κοπέλας του και προσέχει όλο και πιο πολλά παράξενα στη συμπεριφορά των οικοδεσποτών και των καλεσμένων τους, που κρύβουν κάτι απαίσιο. Τρόμος και κοφτερή φυλετική σάτιρα μαζί.","fact":"Πήρε Όσκαρ πρωτότυπου σεναρίου, κάτι σπάνιο για ταινία που τυπικά ανήκει στον τρόμο.","wiki_en":"Get Out"},{"name":"Σικάγο","emoji":"🎷","meta":["μιούζικαλ","2002","Ρομπ Μάρσαλ"],"description":"Μια επίδοξη τραγουδίστρια και μια καταξιωμένη σταρ του βαριετέ, κατηγορούμενες και οι δύο για φόνο, ανταγωνίζονται για την προσοχή του κοινού και για έναν επιτήδειο δικηγόρο στο τζαζ Σικάγο της δεκαετίας του 1920, όπου το σκάνδαλο είναι εισιτήριο για τη δόξα.","fact":"Τα μουσικά νούμερα είναι στημένα σαν φανταστικές παραστάσεις που τρέχουν στο μυαλό της ηρωίδας παράλληλα με τα αληθινά γεγονότα.","wiki_en":"Chicago (2002 film)"},{"name":"Moulin Rouge!","emoji":"🎭","meta":["μιούζικαλ","2001","Μπαζ Λούρμαν"],"description":"Ένας νέος Άγγλος ποιητής στο μποέμ Παρίσι των τελών του 19ου αιώνα ερωτεύεται το αστέρι του διάσημου καμπαρέ Μουλέν Ρουζ, και ο έρωτάς τους ξετυλίγεται μέσα σε εκτυφλωτικά νούμερα που δένουν ποπ επιτυχίες με κλασικές μελωδίες. Γρήγορο, εκκεντρικό και φανταχτερό σινεμά.","fact":"Η μουσική ανακατεύει κλασικά οπερατικά μέρη με διασκευές σύγχρονων ποπ τραγουδιών πολλών δεκαετιών, μέσα στα ίδια νούμερα.","wiki_en":"Moulin Rouge!"},{"name":"Bohemian Rhapsody","emoji":"🎤","meta":["μουσική βιογραφία","2018","Μπράιαν Σίνγκερ"],"description":"Η ταινία παρακολουθεί τους Queen από τα πρώτα μικρά κλαμπ μέχρι τη θέση τους ως ένα από τα μεγαλύτερα ροκ συγκροτήματα του κόσμου, με το βλέμμα κυρίως στην έντονη και αντιφατική μορφή του Φρέντι Μέρκιουρι. Κλείνει με την αναπαράσταση της εμφάνισής τους στο Live Aid.","fact":"Ο Ράμι Μάλεκ πήρε Όσκαρ ως Φρέντι Μέρκιουρι, ρόλος για τον οποίο προετοιμάστηκε πολύ, μελετώντας την κίνηση και το τραγούδι του.","wiki_en":"Bohemian Rhapsody (film)"},{"name":"Rocketman","emoji":"🕶️","meta":["μουσική βιογραφία","2019","Ντέξτερ Φλέτσερ"],"description":"Ένα βιογραφικό μιούζικαλ για τον δρόμο του Έλτον Τζον, από ένα ντροπαλό παιδί των προαστίων του Λονδίνου ως ένα από τα πιο εξεζητημένα αστέρια της ποπ, μέσα από τα δικά του διάσημα τραγούδια. Σε αντίθεση με πολλές μουσικές βιογραφίες, δένει ανοιχτά την αλήθεια με τη φαντασία.","fact":"Όλα τα φωνητικά της ταινίας τα τραγούδησε ο ίδιος ο Τάρον Έγκερτον, και όχι ο αρχικός ερμηνευτής των τραγουδιών.","wiki_en":"Rocketman (film)"},{"name":"Οι Άθλιοι","emoji":"🇫🇷","meta":["μιούζικαλ","2012","Τομ Χούπερ"],"description":"Ο πρώην κατάδικος Ζαν Βαλζάν, που παρέβη τους όρους της αποφυλάκισής του, προσπαθεί να ξεκινήσει μια τίμια ζωή, αλλά ο ακλόνητος επιθεωρητής Ζαβέρ δεν τον αφήνει, και όλα παίζονται με φόντο τις λαϊκές εξεγέρσεις του Παρισιού του 19ου αιώνα. Τα τραγούδια ηχογραφήθηκαν ζωντανά.","fact":"Η Αν Χάθαγουεϊ πήρε Όσκαρ ως Φαντίν, και το μεγάλο της τραγούδι γυρίστηκε σε ένα αδιάκοπο κοντινό πλάνο.","wiki_en":"Les Misérables (2012 film)"}];
